FUNCTION ACOSH:REAL
	VAR_INPUT
		X :	REAL;
	END_VAR
	ACOSH := LN(SQRT(X * X - 1.0) + X);

END_FUNCTION

PROGRAM program0
  VAR
    LocalVar0 : REAL;
    LocalOUT  : REAL;
  END_VAR

  LocalOUT := ACOSH(LocalVar0);
END_PROGRAM

FUNCTION ACOTH:REAL
	VAR_INPUT
		x :	REAL;
	END_VAR

	ACOTH := LN((x+1.0)/(x-1.0))*0.5;

END_FUNCTION

PROGRAM program0
  VAR
    LocalVar0 : REAL;
    LocalOUT  : REAL;
  END_VAR

  LocalOUT := ACOTH(LocalVar0);
END_PROGRAM

