FUNCTION_BLOCK AIN1

	VAR_INPUT
		IN :	DWORD;
		SIGN_BIT :	INT := 255;
		ERROR_BIT :	INT := 255;
		ERROR_CODE_EN :	BOOL := FALSE;
		ERROR_CODE :	DWORD;
		OVERFLOW_BIT :	INT := 255;
		OVERFLOW_CODE_EN :	BOOL;
		OVERFLOW_CODE :	DWORD;
		BIT_0 :	INT;
		BIT_N :	INT := 31;
		OUT_MIN :	REAL;
		OUT_MAX :	REAL := 10.0;
		CODE_MIN :	DWORD;
		CODE_MAX :	DWORD := DWORD#16#FFFFFFFF;
		ERROR_OUTPUT :	REAL;
		OVERFLOW_OUTPUT :	REAL := 10.0;
	END_VAR

	VAR_OUTPUT
		OUT :	REAL;
		SIGN :	BOOL;
		ERROR :	BOOL;
		OVERFLOW :	BOOL;
	END_VAR

	VAR
		tb :	DWORD;
	END_VAR

	ERROR := ((SHR(IN,ERROR_BIT) AND DWORD#16#0000_0001) = DWORD#1) OR (ERROR_CODE_EN AND ERROR_CODE = IN);
	IF ERROR THEN
		OUT := ERROR_OUTPUT;
		RETURN;
	END_IF;

	tb := SHR(SHL(IN, 31 - BIT_N), 31 - BIT_N + BIT_0);

	OVERFLOW := ((SHR(IN,OVERFLOW_BIT) AND DWORD#16#0000_0001) = DWORD#1) OR (OVERFLOW_CODE_EN AND OVERFLOW_CODE = IN) OR (tb < CODE_MIN OR tb > CODE_MAX);
	IF OVERFLOW THEN
		OUT := OVERFLOW_OUTPUT;
		RETURN;
	END_IF;


	SIGN := (SHR(IN,SIGN_BIT) AND DWORD#16#0000_0001) = DWORD#1;

	OUT := (UDINT_TO_REAL(DWORD_TO_UDINT(tb) - DWORD_TO_UDINT(CODE_MIN)) * (OUT_MAX - OUT_MIN) / UDINT_TO_REAL(DWORD_TO_UDINT(CODE_MAX) - DWORD_TO_UDINT(CODE_MIN)) + OUT_MIN);
	IF SIGN THEN OUT := OUT * -1.0; END_IF;


	(* extract ERROR bit *)
	ERROR := ((SHR(IN,ERROR_BIT) AND DWORD#16#0000_0001) = DWORD#1) OR (ERROR_CODE_EN AND ERROR_CODE = IN);
	IF ERROR THEN
		OUT := ERROR_OUTPUT;
		RETURN;
	END_IF;

	(* strip off the data input *)
	tb := SHR(SHL(IN, 31 - BIT_N), 31 - BIT_N + BIT_0);

	(* extract OVERFLOW bit *)
	OVERFLOW := ((SHR(IN,OVERFLOW_BIT) AND DWORD#16#0000_0001) = DWORD#1) OR (OVERFLOW_CODE_EN AND OVERFLOW_CODE = IN) OR (tb < CODE_MIN OR tb > CODE_MAX);
	IF OVERFLOW THEN
		OUT := OVERFLOW_OUTPUT;
		RETURN;
	END_IF;

	(* extract SIGN bit *)
	SIGN := (SHR(IN,SIGN_BIT) AND DWORD#16#0000_0001) = DWORD#1;

	(* convert IN to OUT *)
	OUT := (UDINT_TO_REAL(DWORD_TO_UDINT(tb) - DWORD_TO_UDINT(CODE_MIN)) * (OUT_MAX - OUT_MIN) / UDINT_TO_REAL(DWORD_TO_UDINT(CODE_MAX) - DWORD_TO_UDINT(CODE_MIN)) + OUT_MIN);
	IF SIGN THEN OUT := OUT * - 1.0; END_IF;

END_FUNCTION_BLOCK

PROGRAM program0
  VAR
	IN               :	DWORD;
	SIGN_BIT         :	INT ;
	ERROR_BIT        :	INT ;
	ERROR_CODE_EN    :	BOOL ;
	ERROR_CODE       :	DWORD;
	OVERFLOW_BIT     :	INT ;
	OVERFLOW_CODE_EN :	BOOL;
	OVERFLOW_CODE    :	DWORD;
	BIT_0            :	INT;
	BIT_N            :	INT; 
	OUT_MIN          :	REAL;
	OUT_MAX          :	REAL ;
	CODE_MIN         :	DWORD;
	CODE_MAX         :	DWORD ;
	ERROR_OUTPUT     :	REAL;
	OVERFLOW_OUTPUT  :	REAL ;

	OUT      :	REAL;
	SIGN     :	BOOL;
	ERROR    :	BOOL;
	OVERFLOW :	BOOL;

	func_block : AIN1;
  END_VAR
	func_block.IN               :=IN              ;
	func_block.SIGN_BIT         :=SIGN_BIT        ;
	func_block.ERROR_BIT        :=ERROR_BIT       ;
	func_block.ERROR_CODE_EN    :=ERROR_CODE_EN   ;
	func_block.ERROR_CODE       :=ERROR_CODE      ;
	func_block.OVERFLOW_BIT     :=OVERFLOW_BIT    ;
	func_block.OVERFLOW_CODE_EN :=OVERFLOW_CODE_EN;
	func_block.OVERFLOW_CODE    :=OVERFLOW_CODE   ;
	func_block.BIT_0            :=BIT_0           ;
	func_block.BIT_N            :=BIT_N           ;
	func_block.OUT_MIN          :=OUT_MIN         ;
	func_block.OUT_MAX          :=OUT_MAX         ;
	func_block.CODE_MIN         :=CODE_MIN        ;
	func_block.CODE_MAX         :=CODE_MAX        ;
	func_block.ERROR_OUTPUT     :=ERROR_OUTPUT    ;
	func_block.OVERFLOW_OUTPUT  :=OVERFLOW_OUTPUT ;

	func_block();
	OUT     := func_block.OUT     ;
	SIGN    := func_block.SIGN    ;
	ERROR   := func_block.ERROR   ;
	OVERFLOW:= func_block.OVERFLOW;
END_PROGRAM

FUNCTION_BLOCK ALARM_2
	VAR_INPUT
		X :	REAL;
		LO_1 :	REAL;
		HI_1 :	REAL;
		LO_2 :	REAL;
		HI_2 :	REAL;
		HYS :	REAL;
	END_VAR

	VAR_OUTPUT
		Q1_LO :	BOOL;
		Q1_HI :	BOOL;
		Q2_LO :	BOOL;
		Q2_HI :	BOOL;
	END_VAR

	VAR
		tmp :	REAL;
	END_VAR

	tmp := X - HYS * 0.5;
	IF tmp > LO_1 THEN Q1_LO := FALSE; END_IF;
	IF tmp > LO_2 THEN Q2_LO := FALSE; END_IF;
	IF tmp > HI_1 THEN Q1_HI := TRUE; END_IF;
	IF tmp > HI_2 THEN Q2_HI := TRUE; END_IF;
	tmp := tmp + HYS;
	IF tmp < LO_1 THEN Q1_LO := TRUE; END_IF;
	IF tmp < LO_2 THEN Q2_LO := TRUE; END_IF;
	IF tmp < HI_1 THEN Q1_HI := FALSE; END_IF;
	IF tmp < HI_2 THEN Q2_HI := FALSE; END_IF;

END_FUNCTION_BLOCK

PROGRAM program0
	VAR
	    LocalVar0 : REAL;
		LocalVaR1  : REAL;
		LocalVaR2 : REAL;
		LocalVar3 : REAL;
		LocalVar4 : REAL;
		LocalVar5 : REAL;
		LocalOUT1  : BOOL;
		LocalOUT2  : BOOL;
		LocalOUT3  : BOOL;
		LocalOUT4  : BOOL;
		func_block : ALARM_2;
  	END_VAR
	func_block.X := LocalVar0;
	func_block.LO_1 := LocalVaR1 ;
	func_block.HI_1 := LocalVaR2;
	func_block.LO_2 := LocalVar3;
	func_block.HI_2 := LocalVar4;
	func_block.HYS := LocalVar5;
	func_block();
	LocalOUT1 := func_block.Q1_LO;
	LocalOUT2 := func_block.Q1_HI;
	LocalOUT3 := func_block.Q2_LO;
	LocalOUT4 := func_block.Q2_HI;
END_PROGRAM

