	END_VAR

	VAR_OUTPUT
		ARRAY_HAV :	REAL;
	END_VAR

	VAR
		i :	INT;
		STOP :	INT;
	END_VAR

	STOP :=LIMIT_INT(1,UINT_TO_INT(SIZE),1000);
	ARRAY_HAV := 0.0;
	FOR i := 1 TO STOP DO
		IF PT[i] <> 0.0 THEN
			ARRAY_HAV := ARRAY_HAV + 1.0/PT[i];
		ELSE
			ARRAY_HAV := 0.0;
			RETURN;
		END_IF;
	END_FOR;
	ARRAY_HAV := INT_TO_REAL(STOP) / ARRAY_HAV;
END_FUNCTION_BLOCK

