TYPE
	oscat_PT_ARRAY: ARRAY [1..100] OF REAL;
	oscat_stack_array: ARRAY [1..32]   OF INT;
END_TYPE

FUNCTION _INT_TO_UDINT:UDINT
	VAR_INPUT
		IN :	INT;
	END_VAR

	_INT_TO_UDINT := DINT_TO_UDINT(INT_TO_DINT(IN));
END_FUNCTION

FUNCTION BIT_OF_DWORD:BOOL
	VAR_INPUT
		IN :	DWORD;
		N :	INT;
	END_VAR
	BIT_OF_DWORD := (SHR(IN,N) AND DWORD#1) > DWORD#0;
END_FUNCTION

FUNCTION EVEN:BOOL
	VAR_INPUT
		IN :	DINT;
	END_VAR
	EVEN := NOT BIT_OF_DWORD(DINT_TO_DWORD(IN),0);
END_FUNCTION

FUNCTION_BLOCK _ARRAY_SORT_Block
	VAR_IN_OUT
		PT :	oscat_PT_ARRAY;
	END_VAR

	VAR_INPUT
		SIZE :	UINT;
	END_VAR

	VAR_OUTPUT
		_ARRAY_SORT :BOOL;
	END_VAR

	VAR
		stack_count :	INT;
		stack :	oscat_stack_array;
		links :	INT;
		rechts :	INT;
		pivot :	REAL;
		i :	INT;
		j :	INT;
		ende_innen :	BOOL;
		ende_aussen :	BOOL;
		tmp :	REAL;
		x :	INT;
	END_VAR


	links := 1;
	rechts := DWORD_TO_INT(SHR(UINT_TO_DWORD(SIZE),2)); 
	stack_count := 1; 

	WHILE NOT ende_aussen DO
		IF links < rechts THEN
			x := DWORD_TO_INT(SHR(UDINT_TO_DWORD(_INT_TO_UDINT(rechts)+ _INT_TO_UDINT(links)),1));
			pivot := PT[x];
			i := links - 1;
			j := rechts + 1;

			ende_innen := FALSE;
			REPEAT
				REPEAT	i := i+1;	UNTIL (PT[i] >= pivot) OR NOT (i < rechts)	END_REPEAT;
				REPEAT	j := j-1;	UNTIL (PT[j] <= pivot) OR NOT (j > links)	END_REPEAT;
				IF i >= j THEN
					ende_innen := TRUE;
				ELSE
					tmp := PT[j];
					PT[j] := PT[i];
					PT[i] := tmp;
				END_IF;

			UNTIL ende_innen END_REPEAT;

			stack[stack_count] := rechts;	
			IF stack_count < 32 THEN
				stack_count := stack_count +1;
			ELSE
				ende_aussen := TRUE;
				_ARRAY_SORT := FALSE;				
			END_IF;
			rechts := MAX(links, i-1);

		ELSE
			IF stack_count = 1 THEN
				ende_aussen := TRUE;
			ELSE
				links := rechts+1;
				stack_count := stack_count - 1;	
				rechts:= stack[stack_count];
			END_IF;
		END_IF;
	END_WHILE;

	_ARRAY_SORT := TRUE;			
END_FUNCTION_BLOCK


FUNCTION_BLOCK _ARRAY_MEDIAN_Block

	VAR_IN_OUT
		PT :	oscat_PT_ARRAY;
	END_VAR

	VAR_INPUT
		SIZE :	UINT;
	END_VAR

	VAR_OUTPUT
		ARRAY_MEDIAN :	REAL;
	END_VAR

	VAR
		i :	INT;
		i2 :	INT;
		STOP :	INT;
		array_sort :	_ARRAY_SORT_Block;
	END_VAR


	(* Array sortieren *)
	array_sort.SIZE := SIZE;
	array_sort(PT   := PT);
	PT := array_sort.PT;

	STOP :=LIMIT_INT(1,UINT_TO_INT(SIZE),1000);
	IF EVEN(INT_TO_DINT(STOP)) THEN
	    i := WORD_TO_INT(SHR(INT_TO_WORD(STOP),1));
	    i2 := i+1;
		ARRAY_MEDIAN := (PT[i] + PT[i2]) * 0.5;
	ELSE
	    i := WORD_TO_INT(SHR(INT_TO_WORD(STOP),1))+1;
		ARRAY_MEDIAN := PT[i];
	END_IF;

END_FUNCTION_BLOCK


PROGRAM program0
  VAR
    LocalVar0 : oscat_PT_ARRAY;
    LocalVaR1  : UINT;
	LocalOUT  : REAL;
	func_block : _ARRAY_MEDIAN_Block;
  END_VAR
	func_block(PT := LocalVar0,SIZE := LocalVaR1 );
	LocalOUT := func_block.ARRAY_MEDIAN;
	LocalVar0 := func_block.PT;

END_PROGRAM

TYPE
	oscat_PT_ARRAY: ARRAY [1..100] OF REAL;
END_TYPE

FUNCTION_BLOCK ARRAY_MIN_Block
	VAR_IN_OUT
		PT :	oscat_PT_ARRAY;
	END_VAR

	VAR_INPUT
		SIZE :	UINT;
	END_VAR

	VAR_OUTPUT
		ARRAY_MIN :	REAL;
	END_VAR

	VAR
		i :	INT;
		STOP :	INT;
	END_VAR


	STOP :=LIMIT_INT(1,UINT_TO_INT(SIZE),1000);

	ARRAY_MIN := PT[1];
	FOR i := 2 TO STOP DO
		IF PT[i] < ARRAY_MIN THEN ARRAY_MIN := PT[i]; END_IF;
	END_FOR;

END_FUNCTION_BLOCK
