FUNCTION_BLOCK BAR_GRAPH
	VAR_INPUT
		X :	REAL;
		RST :	BOOL;
		TRIGGER_LOW :	REAL;
		TRIGGER_HIGH :	REAL;
		ALARM_LOW :	BOOL;
		ALARM_HIGH :	BOOL;
		LOG_SCALE :	BOOL;
	END_VAR


	VAR_OUTPUT
		LOW :	BOOL;
		Q1 :	BOOL;
		Q2 :	BOOL;
		Q3 :	BOOL;
		Q4 :	BOOL;
		Q5 :	BOOL;
		Q6 :	BOOL;
		HIGH :	BOOL;
		ALARM :	BOOL;
		STATUS :	BYTE;
	END_VAR


	VAR
		init :	BOOL;
		T1 :	REAL;
		T2 :	REAL;
		T3 :	REAL;
		T4 :	REAL;
		T5 :	REAL;
		temp :	REAL;
	END_VAR

	IF NOT init THEN
		init := TRUE;
		IF LOG_SCALE THEN
			temp := EXP(LN(TRIGGER_HIGH / TRIGGER_LOW) * 0.166666666666666666666);
			T1 := TRIGGER_LOW * temp;
			T2 := T1 * temp;
			T3 := T2 * temp;
			T4 := T3 * temp;
			T5 := T4 * temp;
		ELSE
			temp := (TRIGGER_HIGH - TRIGGER_LOW) * 0.142857142;
			T1 := TRIGGER_LOW + temp;
			T2 := T1 + temp;
			T3 := T2 + temp;
			T4 := T3 + temp;
			T5 := T4 + temp;
		END_IF;
	END_IF;

	Q1 := FALSE;
	Q2 := FALSE;
	Q3 := FALSE;
	Q4 := FALSE;
	Q5 := FALSE;
	Q6 := FALSE;
	STATUS := BYTE#110;

	IF NOT ALARM_LOW THEN LOW := FALSE; END_IF;
	IF NOT ALARM_HIGH THEN HIGH := FALSE; END_IF;
	IF RST THEN
		ALARM := FALSE;
		LOW := FALSE;
		HIGH := FALSE;
	END_IF;

	IF X < TRIGGER_LOW THEN
		LOW := TRUE;
		STATUS := BYTE#111;
		IF ALARM_LOW THEN
			ALARM := TRUE;
			STATUS := BYTE#1;
		END_IF;
	ELSIF X < T1 THEN
		Q1 := TRUE;
	ELSIF X < T2 THEN
		Q2 := TRUE;
	ELSIF X < T3 THEN
		Q3 := TRUE;
	ELSIF X < T4 THEN
		Q4 := TRUE;
	ELSIF X < T5 THEN
		Q5 := TRUE;
	ELSIF X < TRIGGER_HIGH THEN
		Q6 := TRUE;
	ELSE
		HIGH := TRUE;
		STATUS := BYTE#112;
		IF ALARM_HIGH THEN
			ALARM := TRUE;
			STATUS := BYTE#2;
		END_IF;
	END_IF;

END_FUNCTION_BLOCK

