FUNCTION_BLOCK ACTUATOR_3P_Block

	VAR_INPUT
		IN :	BYTE;
		TEST :	BOOL;
		ARE :	BOOL := TRUE;
		END_POS :	BOOL;
		T_RUN :	TIME := T#60s;
		T_EXT :	TIME := T#10s;
		T_CAL :	TIME := T#600s;
		T_DIAG :	TIME := T#10d;
		SWITCH_AVAIL :	BOOL;
	END_VAR


	VAR_OUTPUT
		OUT1 :	BOOL;
		OUT2 :	BOOL;
		POS :	BYTE;
		ERROR :	BOOL;
		STATUS :	BYTE;
	END_VAR


	VAR_IN_OUT
		ARX :	BOOL;
	END_VAR

	VAR
		TX :	TIME;
		_ramp :	_RMP_NEXT_Block;
		next_cal :	TIME;
		next_diag :	TIME;
		last :	TIME;
		START :	TIME;
		T_PLC_MS :	T_PLC_MS_block;
	END_VAR

	T_PLC_MS();
	TX := UDINT_TO_TIME(T_PLC_MS.T_PLC_MS);

	IF TEST THEN
		STATUS := BYTE#103;
		START := TX;
		ARX := TRUE;
	END_IF;

	CASE _BYTE_TO_INT(STATUS) OF
		0:	
			IF ARE AND NOT ARX THEN
				STATUS := BYTE#103;
				START := TX;
				ARX := TRUE;
			END_IF;

		100:
			IF T_DIAG > T#0s AND TX > next_diag AND ARE AND NOT ARX THEN
					STATUS := BYTE#103;
					START := TX;
					ARX := TRUE;

			ELSIF T_CAL > T#0s AND TX > next_cal AND ARE AND NOT ARX THEN
				IF POS > BYTE#127 THEN
					OUT1 := TRUE;
					OUT2 := FALSE;
					_ramp.IN := BYTE#255;
					ARX := TRUE;
				ELSE
					OUT1 := FALSE;
					OUT2 := TRUE;
					_ramp.IN := BYTE#0;
					ARX := TRUE;
				END_IF;
				STATUS := BYTE#101;
				START := TX;
			ELSE
				IF NOT(OUT1 OR OUT2) THEN next_cal := next_cal + (TX-last); END_IF;
				_ramp.IN := IN;
			END_IF;

		101:
			IF TX - START < T_EXT THEN
				next_cal := TX + T_CAL;
			ELSIF SWITCH_AVAIL AND END_POS THEN
				STATUS := BYTE#100;
				ARX := FALSE;
			ELSIF TX - START > T_EXT + T_RUN THEN
				ERROR := SWITCH_AVAIL;
				ARX := FALSE;
			END_IF;

		103:	
			IF TX - START < T_EXT THEN
				ERROR := FALSE;
				_ramp.TR := T_RUN;
				_ramp.TF := T_RUN;
				OUT1 := TRUE;
				OUT2 := FALSE;
				_ramp.IN := BYTE#255;
			ELSIF SWITCH_AVAIL AND END_POS THEN
				_ramp.TR := TX - START;
				STATUS := BYTE#104;
			ELSIF TX - START > T_EXT + T_RUN THEN
				ERROR := SWITCH_AVAIL;
				STATUS := BYTE#104;
				START := TX;
			END_IF;

		104:	
			IF TX - START < T_ext THEN
				OUT1 := FALSE;
				OUT2 := TRUE;
				_ramp.IN := BYTE#0;
				next_diag := TX + T_DIAG;
			ELSIF SWITCH_AVAIL AND END_POS THEN
				_ramp.TR := TX - START;
				IF DINT_TO_TIME(ABS(TIME_TO_DINT(_ramp.TR) - TIME_TO_DINT(_ramp.TF)) * DINT#10) > T_RUN THEN ERROR := TRUE; END_IF;
				STATUS := BYTE#100;
				ARX := FALSE;
				next_cal := TX + T_CAL;
			ELSIF TX - START > T_EXT + T_RUN THEN
				IF SWITCH_AVAIL THEN ERROR := TRUE; END_IF;
				STATUS := BYTE#100;
				ARX := FALSE;
				next_CAL := TX + T_CAL;
			END_IF;
	END_CASE;

	_ramp(OUT := POS);
	POS := _ramp.OUT;
	IF STATUS = BYTE#100 THEN
		OUT1 := _ramp.UP;
		OUT2 := _ramp.DN;
	END_IF;

	IF SWITCH_AVAIL AND END_POS THEN
		POS := SEL_BYTE(POS > BYTE#127, BYTE#0, BYTE#255);
		next_cal := TX + T_CAL;
	END_IF;

	last := TX;

END_FUNCTION_BLOCK

PROGRAM program0
	VAR
		IN :	BYTE;
		TEST :	BOOL;
		ARE :	BOOL := TRUE;
		END_POS :	BOOL;
		T_RUN :	TIME := T#60s;
		T_EXT :	TIME := T#10s;
		T_CAL :	TIME := T#600s;
