FUNCTION_BLOCK ACTUATOR_UD_Block

	VAR_INPUT
		UD :	BOOL;
		_ON :	BOOL;
		MANUAL :	BOOL;
		UP :	BOOL;
		DN :	BOOL;
		OFF :	BOOL;
		YUP_IN :	BOOL;
		YDN_IN :	BOOL;
		_TON :	TIME;
		TOFF :	TIME;
		OUT_RETURN :	BOOL;
	END_VAR


	VAR_OUTPUT
		YUP :	BOOL;
		YDN :	BOOL;
		STATUS :	BYTE;
	END_VAR


	VAR
		TX :	TIME;
		last :	TIME;
		init :	BOOL;
		T_PLC_MS :	T_PLC_MS_block;
	END_VAR

	T_PLC_MS();
	TX:= UDINT_TO_TIME(T_PLC_MS.T_PLC_MS);

	IF NOT init THEN
		last := TX;
		init := TRUE;
	ELSIF off THEN
		Yup := FALSE;
		Ydn := FALSE;
		last := TX;
		STATUS := BYTE#101;

	ELSIF ((Yup OR Ydn) AND SUB_TIME(TX, last) < _TON) THEN RETURN;
	ELSIF NOT yup AND NOT ydn AND SUB_TIME(TX, last) < toff THEN	RETURN;

	ELSIF MANUAL THEN
		STATUS := BYTE#102;
		IF yup AND NOT up OR ydn AND NOT dn THEN
			ydn := FALSE;
			yup := FALSE;
			last := TX;
		ELSIF UP AND NOT DN AND NOT OFF THEN
			Ydn := FALSE;
			Yup := TRUE;
			last := TX;
			STATUS := BYTE#103;
		ELSIF DN AND NOT UP AND NOT OFF THEN
			Yup := FALSE;
			Ydn := TRUE;
			last := TX;
			STATUS := BYTE#104;
		ELSE
			IF YUP OR YDN THEN LAST := TX; END_IF;
			Yup := FALSE;
			Ydn := FALSE;
		END_IF;

	ELSE
		IF yup AND NOT ud OR ydn AND UD THEN
			yup := FALSE;
			ydn := FALSE;
			last := TX;
		ELSIF Ud AND _ON AND NOT OFF THEN
			Ydn := FALSE;
			Yup := TRUE;
			last := TX;
			STATUS := BYTE#111;

		ELSIF NOT UD AND _ON AND NOT OFF THEN
			Yup := FALSE;
			Ydn := TRUE;
			last := TX;
			STATUS := BYTE#112;
		ELSE
			IF Yup OR Ydn THEN last := TX; END_IF;
			Yup := FALSE;
			Ydn := FALSE;
			STATUS := BYTE#110;
		END_IF;
	END_IF;

	IF Ydn AND Yup_IN AND OUT_return THEN
		Ydn := FALSE;
		STATUS := BYTE#1;
	END_IF;
	IF Yup AND Ydn_IN AND OUT_return THEN
		Yup := FALSE;
		STATUS := BYTE#2;
	END_IF;

END_FUNCTION_BLOCK

