	END_IF;

END_FUNCTION

FUNCTION DEW_CON:REAL

	VAR_INPUT
		RH :	REAL;
		T :	REAL;
	END_VAR

	IF RH > 0.0 AND T > -50.0 THEN
		DEW_CON := 2.166824303E-2 * RH * SDD(T,FALSE)  / (T - -273.15);
	ELSE
		DEW_CON := 0.0;
	END_IF;

END_FUNCTION

FUNCTION AIR_ENTHALPY:REAL

	VAR_INPUT
		T :	REAL;
		RH :	REAL;
	END_VAR

	Air_enthalpy := 1.00482 * T + (1.86 * T + 2500.78) * dew_con(RH,T);

END_FUNCTION

