	END_VAR


	VAR
		T_PLC_MS :	T_PLC_MS_block;
		TX :	TIME;
		TL :	TIME;
		tn :	TIME;
		init :	BOOL;
		last_DIR :	BOOL;
		START :	BYTE;
	END_VAR


	T_PLC_MS();
	TX := UDINT_TO_TIME(T_PLC_MS.T_PLC_MS);

	IF E AND init AND (DIR = last_DIR) AND (RMP <> SEL(DIR, BYTE#0, BYTE#255)) AND TR = tn THEN
		RMP := FRMP_B(START, DIR, SUB_TIME(TX, TL), TR);
	ELSE
		init := TRUE;
		TL := TX;
		tn := tr;
		START := RMP;
	END_IF;
	last_DIR := DIR;
END_FUNCTION_BLOCK

FUNCTION_BLOCK AUTORUN_Block

	VAR_INPUT
		IN :	BOOL;
		TEST :	BOOL;
		ARE :	BOOL := TRUE;
		TRUN :	TIME;
		TOFF :	TIME;
	END_VAR


	VAR_OUTPUT
		OUT :	BOOL;
		ARO :	BOOL;
	END_VAR


	VAR_IN_OUT
		ARX :	BOOL;
	END_VAR


	VAR
		timer :	_RMP_B;
		VAL :	BYTE;
	END_VAR

	IF TOFF > T#0s THEN
		timer(DIR:= OUT, TR := SEL(OUT, TOFF, TRUN), RMP := VAL);
		VAL := timer.RMP;
	ELSE
		VAL := BYTE#255;
	END_IF;

	IF (NOT ARX AND ARE AND VAL = BYTE#0) OR TEST THEN
		VAL := BYTE#0;
		ARO := TRUE;
		ARX := TRUE;
	ELSIF VAL = BYTE#255 AND ARO THEN
		ARO := FALSE;
		ARX := FALSE;
	END_IF;

	OUT := IN OR ARO;

END_FUNCTION_BLOCK

