FUNCTION_BLOCK TREND_DW
	VAR_INPUT
		X :	DWORD;
	END_VAR
	VAR_OUTPUT
		Q :	BOOL;
		TU :	BOOL;
		TD :	BOOL;
		D :	DWORD;
	END_VAR

	VAR
		LAST_X :	DWORD;
	END_VAR

	IF X > last_X THEN
		TU := TRUE;
		TD := FALSE;
		D := UDINT_TO_DWORD(DWORD_TO_UDINT(X) - DWORD_TO_UDINT(last_X));
		Q := TRUE;
	ELSIF X < last_X THEN
		TD := TRUE;
		TU := FALSE;
		D := UDINT_TO_DWORD(DWORD_TO_UDINT(last_X) - DWORD_TO_UDINT(X));
		Q := FALSE;
	ELSE
		TU := FALSE;
		TD := FALSE;
		D := DWORD#0;
	END_IF;
	last_X := X;
END_FUNCTION_BLOCK

FUNCTION_BLOCK _RMP_NEXT
	VAR_INPUT
		E :	BOOL := TRUE;
		IN :	BYTE;
		TR :	TIME;
		TF :	TIME;
		TL :	TIME;
	END_VAR

	VAR_OUTPUT
		DIR :	BOOL;
		UP :	BOOL;
		DN :	BOOL;
	END_VAR

	VAR_IN_OUT
		OUT :	BYTE;
	END_VAR
	VAR
		rmx :	_RMP_B;
		DIRx :	TREND_DW;
		t_lock :	TP;
		xen :	BOOL;
		xDIR :	BOOL;
	END_VAR

	DIRx(X := BYTE_TO_DWORD(IN));

	t_lock(IN := FALSE, PT := TL);

	IF DIRx.TU AND (OUT < IN) THEN
		IF NOT xDIR AND xen THEN t_lock(IN := TRUE); END_IF;
		xen := TRUE;
		xDIR := TRUE;
	ELSIF DIRx.TD AND (OUT > IN) THEN
		IF xDIR AND xen THEN t_lock(IN := TRUE); END_IF;
		xen := TRUE;
		xDIR := FALSE;
	ELSIF xen THEN
		IF (xDIR AND (OUT >= IN)) OR (NOT xDIR AND (OUT <= IN)) THEN
			xen := FALSE;
			IF TL > t#0s THEN t_lock(IN := TRUE); END_IF;
		END_IF;
	END_IF;

	IF NOT t_lock.Q AND xen THEN
		UP := XDIR;
		DIR := XDIR;
		DN := NOT XDIR;
	ELSE
		UP := FALSE;
		DN := FALSE;
	END_IF;

	rmx(rmp := OUT, E := E AND (UP OR DN) , DIR := DIR, tr := SEL(DIR, TF, TR));
	OUT := rmx.RMP;
END_FUNCTION_BLOCK

