FUNCTION_BLOCK BLIND_INPUT_Block

	VAR_INPUT
		POS :	BYTE;
		ANG :	BYTE;
		S1 :	BOOL;
		S2 :	BOOL;
		IN :	BOOL;
		PI :	BYTE;
		AI :	BYTE;
		SINGLE_SWITCH :	BOOL;
		CLICK_EN :	BOOL := TRUE;
		CLICK_TIME :	TIME := T#500ms;
		MAX_RUNTIME :	TIME := T#60s;
		MANUAL_TIMEOUT :	TIME := T#1h;
		DEBOUNCE_TIME :	TIME := T#20ms;
		DBL_CLK1 :	BOOL := FALSE;
		DBL_POS1 :	BYTE;
		DBL_ANG1 :	BYTE;
		DBL_CLK2 :	BOOL := FALSE;
		DBL_POS2 :	BYTE := BYTE#255;
		DBL_ANG2 :	BYTE := BYTE#255;
		D1_TOGGLE :	BOOL := TRUE;
		D2_TOGGLE :	BOOL := TRUE;
		MASTER_MODE :	BOOL;
	END_VAR


	VAR_OUTPUT
		QU :	BOOL := TRUE;
		QD :	BOOL := TRUE;
		STATUS :	BYTE;
		PO :	BYTE := BYTE#255;
		AO :	BYTE := BYTE#255;
		D1 :	BOOL;
		D2 :	BOOL;
	END_VAR


	VAR
		S1e :	TOF;
		S2e :	TOF;
		S1d :	CLICK_MODE_Block;
		S2d :	CLICK_MODE_Block;
		DIR :	BOOL;
		TX :	TIME;
		last :	TIME;
		T_PLC_MS :	T_PLC_MS_block;
	END_VAR

	T_PLC_MS();
	TX:= UDINT_TO_TIME(T_PLC_MS.T_PLC_MS);

	S1e(IN := S1, PT := DEBOUNCE_TIME);
	S2e(IN := S2, PT := DEBOUNCE_TIME);
	S1d(IN := (S1e.Q AND NOT SINGLE_SWITCH) OR (S1e.Q AND SINGLE_SWITCH AND DIR), t_long := CLICK_TIME);
	S2d(IN := (S2e.Q AND NOT SINGLE_SWITCH) OR (S1e.Q AND SINGLE_SWITCH AND NOT DIR), t_long := CLICK_TIME);

	IF NOT D1_toggle THEN D1 := FALSE; END_IF;
	IF NOT D2_toggle THEN D2 := FALSE; END_IF;

	IF (S1d.LONG AND S2d.LONG) OR (STATUS = BYTE#139) THEN
	STATUS := BYTE#139;
	IF NOT (S1d.LONG OR S2d.LONG)  THEN STATUS := BYTE#130; END_IF;
	ELSIF S1d.tp_LONG THEN
		STATUS := BYTE#132;
	ELSIF S2d.tp_LONG THEN
		STATUS := BYTE#133;
	ELSIF  S1d.SINGLE THEN
		IF click_en THEN
			IF QU XOR QD THEN
				STATUS := BYTE#131;
			ELSE
				STATUS := BYTE#134;
				last := TX;
				DIR := NOT DIR;
			END_IF;
		END_IF;
	ELSIF  S2d.SINGLE THEN
		IF click_en THEN
			IF QU XOR QD THEN
				STATUS := BYTE#131;
			ELSE
				STATUS := BYTE#135;
				last := TX;
				DIR := NOT DIR;
			END_IF;
		END_IF;
	ELSIF IN THEN
		STATUS := BYTE#136;
		last := TX;
	ELSIF S1d.DOUBLE THEN
		IF dbl_CLK1 THEN
			STATUS := BYTE#137;
			last := TX;
		ELSE
			D1 := NOT D1;
		END_IF;
	ELSIF S2d.DOUBLE THEN
		IF dbl_CLK2 THEN
			STATUS := BYTE#138;
			last := TX;
		ELSE
			IF single_switch THEN D1 := NOT D1; ELSE D2 := NOT D2; END_IF;
		END_IF;
	END_IF;

	CASE _BYTE_TO_INT(STATUS) OF
		0:		
				STATUS := BYTE#130;

		130:	
				IF NOT master_MODE THEN
					PO := POS;
					AO := ANG;
				END_IF;
				QU := TRUE;
				QD := TRUE;

		131:	
				QU := FALSE;
				QD := FALSE;
				PO := POS;
				AO := ANG;
				IF SUB_TIME(TX, last) >= MANUAL_TIMEOUT THEN
					STATUS := BYTE#130;
				END_IF;

		132:	
				QU := TRUE;
				QD := FALSE;
				PO := POS; AO := ANG;
				last := TX;
				IF NOT S1d.LONG THEN STATUS := BYTE#131; DIR := NOT DIR; END_IF;

		133:	
				QU := FALSE;
				QD := TRUE;
				PO := POS; AO := ANG;
				last := TX;
				IF NOT S2d.LONG THEN	STATUS := BYTE#131; DIR := NOT DIR; END_IF;

		134:
				QU := TRUE;
				QD := FALSE;
				PO := POS; AO := ANG;
				IF SUB_TIME(TX, last) >= max_runtime THEN STATUS := BYTE#131; END_IF;

		135:	
				QU := FALSE;
				QD := TRUE;
				PO := POS; AO := ANG;
				IF SUB_TIME(TX, last) >= max_runtime THEN STATUS := BYTE#131;	END_IF;

		136:	
				QU := TRUE;
				QD := TRUE;
				PO := PI; AO := AI;
				IF TX-last >= max_runtime THEN STATUS := BYTE#130; END_IF;

		137:
				QU := TRUE;
				QD := TRUE;
				PO := DBL_POS1;
				AO := DBL_ANG1;
				IF SUB_TIME(TX, last) >= max_runtime THEN STATUS := BYTE#131; END_IF;

		138:	
				QU := TRUE;
				QD := TRUE;
				PO := DBL_POS2;
				AO := DBL_ANG2;
				IF SUB_TIME(TX, last) >= max_runtime THEN STATUS := BYTE#131; END_IF;

		139:
				QU := FALSE;
				QD := FALSE;
				PO := POS;
				AO := ANG;

	END_CASE;

END_FUNCTION_BLOCK

