FUNCTION_BLOCK BLIND_NIGHT_Block

	VAR_INPUT
		UP :	BOOL;
		DN :	BOOL;
		S_IN :	BYTE;
		PI :	BYTE;
		AI :	BYTE;
		E_NIGHT :	BOOL := TRUE;
		E_DAY  :	BOOL := TRUE;
		DTIN :	UDINT;
		SUNRISE :	UDINT;
		SUNSET :	UDINT;
		SUNRISE_OFFSET :	TIME;
		SUNSET_OFFSET :	TIME;
		NIGHT_POSITION :	BYTE;
		NIGHT_ANGLE :	BYTE;
	END_VAR


	VAR_OUTPUT
		QU :	BOOL;
		QD :	BOOL;
		STATUS :	BYTE;
		PO :	BYTE;
		AO :	BYTE;
	END_VAR


	VAR
		NIGHT :	BOOL;
		last_NIGHT :	UDINT;
		last_DAY  :	UDINT;
	END_VAR

	IF NOT (up AND dn) AND NIGHT THEN
		NIGHT := FALSE;
	ELSIF (DT_TO_TOD2(DTIn) > sunset + TIME_TO_UDINT2(sunset_offset)) AND (last_NIGHT < DT_TO_DATE2(DTIn)) AND NOT NIGHT AND e_NIGHT THEN
		NIGHT := TRUE;
		last_NIGHT := DT_TO_DATE2(DTIn);
	ELSIF (DT_TO_TOD2(DTIn) > sunrise + TIME_TO_UDINT2(sunrise_offset)) AND (last_DAY  < DT_TO_DATE2(DTIn)) AND NIGHT AND e_DAY  AND (last_NIGHT < DT_TO_DATE2(DTIn)) THEN
		NIGHT := FALSE;
		last_DAY  := DT_TO_DATE2(DTIn);
	END_IF;

	IF UP AND DN AND NIGHT THEN
		STATUS := BYTE#141;
		po := NIGHT_POSition;
		ao := NIGHT_angle;
	ELSE
		QU := UP;
		QD := DN;
		po := pi;
		ao := ai;
		STATUS := s_in;
	END_IF;

END_FUNCTION_BLOCK

