FUNCTION_BLOCK DIMM_2_Block

	VAR_INPUT
		SET :	BOOL;
		VAL :	BYTE := BYTE#255;
		I1 :	BOOL;
		I2 :	BOOL;
		RST :	BOOL;
		T_DEBOUNCE :	TIME := T#10ms;
		T_ON_MAX :	TIME := T#0h;
		T_DIMM_START :	TIME := T#1s;
		T_DIMM :	TIME := T#3s;
		MIN_ON :	BYTE := BYTE#50;
		MAX_ON :	BYTE := BYTE#255;
		RST_OUT :	BOOL;
		SOFT_DIMM :	BOOL := TRUE;
		DBL1_TOG :	BOOL;
		DBL2_TOG :	BOOL;
		DBL1_SET :	BOOL;
		DBL2_SET :	BOOL;
		DBL1_POS :	BYTE;
		DBL2_POS :	BYTE;
	END_VAR


	VAR_OUTPUT
		Q :	BOOL;
		D1 :	BOOL;
		D2 :	BOOL;
	END_VAR


	VAR_IN_OUT
		_OUT :	BYTE;
	END_VAR


	VAR
		t1 :	TOF;
		t2 :	TOF;
		DC1 :	CLICK_MODE_Block;
		DC2 :	CLICK_MODE_Block;
		t3 :	TON;
		dim :	_RMP_B;
	END_VAR

	t1(IN := I1, PT := T_DEBOUNCE);
	t2(IN := I2, PT := T_DEBOUNCE);
	DC1(IN := t1.Q, T_LONG := T_DIMM_START);
	DC2(IN := t2.Q, T_LONG := T_DIMM_START);

	IF RST THEN
		IF RST_OUT THEN _OUT := BYTE#0; END_IF;
		Q := FALSE;
		D1 := FALSE;
		D2 := FALSE;
	ELSIF SET THEN
		_OUT := VAL;
		Q := TRUE;
	ELSIF DC1.SINGLE THEN
		_OUT := LIMIT(MAX(MIN_ON,BYTE#1), _OUT, MAX_ON);
		Q := TRUE;
	ELSIF DC2.SINGLE THEN
		Q := FALSE;
	ELSIF DC1.TP_LONG THEN
		IF NOT Q THEN
			_OUT := SEL(SOFT_DIMM, LIMIT(MAX(MIN_ON,BYTE#1), _OUT, MAX_ON), BYTE#1);
		END_IF;
		Q := TRUE;
		dim.DIR := TRUE;
	ELSIF DC2.TP_LONG THEN
		dim.DIR := FALSE;
	END_IF;

	IF NOT DBL1_TOG THEN D1 := FALSE; END_IF;
	IF DC1.DOUBLE THEN
		IF DBL1_SET THEN
			_OUT := DBL1_POS;
			Q := TRUE;
		ELSE
			D1 := NOT D1;
		END_IF;
	END_IF;
	IF NOT DBL2_TOG THEN D2 := FALSE; END_IF;
	IF DC2.DOUBLE THEN
		IF DBL2_SET THEN
			_OUT := DBL2_POS;
			Q := TRUE;
		ELSE
