        data[02][1] := REAL#42.1;
        data[03][0] := REAL#20.0;
        data[03][1] := REAL#83.9;
        data[04][0] := REAL#30.0;
        data[04][1] := REAL#125.8;
        data[05][0] := REAL#40.0;
        data[05][1] := REAL#167.58;
        data[06][0] := REAL#50.0;
