FUNCTION_BLOCK HEAT_METER_Block

	VAR_INPUT
		TF :	REAL;
		TR :	REAL;
		LPH :	REAL;
		E :	BOOL;
		RST :	BOOL;
		CP :	REAL;
		DENSITY :	REAL;
		CONTENT :	REAL;
		PULSE_MODE :	BOOL;
		RETURN_METER :	BOOL;
		AVG_TIME :	TIME := T#5s;
	END_VAR


	VAR_OUTPUT
		C :	REAL;
	END_VAR


	VAR_IN_OUT
		Y :	REAL;
	END_VAR


	VAR
		TX :	UDINT;
		last :	UDINT;
		int1 :	FT_INT2_Block;
		edge :	BOOL;
		x :	REAL;
		init :	BOOL;
		Y_last :	REAL;
		T_PLC_MS :	T_PLC_MS_block;
		WATER_ENTHALPY :	WATER_ENTHALPY_Block;
		wa_TF :	REAL;
		wa_TR :	REAL;
	END_VAR

	IF RST THEN
		int1(RST := TRUE);
		int1.RST := FALSE;
		C := 0.0;
		Y := 0.0;
	ELSIF e THEN
		water_enthalpy(T:=TF);
		wa_TF:=water_enthalpy.Result;

		water_enthalpy(T:=TR);
		wa_TR:=water_enthalpy.Result;

		X := (WATER_DENSITY(SEL(return_meter, TF, TR), FALSE) * (wa_TF - wa_TR) * (1.0 - content) + CP * Density * content * (TF-TR));
	END_IF;

	int1(run := NOT pulse_MODE AND e, IN := X * LPH * 2.77777777777E-4);
	IF pulse_MODE THEN
		IF NOT edge AND E THEN Y := Y + X * LPH; END_IF;
	ELSE
		Y := int1.Out;
	END_IF;

	edge := e;

	T_PLC_MS();
	TX:= T_PLC_MS.T_PLC_MS;

	IF NOT init THEN
		init := TRUE;
		last := TX;
	END_IF;

	IF (SUB_TIME(TX, last) >= TIME_TO_UDINT2(AVG_TIME)) AND (AVG_time > T#0s) THEN
		last := TX;
		C := (Y - Y_last) * 3.6E12 / TIME_TO_REAL(AVG_TIME);
		Y_last := Y;
	END_IF;

END_FUNCTION_BLOCK

