	END_VAR

	IF E THEN
		STOP := TOD_TO_TIME(START) + DURATION;
		IF STOP > T#24h THEN STOP := STOP - T#24h; END_IF;
		Q := TIMECHECK(DT_TO_TOD2(DTI), START, TIME_TO_TOD2(STOP)) AND (SHR(BYTE#128, DAY_OF_WEEK(_DT_TO_DATE_B(DTI))) AND DAY) > BYTE#0;
