FUNCTION SDD_NH3:REAL

	VAR_INPUT
		T :	REAL;
	END_VAR

	IF T < -33.65 THEN
		SDD_NH3 := EXP(7.3396511649 - ( 1166.7498002 / ( T + 192.37 )));
	ELSE
		SDD_NH3 := EXP(11.210964456 - ( 2564.9140075 / ( T + 262.741 )));
	END_IF;

END_FUNCTION

PROGRAM program0
  VAR
    T :	REAL;
    CEIL5_OUT : REAL;
  END_VAR

  CEIL5_OUT := SDD_NH3(T);
END_PROGRAM

FUNCTION SDT_NH3:REAL

	VAR_INPUT
		P :	REAL;
	END_VAR

	IF P < 1.0E-3 THEN
		SDT_NH3 := -110.0;
	ELSIF P < 1.0 THEN
		SDT_NH3 := 506.713 / (3.18757 - LOG(P)) - 192.37 ;
	ELSE
		SDT_NH3 := 1113.928 / (4.86886 - LOG(P)) - 262.71 ;
	END_IF;

END_FUNCTION

PROGRAM program0
  VAR
    P :	REAL;
    CEIL5_OUT : REAL;
  END_VAR

  CEIL5_OUT := SDT_NH3(P);
END_PROGRAM

