			q62 := TRUE;
			X2 := FALSE;
		END_IF;
	ELSIF NOT T1.Q AND E1 AND X1 THEN
		Q1 := TRUE;
		X1 := FALSE;
	ELSIF NOT T2.Q AND E2 AND X2 THEN
		Q2 := TRUE;
		X2 := FALSE;
	ELSIF T3.Q THEN
		Q3 := TRUE;
	ELSIF T4.Q THEN
		Q4 := TRUE;
	ELSIF T5.Q THEN
