FUNCTION_BLOCK ACTUATOR_COIL_Block

	VAR_INPUT
		IN :	BOOL;
		SELF_ACT_CYCLE :	TIME := T#10d;
		SELF_ACT_TIME :	TIME := T#1s;
	END_VAR


	VAR_OUTPUT
		OUT :	BOOL;
		STATUS :	BYTE;
	END_VAR


	VAR
		last :	UDINT;
		init :	BOOL;
		TX :	UDINT;
		now :	UDINT;
		T_PLC_MS :	T_PLC_MS_block;
	END_VAR

	T_PLC_MS();
	now := T_PLC_MS.T_PLC_MS;

	IF NOT init THEN
		last := now;
		init := TRUE;
	ELSIF IN THEN
		OUT := TRUE;
		STATUS := BYTE#101;
		LAST := now;
	ELSE
		OUT := FALSE;
		STATUS := BYTE#100;
		TX := now - last;
		IF (self_act_cycle > T#0s) AND (TX >= TIME_TO_UDINT2(self_act_cycle)) THEN
			OUT := TRUE;
			STATUS := BYTE#102;
			IF TX >= TIME_TO_UDINT2(self_act_cycle + self_act_time) THEN
				last := now;
				OUT := FALSE;
				STATUS := BYTE#100;
			END_IF;
		END_IF;
	END_IF;

END_FUNCTION_BLOCK

