		open :	BOOL;
	END_VAR

	TL(IN := level, T_ON := level_DELAY_time, T_OFF := level_DELAY_time);
	open := TL.Q;

	IF ALARM THEN
		IF ACLR THEN
			ALARM := FALSE;
			STATUS := BYTE#101;
			CX(IN := FALSE);
		END_IF;
		RETURN;
	ELSIF LEAK THEN
