END_PROGRAM

FUNCTION TANK_VOL2:REAL

	VAR_INPUT
		TR :	REAL;
		H :	REAL;
	END_VAR

	TANK_VOL2 := 3.14159265358979323846264338327950288 * H * H * (TR - H / 3.0);

END_FUNCTION

