	END_VAR


	VAR_OUTPUT
		T_EXT :	REAL;
		HEAT :	BOOL;
		COOL :	BOOL;
	END_VAR


	VAR
		TX :	TIME;
		last_run :	TIME;
		init :	BOOL;
		cool_START :	UDINT;
		cool_STOP :	UDINT;
		heat_START :	UDINT;
		heat_STOP :	UDINT;
		xdate :	UDINT;
		DAY  :	BOOL;
		T_PLC_MS :	T_PLC_MS_block;
	END_VAR

	IF NOT init THEN
