	T_PLC_MS();
	TX:= T_PLC_MS.T_PLC_MS;

	IF NOT init OR T = t#0s THEN
		init := TRUE;
		Yi := INT_TO_DINT(X) * DINT#1000;
	ELSE
		Yi := Yi + INT_TO_DINT(X - Y) * UDINT_TO_DINT(TX - last) * DINT#1000 / TIME_TO_DINT(T);
	END_IF;
	last := TX;
	Y := DINT_TO_INT(yi / DINT#1000);

