TYPE oscat_complex :
  STRUCT
	re : REAL;
	im : REAL;
  END_STRUCT;
END_TYPE

FUNCTION ATAN2:REAL
	VAR_INPUT
		X :	REAL;
		Y :	REAL;
	END_VAR

	IF X > 0.0 THEN
		ATAN2 := ATAN(Y/X);
	ELSIF X < 0.0 THEN
		IF Y >= 0.0 THEN
			ATAN2 := ATAN(Y/X) + 3.14159265358979323846264338327950288;
		ELSE
			ATAN2 := ATAN(Y/X) - 3.14159265358979323846264338327950288;
		END_IF;
	ELSIF Y > 0.0 THEN
		ATAN2 := 1.5707963267948965580;
	ELSIF Y < 0.0 THEN
		ATAN2 := -1.5707963267948965580;
	ELSE
		ATAN2 := 0.0;
	END_IF;

END_FUNCTION

FUNCTION HYPOT:REAL
	VAR_INPUT
		X :	REAL;
		Y :	REAL;
	END_VAR

	HYPOT := SQRT(X*X + Y*Y);
END_FUNCTION

FUNCTION_BLOCK CLOG_Block

	VAR_INPUT
		X :	oscat_complex;
	END_VAR

	VAR_OUTPUT
		CLOG :	oscat_complex;
	END_VAR

	CLOG.re := LN(HYPOT(X.re, X.im));
	CLOG.im := ATAN2(X.im, X.re);

END_FUNCTION_BLOCK

FUNCTION SGN : INT
  VAR_INPUT
    X : REAL;
  END_VAR

  IF X > 0.0 THEN
  	SGN := 1;
  ELSIF X < 0.0 THEN
  	SGN := -1;
  ELSE
  	SGN := 0;
  END_IF;
END_FUNCTION

FUNCTION_BLOCK CSQRT_Block
	VAR_INPUT
		X :	oscat_complex;
	END_VAR

	VAR_OUTPUT
		CSQRT :	oscat_complex;
	END_VAR

	VAR
		temp :	REAL;
	END_VAR

	temp := HYPOT(X.re, X.im);
	CSQRT.re :=  SQRT(0.5 * (temp + X.re));
	CSQRT.im :=  INT_TO_REAL(SGN(X.im)) * SQRT(0.5 * (temp - X.re));

END_FUNCTION_BLOCK


FUNCTION_BLOCK CACOSH_Block
	VAR_INPUT
		X :	oscat_complex;
	END_VAR

	VAR_OUTPUT
		CACOSH :	oscat_complex;
	END_VAR

	VAR
		Y :	oscat_complex;
		CLOG :	CLOG_Block;
		CSQRT :	CSQRT_Block;
	END_VAR

	Y.re := (X.re - X.im)*(X.re + X.im) - 1.0;
	Y.im := 2.0 * X.re * X.im;
	CSQRT(X:=Y);
	Y    := CSQRT.CSQRT;
	Y.re := Y.re + X.re;
	Y.im := Y.im + X.im;
	CLOG(X:=Y);
	CACOSH  := CLOG.CLOG;
END_FUNCTION_BLOCK

FUNCTION_BLOCK CACOS_Block
	VAR_INPUT
		X :	oscat_complex;
	END_VAR

	VAR_OUTPUT
		CACOS :	oscat_complex;
	END_VAR

	VAR
		Y :	oscat_complex;
		CACOSH :	CACOSH_Block;
	END_VAR

	CACOSH(X:=X);
	Y := CACOSH.CACOSH;
	CACOS.re := Y.im;
	CACOS.im := -Y.re;
END_FUNCTION_BLOCK

PROGRAM program0
  VAR
    LocalVar0 : oscat_complex;
	LocalOUT  : oscat_complex;
	func_block : CACOS_Block;
  END_VAR
	func_block.X  := LocalVar0;
	func_block();
	LocalOUT := func_block.CACOS;
END_PROGRAM

TYPE oscat_complex :
  STRUCT
	re : REAL;
	im : REAL;
  END_STRUCT;
END_TYPE

FUNCTION ATAN2:REAL
	VAR_INPUT
		X :	REAL;
		Y :	REAL;
	END_VAR

	IF X > 0.0 THEN
		ATAN2 := ATAN(Y/X);
	ELSIF X < 0.0 THEN
		IF Y >= 0.0 THEN
			ATAN2 := ATAN(Y/X) + 3.14159265358979323846264338327950288;
		ELSE
			ATAN2 := ATAN(Y/X) - 3.14159265358979323846264338327950288;
		END_IF;
	ELSIF Y > 0.0 THEN
		ATAN2 := 1.5707963267948965580;
	ELSIF Y < 0.0 THEN
		ATAN2 := -1.5707963267948965580;
	ELSE
		ATAN2 := 0.0;
	END_IF;

END_FUNCTION

FUNCTION HYPOT:REAL
	VAR_INPUT
		X :	REAL;
		Y :	REAL;
	END_VAR

	HYPOT := SQRT(X*X + Y*Y);
END_FUNCTION

FUNCTION_BLOCK CLOG_Block

	VAR_INPUT
		X :	oscat_complex;
	END_VAR

	VAR_OUTPUT
		CLOG :	oscat_complex;
	END_VAR

	CLOG.re := LN(HYPOT(X.re, X.im));
	CLOG.im := ATAN2(X.im, X.re);

END_FUNCTION_BLOCK

FUNCTION SGN : INT
  VAR_INPUT
    X : REAL;
  END_VAR

  IF X > 0.0 THEN
  	SGN := 1;
  ELSIF X < 0.0 THEN
  	SGN := -1;
  ELSE
  	SGN := 0;
  END_IF;
END_FUNCTION

FUNCTION_BLOCK CSQRT_Block
	VAR_INPUT
		X :	oscat_complex;
	END_VAR

	VAR_OUTPUT
		CSQRT :	oscat_complex;
	END_VAR

	VAR
		temp :	REAL;
	END_VAR

	temp := HYPOT(X.re, X.im);
	CSQRT.re :=  SQRT(0.5 * (temp + X.re));
	CSQRT.im :=  INT_TO_REAL(SGN(X.im)) * SQRT(0.5 * (temp - X.re));

END_FUNCTION_BLOCK


FUNCTION_BLOCK CACOSH_Block
	VAR_INPUT
		X :	oscat_complex;
	END_VAR

	VAR_OUTPUT
		CACOSH :	oscat_complex;
	END_VAR

	VAR
		Y :	oscat_complex;
		CLOG :	CLOG_Block;
		CSQRT :	CSQRT_Block;
	END_VAR

	Y.re := (X.re - X.im)*(X.re + X.im) - 1.0;
	Y.im := 2.0 * X.re * X.im;
	CSQRT(X:=Y);
	Y    := CSQRT.CSQRT;
	Y.re := Y.re + X.re;
	Y.im := Y.im + X.im;
	CLOG(X:=Y);
	CACOSH  := CLOG.CLOG;
END_FUNCTION_BLOCK

PROGRAM program0
  VAR
    LocalVar0 : oscat_complex;
	LocalOUT  : oscat_complex;
	func_block : CACOSH_Block;
  END_VAR
	func_block.X  := LocalVar0;
	func_block();
	LocalOUT := func_block.CACOSH;
END_PROGRAM

