		CLOG :	CLOG_Block;
		CSQRT :	CSQRT_Block;
	END_VAR

	Y.re := (X.re - X.im)*(X.re + X.im) + 1.0;
	Y.im := 2.0 * X.re * X.im;
	CSQRT(X:=Y);
	Y    := CSQRT.CSQRT;
	Y.re := Y.re + X.re;
	Y.im := Y.im + X.im;
	CLOG(X:=Y);
	CASINH  := CLOG.CLOG;
END_FUNCTION_BLOCK

FUNCTION_BLOCK CASIN_Block
	VAR_INPUT
		X :	oscat_complex;
