	VAR_OUTPUT
		CASIN :	oscat_complex;
	END_VAR

	VAR
		Y :	oscat_complex;
		CASINH :	CASINH_Block;
	END_VAR

	Y.re := -X.im;
	Y.im := X.re;
	CASINH(X:=Y);
	Y := CASINH.CASINH;
	CASIN.re := Y.im;
	CASIN.im := -Y.re;
END_FUNCTION_BLOCK

