FUNCTION_BLOCK CATANH_Block
	VAR_INPUT
		X :	oscat_complex;
	END_VAR

	VAR_OUTPUT
		CATANH :	oscat_complex;
	END_VAR

	VAR
		i2 :	REAL;
		num :	REAL;
		den :	REAL;
	END_VAR

	i2 := X.im * X.im;
	num := 1.0 + X.re;
	num := i2 + num * num;
	den := 1.0 - X.re;
	den := i2 + den * den;
	CATANH.re := 0.25 * (LN(num) - LN(den));
	den := 1.0 - X.re * X.re - i2;
	CATANH.im := 0.5 * ATAN(2.0 * X.im / den);

END_FUNCTION_BLOCK

