	VAR_OUTPUT
		CLEAN :	STRING;
	END_VAR

	VAR
		POS :	INT;
		STOP :	INT;
		CHAR :	STRING;
	END_VAR

	CLEAN := IN;
	STOP := LEN(IN);
	POS := 1;
	WHILE POS <= STOP DO
		CHAR := MID(CLEAN, 1, POS);
