FUNCTION_BLOCK T_PLC_US_Block
	VAR_OUTPUT
		T_PLC_US :	UDINT;
	END_VAR

	VAR
		PLC_TICKS_PER_SEC :	INT;
		PLC_SYS_TICK_CNT :	DINT;
	END_VAR

	VAR
		debug :	BOOL;
		N :	INT;
		Offset :	UDINT;
		temp :	DWORD := DWORD#1;
		MODE :	BOOL;
		faktor :	UDINT;
		init :	BOOL;
		v_plc_ticks_per_sec :	UDINT;
		base :	UDINT := UDINT#1000000;
	END_VAR

	IF init = FALSE THEN
		v_plc_ticks_per_sec := INT_TO_UDINT(PLC_TICKS_PER_SEC);
		IF v_plc_ticks_per_sec = UDINT#1024 THEN
			faktor := UDINT#1000;
			MODE := FALSE;
		ELSIF v_plc_ticks_per_sec > UDINT#0 THEN
			IF v_plc_ticks_per_sec <= base THEN
				faktor := base / v_plc_ticks_per_sec;
				MODE := FALSE;
			ELSE
				faktor := v_plc_ticks_per_sec / base;
				MODE := TRUE;
			END_IF;
		ELSE
			faktor := UDINT#1;
		END_IF;
		init := TRUE;
	END_IF;

	IF MODE THEN
		T_PLC_US := DINT_TO_UDINT(PLC_SYS_TICK_CNT) / faktor;
	ELSE
		T_PLC_US := DINT_TO_UDINT(PLC_SYS_TICK_CNT) * faktor;
	END_IF;

	IF debug THEN
		T_PLC_US := (DWORD_TO_UDINT(SHL(UDINT_TO_DWORD(T_PLC_US),N) OR SHL(temp,N)) - UDINT#1) + Offset;
	END_IF;
END_FUNCTION_BLOCK

FUNCTION_BLOCK FT_PIWL

	VAR_INPUT
		IN :	REAL;
		KP :	REAL := 1.0;
		KI :	REAL := 1.0;
		LIM_L :	REAL := -1.0E38;
		LIM_H :	REAL := 1.0E38;
		RST :	BOOL;
	END_VAR

	VAR_OUTPUT
		Y :	REAL;
		LIM :	BOOL;
	END_VAR

	VAR
		init :	BOOL;
		TX :	UDINT;
		tc :	REAL;
		t_last :	UDINT;
		in_last :	REAL;
		i :	REAL;
		p :	REAL;
		T_PLC_US :	T_PLC_US_Block;
	END_VAR

	IF NOT init OR RST THEN
		init := TRUE;
		in_last := IN;
		T_PLC_US();
		t_last := T_PLC_US.T_PLC_US;
		i := 0.0;
		tc := 0.0;
	ELSE
		(* read last cycle time IN Microseconds *)
		T_PLC_US();
		TX := T_PLC_US.T_PLC_US;
		tc := UDINT_TO_REAL(TX - t_last);
		t_last := TX;

		(* calculate proportional part *)
		p := KP * IN;

		(* run INTEGrator *)
		i := (IN + in_last) * 5.0E-7 * KI * tc + i;
		in_last := IN;

		(* calculate OUTput Y *)
		Y := p + i;

		(* check OUTput for limits *)
		IF Y >= LIM_H THEN
			Y := LIM_H;
			IF KI <> 0.0 THEN
				i := LIM_H - p;
			ELSE
				i := 0.0;
			END_IF;
			LIM := TRUE;
		ELSIF Y <= LIM_L THEN
			Y := LIM_L;
			IF KI <> 0.0 THEN
				i := LIM_L - p;
			ELSE
				i := 0.0;
			END_IF;
			LIM := TRUE;
		ELSE
			LIM := FALSE;
		END_IF;
	END_IF;
END_FUNCTION_BLOCK

FUNCTION_BLOCK FT_DERIV
	VAR_INPUT
		IN :	REAL;
		K :	REAL := 1.0;
		RUN :	BOOL := TRUE;
	END_VAR

	VAR_OUTPUT
		OUT :	REAL;
	END_VAR

	VAR
		old :	REAL;
		TX :	UDINT;
		last :	UDINT;
		init :	BOOL;
		tc :	REAL;
		T_PLC_US :	T_PLC_US_Block;
	END_VAR

	T_PLC_US();
	TX:= T_PLC_US.T_PLC_US;
	tc := UDINT_TO_REAL((TX - last));

	IF NOT init THEN
		init := TRUE;
		old := IN;
	ELSIF RUN AND tc > 0.0 THEN
		OUT := (IN - old) / tc * 1000000.0 * K;
		old := IN;
	ELSE
		OUT := 0.0;
	END_IF;

	last := TX;

	T_PLC_US();
	TX:= T_PLC_US.T_PLC_US;

	IF NOT init THEN
		init := TRUE;
	ELSIF RUN AND (TX - last) > UDINT#0 THEN
		OUT := (IN - old) / UDINT_TO_REAL(TX - last) * 1000000.0 * K;
	ELSE
		OUT := 0.0;
	END_IF;
	old := IN;
	last := TX;
END_FUNCTION_BLOCK

FUNCTION_BLOCK FT_PIDWL
	VAR_INPUT
		IN :	REAL;
		KP :	REAL := 1.0;
		TN :	REAL := 1.0;
		TV :	REAL := 1.0;
		LIM_L :	REAL := -1.0E38;
		LIM_H :	REAL := 1.0E38;
		RST :	BOOL;
	END_VAR

	VAR_OUTPUT
		Y :	REAL;
		LIM :	BOOL;
	END_VAR

	VAR
		piwl :	FT_PIWL;
		diff :	FT_DERIV;
	END_VAR

	IF RST THEN
		piwl(RST := TRUE);
		piwl.RST := FALSE;
	ELSE
		IF TN = 0.0 THEN
			piwl(IN := IN * KP, KP := 1.0, KI := 0.0, LIM_L := LIM_L, LIM_H := LIM_H);
		ELSE
			piwl(IN := IN * KP, KP := 1.0, KI := 1.0 / TN, LIM_L := LIM_L, LIM_H := LIM_H);
		END_IF;

		diff(IN := IN, K := KP * TV);
		Y := piwl.Y + diff.OUT;

		IF Y < LIM_L THEN
			LIM := TRUE;
			Y := LIM_L;
		ELSIF Y > LIM_H THEN
			LIM := TRUE;
			Y := LIM_H;
		ELSE
			LIM := FALSE;
		END_IF;
	END_IF;
END_FUNCTION_BLOCK

FUNCTION_BLOCK CTRL_OUT
	VAR_INPUT
		CI :	REAL;
		OFFSET :	REAL;
		MAN_IN :	REAL;
		LIM_L :	REAL;
		LIM_H :	REAL;
		MANUAL :	BOOL;
	END_VAR

	VAR_OUTPUT
		Y :	REAL;
		LIM :	BOOL;
	END_VAR

	Y := SEL(MANUAL, CI, MAN_IN) + OFFSET;

	IF Y >= LIM_H THEN
		Y := LIM_H;
		LIM := TRUE;
	ELSIF Y <= LIM_L THEN
		Y := LIM_L;
		LIM := TRUE;
	ELSE
		LIM := FALSE;
	END_IF;
END_FUNCTION_BLOCK

FUNCTION DEAD_ZONE:REAL

	VAR_INPUT
		X :	REAL;
		L :	REAL;
	END_VAR

	IF ABS(X) > L THEN
		DEAD_ZONE := X;
	ELSE
		DEAD_ZONE := 0.0;
	END_IF;

END_FUNCTION

FUNCTION CTRL_IN:REAL
	VAR_INPUT
		SET_POINT :	REAL;
		ACTUAL :	REAL;
		NOISE :	REAL;
	END_VAR
	CTRL_IN := DEAD_ZONE(SET_POINT - ACTUAL, NOISE);
END_FUNCTION

