FUNCTION_BLOCK DEAD_ZONE2
	VAR_INPUT
		X :	REAL;
		L :	REAL;
	END_VAR

	VAR_OUTPUT
		Y :	REAL;
	END_VAR

	IF ABS(X) > L THEN
		Y := X;
	ELSIF Y > 0.0 THEN
		Y := L;
	ELSE
		Y := -L;
	END_IF;
END_FUNCTION_BLOCK

PROGRAM program0
  VAR
    LocalVar0 : REAL;
	LocalVaR1  : REAL;
