FUNCTION_BLOCK DEC_2
	VAR_INPUT
		D :	BOOL;
		A :	BOOL;
	END_VAR
	VAR_OUTPUT
		Q0 :	BOOL;
		Q1 :	BOOL;
	END_VAR
	Q0 := D AND NOT A;
	Q1 := D AND A;
END_FUNCTION_BLOCK

