FUNCTION BIT_LOAD_B:BYTE
	VAR_INPUT
		IN :	BYTE;
		VAL :	BOOL;
		POS :	INT;
	END_VAR

	IF VAL THEN
		BIT_LOAD_B := IN OR SHL(BYTE#1,POS);
	ELSE
		BIT_LOAD_B := IN AND (NOT SHL(BYTE#1,POS));
	END_IF;
END_FUNCTION

FUNCTION _BYTE_TO_INT:INT
	VAR_INPUT
		IN :	BYTE;
	END_VAR

	_BYTE_TO_INT := USINT_TO_INT(BYTE_TO_USINT(IN));
END_FUNCTION

FUNCTION_BLOCK DEC_8

	VAR_INPUT
		D :	BOOL;
		A0 :	BOOL;
		A1 :	BOOL;
		A2 :	BOOL;
	END_VAR


	VAR_OUTPUT
		Q0 :	BOOL;
		Q1 :	BOOL;
		Q2 :	BOOL;
		Q3 :	BOOL;
		Q4 :	BOOL;
		Q5 :	BOOL;
		Q6 :	BOOL;
		Q7 :	BOOL;
	END_VAR


	VAR
		X :	BYTE;
		Y :	INT;
	END_VAR

	X:=BIT_LOAD_B(X,A0,0); (* X.0 := A0; *)
	X:=BIT_LOAD_B(X,A1,1); (* X.1 := A1; *)
	X:=BIT_LOAD_B(X,A2,2); (* X.2 := A2; *)

	Q0 := FALSE;
	Q1 := FALSE;
	Q2 := FALSE;
	Q3 := FALSE;
	Q4 := FALSE;
	Q5 := FALSE;
	Q6 := FALSE;
	Q7 := FALSE;

	Y := _BYTE_TO_INT(X);

	CASE Y OF
		0 : Q0 := D;
		1 : Q1 := D;
		2 : Q2 := D;
		3 : Q3 := D;
		4 : Q4 := D;
		5 : Q5 := D;
		6 : Q6 := D;
		7 : Q7 := D;
	END_CASE;

	END_FUNCTION_BLOCK

