FUNCTION_BLOCK DWORD_TO_STRF_Block

	VAR_INPUT
		IN :	DWORD;
		N :	INT;
	END_VAR

	VAR_OUTPUT
		DWORD_TO_STRF :	STRING;
	END_VAR

	VAR
		temp :	STRING;
		temp2 :	STRING;
		L : INT;
	END_VAR

	temp := DWORD_TO_STRING(IN);
	L := LEN(temp);
	IF N < L THEN
		temp :=RIGHT(temp,N);
		L := N;
	END_IF;

	WHILE L < N DO
		temp2 := temp;
		temp := CONCAT('0', temp2);
		L := L + 1;
	END_WHILE;
	DWORD_TO_STRF := temp;

END_FUNCTION_BLOCK

