			(* perform the PTesss on the ramp *)
			TL := TX;
			(* calculate the PTesss response *)
			IF NOT DIR THEN PTesss := - PTesss; END_IF;
			RMP := DINT_TO_WORD(LIMIT(DINT#0, _WORD_TO_DINT(RMP) + PTesss, DINT#65535));
		END_IF;
	ELSE
		TL := TX;
		init := TRUE;
	END_IF;
END_FUNCTION_BLOCK



FUNCTION_BLOCK RMP_W

	VAR_INPUT
		SET :	BOOL;
		PT :	TIME;
		E :	BOOL := TRUE;
		UP :	BOOL := TRUE;
		RST :	BOOL;
	END_VAR

	VAR_OUTPUT
		OUT :	WORD;
		BUSY :	BOOL;
		HIGH :	BOOL;
		LOW :	BOOL;
	END_VAR

	VAR
		rmp :	_RMP_W;
	END_VAR

	rmp(DIR := UP, E := E, TR := PT, RMP := OUT);
	OUT := rmp.RMP;

	IF RST THEN
		OUT := WORD#0;
	ELSIF SET THEN
		OUT := WORD#65535;
	END_IF;

	LOW := OUT = WORD#0;
	HIGH := OUT = WORD#65535;
	BUSY := NOT (LOW OR HIGH) AND E;

END_FUNCTION_BLOCK

FUNCTION _WORD_TO_REAL:REAL
	VAR_INPUT
		IN :	WORD;
