FUNCTION_BLOCK FADE
	VAR_INPUT
		IN1 :	REAL;
		IN2 :	REAL;
		F :	BOOL;
		TF :	TIME;
		RST :	BOOL;
	END_VAR

	VAR_OUTPUT
		Y :	REAL;
	END_VAR

	VAR
		rmx :	RMP_W;
	END_VAR
	rmx(RST := RST AND NOT F, SET := RST AND F, PT := TF, UP := F);
	Y := (IN2 - IN1) / 65535.0 * _WORD_TO_REAL(rmx.OUT) + IN1;

END_FUNCTION_BLOCK

