FUNCTION FIB:DINT

VAR_INPUT
	X :	INT;
END_VAR

VAR
	t1 :	DINT;
	t2 :	DINT;
	X_tmp :	INT;
END_VAR

t1 := DINT#0;
t2 := DINT#0;
X_tmp := X;
IF X_tmp < 0 OR X_tmp > 46 THEN
	FIB := DINT#-1;
ELSIF X_tmp < 2 THEN
	FIB := INT_TO_DINT(X_tmp);
	RETURN;
ELSE
	t2 := DINT#1;
	WHILE X_tmp > 3 DO
		X_tmp := X_tmp - 2;
		t1 := t1 + t2;
		t2 := t1 + t2;
	END_WHILE;
	IF X_tmp > 2 THEN t1 := t1 + t2; END_IF;
	FIB := t1 + t2;
END_IF;

END_FUNCTION

