FUNCTION_BLOCK FILTER_MAV_DW

	VAR_INPUT
		X :	DWORD;
		N :	UINT;
		RST :	BOOL;
	END_VAR

	VAR_OUTPUT
		Y :	DWORD;
	END_VAR

	VAR
		init :	BOOL;
		buffer :	oscat_ardw_0_31;
		i :	INT;
		tmp :	INT;
		NN :	UINT;
	END_VAR

	NN := MIN(N, UINT#32);

	(* STARTup initialisation *)
	IF NOT init OR RST OR NN = UINT#0 THEN
		init := TRUE;
		tmp := UINT_TO_INT(NN)-1;
		FOR i := 0 TO tmp DO
			buffer[i] := X;
		END_FOR;
		Y := X;
	ELSE
		tmp := UINT_TO_INT(NN);
		i := INC1(i, tmp);
		Y := UDINT_TO_DWORD(DWORD_TO_UDINT(Y) + (DWORD_TO_UDINT(X) - DWORD_TO_UDINT(buffer[i])) / UINT_TO_UDINT(NN));
		buffer[i] := X;
	END_IF;

END_FUNCTION_BLOCK

