	T :	TIME;

	Y :	WORD;

	func_block : FILTER_W;
  END_VAR
	func_block.X  := X;
	func_block.T  := T;
	func_block();
	Y := func_block.Y;
END_PROGRAM

TYPE
  oscat_arr_0_15              : ARRAY [0..15]   OF REAL;
END_TYPE


FUNCTION INC1:INT

	VAR_INPUT
		X :	INT;
		N :	INT;
	END_VAR

	IF X >= N - 1 THEN
		INC1 := 0;
	ELSE
		INC1 := X + 1;
	END_IF;
END_FUNCTION

FUNCTION DEC1:INT

	VAR_INPUT
		X :	INT;
		N :	INT;
	END_VAR

	IF X = 0 THEN
		DEC1 := N - 1;
	ELSE
		DEC1 := X - 1;
	END_IF;

END_FUNCTION

FUNCTION_BLOCK FILTER_WAV
	VAR_INPUT
		X :	REAL;
		W :	oscat_arr_0_15;
		RST :	BOOL;
	END_VAR

	VAR_OUTPUT
		Y :	REAL;
	END_VAR

	VAR
		init :	BOOL;
		buffer :	oscat_arr_0_15;
		i :	INT;
		n :	INT;
	END_VAR

	IF NOT init OR RST THEN
		init := TRUE;
		FOR i := 0 TO 15 DO
			buffer[i] := X;
		END_FOR;
		i := 15;
		Y := X;
	ELSE
		i := INC1(i, 16);
		buffer[i] := X;
	END_IF;

	Y := 0.0;
	FOR n := 0 TO 15 DO
		Y := buffer[i] * W[n] + Y;
		i := DEC1(i, 16);
	END_FOR;
END_FUNCTION_BLOCK

PROGRAM program0
  VAR
	X :	REAL;
	W :	oscat_arr_0_15;
	RST :	BOOL;

	Y :	REAL;

	func_block : FILTER_WAV;
  END_VAR
	func_block.X  := X;
	func_block.W  := W;
	func_block.RST  := RST;
	func_block();
	Y := func_block.Y;
END_PROGRAM

FUNCTION_BLOCK FINDB_Block

	VAR_INPUT
		STR1  :	STRING;
		STR2 :	STRING;
	END_VAR

	VAR_OUTPUT
		FINDB :	INT;
	END_VAR

	VAR
		POS :	INT;
		length :	INT;
		string_temp :	STRING;
	END_VAR

	length := LEN(STR2);
	POS := LEN(STR1 ) - length +1;
	WHILE (POS >= 1) DO
		string_temp := MID(STR1 ,length,POS);
		IF EQ_STRING(string_temp,STR2) THEN
			FINDB := POS;
			RETURN;
		END_IF;
	POS := POS -1;
	END_WHILE;
	FINDB := 0;

END_FUNCTION_BLOCK

PROGRAM program0
  VAR
		STR1  :	STRING;
		STR2 :	STRING;

		FINDB :	INT;

	func_block : FINDB_Block;
  END_VAR
	func_block.STR1   := STR1 ;
	func_block.STR2  := STR2;
	func_block();
	FINDB := func_block.FINDB;
END_PROGRAM

FUNCTION_BLOCK FINDP_Block

	VAR_INPUT
		STR :	STRING;
		SRC :	STRING;
		POS :	INT;
	END_VAR


	VAR_OUTPUT
		FINDP :	INT;
	END_VAR

	VAR
		i :	INT;
		ls :	INT;
		lx :	INT;
		stp :	INT;
		st_tmp :	STRING;
	END_VAR


	ls := LEN(STR);
	lx := LEN(SRC);
	IF ls < lx OR lx = 0 THEN RETURN; END_IF;
	stp := ls - lx + 1;
	FOR i := MAX(POS,1) TO stp DO
		st_tmp := MID(STR,lx,i);
		IF EQ_STRING(st_tmp,SRC) THEN
			FINDP := i;
			RETURN;
		END_IF;
	END_FOR;
	FINDP := 0;

END_FUNCTION_BLOCK

PROGRAM program0

	VAR
		STR :	STRING;
		SRC :	STRING;
		POS :	INT;

        FINDP :	INT;
		func_block : FINDP_Block;
	END_VAR
		func_block.STR := STR;
		func_block.SRC := SRC;
		func_block.POS := POS;
		func_block();
		FINDP := func_block.FINDP;

END_PROGRAM

FUNCTION _BYTE_TO_INT:INT
	VAR_INPUT
		IN :	BYTE;
	END_VAR

	_BYTE_TO_INT := USINT_TO_INT(BYTE_TO_USINT(IN));
END_FUNCTION

FUNCTION_BLOCK CHR_TO_STRING_Block
	VAR_INPUT
		C :	BYTE;
	END_VAR

	VAR_OUTPUT
		CHR_TO_STRING :	STRING;
	END_VAR

	CHR_TO_STRING := BYTE_TO_STRING(C);

END_FUNCTION_BLOCK

FUNCTION BIT_OF_DWORD : BOOL
  VAR_INPUT
    IN : DWORD;
    N : INT;
  END_VAR

  BIT_OF_DWORD := (SHR(IN,N) AND 16#00000001) > 0;
  (* from OSCAT library; www.oscat.de  *)
END_FUNCTION

FUNCTION_BLOCK FILL_Block
	VAR_INPUT
		C :	BYTE;
		L :	INT;
	END_VAR

	VAR_OUTPUT
		FILL :	STRING;
	END_VAR

	VAR
		N :	BYTE;
		I :	INT;
		sx :	STRING;
		CHR_TO_STRING :	CHR_TO_STRING_Block;
		FILL_tmp :	STRING;
	END_VAR

	CHR_TO_STRING(C:=C);
	sx:=CHR_TO_STRING.CHR_TO_STRING;
	(* create string *)
	N := INT_TO_BYTE(LIMIT(0,L,80));
	(* create a string of CHARacters to be connected to str *)
	FILL := '';
	FOR I := 1 TO 8 DO
		FILL_tmp := FILL;
		FILL := CONCAT(FILL_tmp,FILL);
		IF BIT_OF_DWORD(BYTE_TO_DWORD(N),7) THEN FILL := CONCAT(FILL,sx); END_IF;
		N := SHL(N,1);
	END_FOR;
END_FUNCTION_BLOCK

FUNCTION_BLOCK FIX_Block

	VAR_INPUT
		STR :	STRING;
		L :	INT;
		C :	BYTE;
		M :	INT;
	END_VAR

	VAR_OUTPUT
		FIX :	STRING;
	END_VAR

	VAR
		N :	INT;
		FILL :	FILL_Block;
	END_VAR

	N := LIMIT(0,L,255) - LEN(STR);
	IF N <= 0 THEN
		(* truncate the string at length N *)
		IF M = 1 THEN
			FIX := RIGHT(STR,L);
		ELSE
			FIX := LEFT(STR,L);
		END_IF;
	ELSIF M = 1 THEN
		(* connect fill CHARacters at the beginning *)
		FILL(C:=C,L:=N);
		FIX := CONCAT(FILL.FILL,STR);
	ELSIF M = 2 THEN
		(* center str beween fill CHARacters *)
		(* for an unEVEN number of fill CHARacters, there is one more at the end *)
		FILL(C:=C,L:=_BYTE_TO_INT(SHR(INT_TO_BYTE(N+1),1)));
		FIX := CONCAT(STR,FILL.FILL);
		FILL(C:=C,L:=_BYTE_TO_INT(SHR(INT_TO_BYTE(N),1)));
		FIX := CONCAT(FILL.FILL,FIX);
	ELSE
		(* connect fill CHARacters at the end *)
		FILL(C:=C,L:=N);
		FIX := CONCAT(STR,FILL.FILL);
	END_IF;

END_FUNCTION_BLOCK

PROGRAM program0
  VAR
	STR :	STRING;
	L   :	INT;
	C   :	BYTE;
	M   :	INT;

	FIX :	STRING;

	func_block : FIX_Block;
  END_VAR
	func_block.STR:=STR;
	func_block.L  :=L  ;
	func_block.C  :=C  ;
	func_block.M  :=M  ;
	func_block();
	FIX := func_block.FIX;
END_PROGRAM

