FUNCTION_BLOCK TP_1D
	VAR_INPUT
		IN :	BOOL;
		PT1 :	TIME;
		PTD :	TIME;
		RST :	BOOL;
	END_VAR


	VAR_OUTPUT
		Q :	BOOL;
		W :	BOOL;
	END_VAR

	VAR
		TX :	TIME;
		START :	TIME;
		ix :	BOOL;
		T_PLC_MS :	T_PLC_MS_block;
		RSTT : BOOL;
		INN : BOOL;
	END_VAR

	T_PLC_MS();
	TX := UDINT_TO_TIME(T_PLC_MS.T_PLC_MS);

	RSTT := RST;
	INN := IN;
	IF RSTT THEN
		Q := FALSE;
		RSTT := FALSE;
		W := FALSE;
	ELSIF W THEN
		IF SUB_TIME(TX, START) >= PTD THEN
			W := FALSE;
		END_IF;
	ELSIF INN AND NOT ix THEN
		Q := TRUE;
		START := TX;
		INN := FALSE;
	ELSIF SUB_TIME(TX, START)  >= PT1 THEN
		Q := FALSE;
		W := TRUE;
		START := TX;
	END_IF;

	ix := INN;

END_FUNCTION_BLOCK

FUNCTION_BLOCK FLOW_CONTROL
	VAR_INPUT
		IN :	BOOL;
		REQ :	BOOL;
		ENQ :	BOOL;
		RST :	BOOL := FALSE;
		T_AUTO :	TIME := T#1h;
		T_DELAY :	TIME := T#23h;
	END_VAR

	VAR_OUTPUT
		Q :	BOOL;
		STATUS :	BYTE;
	END_VAR

	VAR
		timer :	TP_1D;
	END_VAR

	STATUS := BYTE#100;
	IF RST THEN
		Q := FALSE;
		timer(RST := TRUE);
		timer.RST := FALSE;
		STATUS := BYTE#103;
	ELSIF ENQ THEN
		IF IN THEN
			STATUS := BYTE#101;
		END_IF;
		IF REQ THEN
			(* timer will generate a timed pulse after TP goes high *)
			timer.PT1 := T_AUTO;
			timer.PTD := T_DELAY;
			timer.IN := TRUE;
			STATUS := BYTE#102;
		END_IF;
	END_IF;

	timer();
	timer.IN := FALSE;
	Q := (IN AND ENQ) OR timer.Q;
END_FUNCTION_BLOCK

