	STATUS :	BYTE;

	func_block : FLOW_CONTROL;
  END_VAR
	func_block.IN     :=IN     ;
	func_block.REQ    :=REQ    ;
	func_block.ENQ    :=ENQ    ;
	func_block.RST    :=RST    ;
	func_block.T_AUTO :=T_AUTO ;
	func_block.T_DELAY:=T_DELAY;
