		ELSIF v_plc_ticks_per_sec > UDINT#0 THEN
			IF v_plc_ticks_per_sec <= base THEN
				faktor := base / v_plc_ticks_per_sec;
				MODE := FALSE;
			ELSE
				faktor := v_plc_ticks_per_sec / base;
				MODE := TRUE;
			END_IF;
		ELSE
			faktor := UDINT#1;
		END_IF;
		init := TRUE;
	END_IF;

	IF MODE THEN
		T_PLC_MS := DINT_TO_UDINT(PLC_SYS_TICK_CNT) / faktor;
	ELSE
		T_PLC_MS := DINT_TO_UDINT(PLC_SYS_TICK_CNT) * faktor;
	END_IF;

	IF debug THEN
		T_PLC_MS := (DWORD_TO_UDINT(SHL(UDINT_TO_DWORD(T_PLC_MS),N) OR SHL(temp,N)) - UDINT#1) + Offset;
	END_IF;
END_FUNCTION_BLOCK

FUNCTION_BLOCK INTEGRATE

	VAR_INPUT
		E :	BOOL := TRUE;
		X :	REAL;
		K :	REAL := 1.0;
	END_VAR

	VAR_IN_OUT
		Y :	REAL;
	END_VAR

	VAR
		X_LAST :	REAL;
		init :	BOOL;
		T_PLC_MS :	T_PLC_MS_block;
		last :	UDINT;
		TX :	UDINT;
	END_VAR


	T_PLC_MS();
	TX:= T_PLC_MS.T_PLC_MS;

	IF NOT init THEN
		init := TRUE;
		X_LAST := X;
	ELSIF E THEN
		Y := (X + X_LAST) * 0.5E-3 * UDINT_TO_REAL(TX-last) * K + Y;
		X_LAST := X;
	END_IF;
	last := TX;

END_FUNCTION_BLOCK

FUNCTION _INT_TO_UDINT:UDINT
	VAR_INPUT
		IN :	INT;
	END_VAR

	_INT_TO_UDINT := DINT_TO_UDINT(INT_TO_DINT(IN));
END_FUNCTION

FUNCTION FLOOR : INT
	VAR_INPUT
		X : REAL;
	END_VAR

	FLOOR := REAL_TO_INT(X);
	IF INT_TO_REAL(FLOOR) > X THEN
		FLOOR := FLOOR - 1;
	END_IF;
END_FUNCTION

FUNCTION_BLOCK FLOW_METER
	VAR_INPUT
		VX :	REAL;
		E :	BOOL;
		RST :	BOOL;
		PULSE_MODE :	BOOL;
		UPDATE_TIME :	TIME := T#1s;
	END_VAR

	VAR_OUTPUT
		F :	REAL;
	END_VAR

	VAR_IN_OUT
		X :	REAL;
		Y :	UDINT;
	END_VAR

	VAR
		T_PLC_MS :	T_PLC_MS_block;
		TX :	TIME;
		TL :	TIME;
		int1 :	INTEGRATE;
		init :	BOOL;
		e_last :	BOOL;
		tmp :	INT;
		X_LAST :	REAL;
		y_last :	UDINT;
	END_VAR

	IF NOT init THEN	(* init on power up *)
		init := TRUE;
		TL := TX;
		X_LAST := X;
		y_last := Y;
		int1.K := 2.7777777777777777E-4;
	END_IF;

	int1(E := NOT (RST OR PULSE_MODE) AND E, X := VX, Y := X);	(* gated operation *)
	X := int1.Y;

	IF RST THEN		(* reset *)
		X := 0.0;
		Y := UDINT#0;
		TL := TX;
		X_LAST := 0.0;
		y_last := UDINT#0;
	ELSIF E AND PULSE_MODE THEN	(* check for pulse MODE *)
		IF NOT e_last THEN X := X + VX; END_IF;
	END_IF;
	e_last := E;

	(* reduce X to be less than 1 and INCrease Y respectively *)
	IF X > 1.0 THEN
		tmp := FLOOR(X);
		Y := Y + _INT_TO_UDINT(tmp);
		X := X - INT_TO_REAL(tmp);
	END_IF;

	(* calculate the current flow *)
	T_PLC_MS();
	TX := UDINT_TO_TIME(T_PLC_MS.T_PLC_MS);
	IF SUB_TIME(TX, TL) >= UPDATE_TIME AND UPDATE_TIME > t#0s THEN
		F := (UDINT_TO_REAL(Y - y_last) + X - X_LAST) / TIME_TO_REAL(SUB_TIME(TX, TL)) * 3.6E6;
		y_last := Y;
		X_LAST := X;
		TL := TX;
	END_IF;

END_FUNCTION_BLOCK

PROGRAM program0
  VAR
	VX :	REAL;
	E :	BOOL;
	RST :	BOOL;
	PULSE_MODE :	BOOL;
	UPDATE_TIME :	TIME := T#1s;

	F :	REAL;

	X :	REAL;
	Y :	UDINT;

	func_block : FLOW_METER;
  END_VAR
	func_block.VX:=VX;
	func_block.E:=E;
	func_block.RST:=RST;
	func_block.PULSE_MODE:=PULSE_MODE;
	func_block.UPDATE_TIME :=UPDATE_TIME ;

	func_block(X:=X, Y:=Y);
	F:= func_block.F;
	X:= func_block.X;
	Y:= func_block.Y;
END_PROGRAM

FUNCTION D_TRUNC : DINT
  VAR_INPUT
    X : REAL;
  END_VAR

  D_TRUNC := REAL_TO_DINT(X);
  IF X > 0.0 THEN
  	IF DINT_TO_REAL(D_TRUNC) > X THEN D_TRUNC := D_TRUNC - DINT#1; END_IF;
  ELSE
  	IF DINT_TO_REAL(D_TRUNC) < X THEN D_TRUNC := D_TRUNC + DINT#1; END_IF;
  END_IF;
END_FUNCTION

FUNCTION FRACT:REAL
	VAR_INPUT
		X :	REAL;
	END_VAR

	IF ABS(X) < 2.0E9 THEN
		FRACT := X - DINT_TO_REAL(D_TRUNC(X));
	ELSE
		FRACT := 0.0;
	END_IF;
END_FUNCTION

PROGRAM program0
  VAR
    LocalVar0 : REAL;
	LocalOUT  : REAL;
  END_VAR
  	LocalOUT := FRACT(LocalVar0);
END_PROGRAM

FUNCTION FRMP_B:BYTE

	VAR_INPUT
		START :	BYTE;
		DIR :	BOOL;
		TD :	TIME;
		TR :	TIME;
	END_VAR

	IF TD < TR THEN
		FRMP_B := MIN(UDINT_TO_BYTE(DWORD_TO_UDINT(SHL(TIME_TO_DWORD(TD), 8)) / TIME_TO_UDINT(TR)), SEL(DIR, START, USINT_TO_BYTE(USINT#255 - BYTE_TO_USINT(START))));
		IF DIR THEN
			FRMP_B := USINT_TO_BYTE(BYTE_TO_USINT(START) + BYTE_TO_USINT(FRMP_B));
		ELSE
			FRMP_B := USINT_TO_BYTE(BYTE_TO_USINT(START) - BYTE_TO_USINT(FRMP_B));
		END_IF;
	ELSE
		FRMP_B := SEL(DIR, BYTE#0, BYTE#255);
	END_IF;
END_FUNCTION

PROGRAM program0
  VAR
    LocalVar0 : BYTE;
	LocalVaR1  : BOOL;
	LocalVaR2 : TIME;
	LocalVar3 : TIME;
    LocalOUT  : BYTE;
  END_VAR

  LocalOUT := FRMP_B(LocalVar0, LocalVaR1 , LocalVaR2,LocalVar3);
END_PROGRAM

TYPE
	oscat_DELAY_buf             : ARRAY [0..31]   OF REAL;
END_TYPE

FUNCTION INC1:INT

	VAR_INPUT
		X :	INT;
		N :	INT;
	END_VAR

	IF X >= N - 1 THEN
		INC1 := 0;
	ELSE
		INC1 := X + 1;
	END_IF;
END_FUNCTION


FUNCTION_BLOCK DELAY

	VAR_INPUT
		IN :	REAL;
		N :	INT;
		RST :	BOOL;
	END_VAR


	VAR_OUTPUT
		OUT :	REAL;
	END_VAR


	VAR
		buf :	oscat_DELAY_buf;
		i :	INT;
		init :	BOOL;
		STOP :	INT;
	END_VAR

	STOP := LIMIT(0,N,32) - 1;
	IF RST OR NOT init THEN
		init := TRUE;
		FOR i := 0 TO STOP DO buf[i] := IN; END_FOR;
		OUT := IN;
		i := 0;
	ELSIF STOP < 0 THEN
		OUT := IN;
	ELSE
		OUT := buf[i];
		buf[i] := IN;
		i := INC1(i, N);
	END_IF;

END_FUNCTION_BLOCK

FUNCTION_BLOCK FT_AVG

	VAR_INPUT
		IN :	REAL;
		E :	BOOL := TRUE;
		N :	INT := INT#32;
		RST :	BOOL;
	END_VAR

	VAR_OUTPUT
		AVG :	REAL;
	END_VAR

	VAR
		buff :	DELAY;
		i :	INT;
		init :	BOOL;
	END_VAR


	buff.N := LIMIT(0, N, 32);

	IF NOT init OR RST THEN
		FOR i := 1 TO N DO
			buff(IN := IN);
		END_FOR;
		AVG := IN;
		init := TRUE;
	ELSIF E THEN
		buff(IN := IN);
		AVG := AVG + (IN - buff.OUT ) / INT_TO_REAL(N);
	END_IF;

END_FUNCTION_BLOCK

