FUNCTION_BLOCK FT_DERIV
	VAR_INPUT
		IN :	REAL;
		K :	REAL := 1.0;
		RUN :	BOOL := TRUE;
	END_VAR

	VAR_OUTPUT
		OUT :	REAL;
	END_VAR

	VAR
		old :	REAL;
		TX :	UDINT;
		last :	UDINT;
		init :	BOOL;
		tc :	REAL;
		T_PLC_US :	T_PLC_US_Block;
	END_VAR

	T_PLC_US();
	TX:= T_PLC_US.T_PLC_US;
	tc := UDINT_TO_REAL(TX - last);

	IF NOT init THEN
		init := TRUE;
		old := IN;
	ELSIF RUN AND tc > 0.0 THEN
		OUT := (IN - old) / tc * 1000000.0 * K;
		old := IN;
	ELSE
		OUT := 0.0;
	END_IF;

	last := TX;

	T_PLC_US();
	TX:= T_PLC_US.T_PLC_US;

	IF NOT init THEN
		init := TRUE;
	ELSIF RUN AND (TX - last) > UDINT#0 THEN
		OUT := (IN - old) / UDINT_TO_REAL(TX - last) * 1000000.0 * K;
	ELSE
		OUT := 0.0;
	END_IF;
	old := IN;
	last := TX;
END_FUNCTION_BLOCK

