	END_IF;

	(* limit the OUTputs *)
	IF OUT >= OUT_MAX THEN
		OUT := OUT_MAX;
		LIM := TRUE;
	ELSIF OUT <= OUT_MIN THEN
		OUT := OUT_MIN;
		LIM := TRUE;
	ELSE
		LIM := FALSE;
	END_IF;

END_FUNCTION_BLOCK

