FUNCTION_BLOCK FT_INT2_Block

	VAR_INPUT
		IN :	REAL;
		K :	REAL := 1.0;
		RUN :	BOOL := TRUE;
		RST :	BOOL;
		OUT_MIN :	REAL := REAL#-1.0E-37;
		OUT_MAX :	REAL := REAL#1.0E37;
	END_VAR

	VAR_OUTPUT
		OUT :	REAL;
		LIM :	BOOL;
	END_VAR

	VAR
		INTEG :	INTEGRATE;
		ix :	REAL;
		VAL :	REAL2;
		R2_ADD :	R2_ADD_Block;
		R2_SET :	R2_SET_Block;
	END_VAR

	IF RST THEN
		R2_SET(X:=0.0);
		VAL:=R2_SET.R2_SET;
		OUT := 0.0;
	ELSE
		INTEG(X := IN, E := RUN, K := K, Y := ix);
		ix := INTEG.Y;
		R2_ADD(X:=VAL,Y:=ix);
		VAL:=R2_ADD.R2_ADD;
		ix := 0.0;
		OUT := VAL.RX;
	END_IF;

	(* check OUTput for limits *)
	IF OUT > OUT_MIN AND OUT < OUT_MAX THEN
		LIM := FALSE;
	ELSE
		OUT := LIMIT(OUT_MIN, OUT, OUT_MAX);
		R2_SET(X:=OUT);
		VAL:=R2_SET.R2_SET;
		LIM := TRUE;
	END_IF;

END_FUNCTION_BLOCK

