FUNCTION_BLOCK FT_PID

	VAR_INPUT
		IN :	REAL;
		KP :	REAL := 1.0;
		TN :	REAL := 1.0;
		TV :	REAL := 1.0;
		ILIM_L :	REAL := -1.0E38;
		ILIM_H :	REAL := 1.0E38;
		IEN :	BOOL := TRUE;
		RST :	BOOL := FALSE;
	END_VAR

	VAR_OUTPUT
		Y :	REAL;
		LIM :	BOOL;
	END_VAR

	VAR
		INTEG :	FT_INT_Block;
		diff :	FT_DERIV;
	END_VAR


	IF TN > 0.0 THEN
		INTEG(IN := IN, K := 1.0 / TN, RUN := IEN, RST := RST, OUT_MIN := ILIM_L, OUT_MAX := ILIM_H);
	ELSE
		INTEG(RST := FALSE);
	END_IF;

	(* run differentiator *)
	diff(IN := IN, K := TV);

	(* combine both VALues *)
	Y := KP * (INTEG.OUT + diff.OUT + IN);

	(* check if INTEGrator has reached its limits and set OVERFLOW *)
	LIM := INTEG.LIM;

END_FUNCTION_BLOCK

