FUNCTION_BLOCK FT_PIDW

	VAR_INPUT
		IN :	REAL;
		KP :	REAL := 1.0;
		TN :	REAL := 1.0;
		TV :	REAL := 1.0;
		LIM_L :	REAL := -1.0E38;
		LIM_H :	REAL := 1.0E38;
		RST :	BOOL := FALSE;
	END_VAR


	VAR_OUTPUT
		Y :	REAL;
		LIM :	BOOL;
	END_VAR


	VAR
		INTEG :	INTEGRATE;
		diff :	FT_DERIV;
		YI :	REAL;
	END_VAR


	IF TN = 0.0 OR RST THEN
		INTEG(E := FALSE, Y := YI);
		YI := INTEG.Y;
		YI := 0.0;
	ELSE
		INTEG(X := IN, K := 1.0 / TN, E := NOT LIM, Y := YI);
		YI := INTEG.Y;
	END_IF;

	(* add up INTEGrator and linear part *)
	Y := KP * (IN + YI);

	(* run differentiator *)
	diff(IN := IN, K := TV);

	(* set lim before differentiator is added to STOP INTEGrator if necessary *)
	IF Y > LIM_L AND Y < LIM_H THEN
		LIM := FALSE;
	ELSE
		LIM := TRUE;
	END_IF;

	Y := LIMIT(LIM_L, Y + KP * diff.OUT, LIM_H);

END_FUNCTION_BLOCK

