FUNCTION_BLOCK FT_PIWL

	VAR_INPUT
		IN :	REAL;
		KP :	REAL := 1.0;
		KI :	REAL := 1.0;
		LIM_L :	REAL := -1.0E38;
		LIM_H :	REAL := 1.0E38;
		RST :	BOOL;
	END_VAR

	VAR_OUTPUT
		Y :	REAL;
		LIM :	BOOL;
	END_VAR

	VAR
		init :	BOOL;
		TX :	UDINT;
		tc :	REAL;
		t_last :	UDINT;
		in_last :	REAL;
		i :	REAL;
		p :	REAL;
		T_PLC_US :	T_PLC_US_Block;
	END_VAR

	IF NOT init OR RST THEN
		init := TRUE;
		in_last := IN;
		T_PLC_US();
		t_last := T_PLC_US.T_PLC_US;
		i := 0.0;
		tc := 0.0;
	ELSE
		(* read last cycle time IN Microseconds *)
		T_PLC_US();
		TX := T_PLC_US.T_PLC_US;
		tc := UDINT_TO_REAL(TX - t_last);
		t_last := TX;

		(* calculate proportional part *)
		p := KP * IN;

		(* run INTEGrator *)
		i := (IN + in_last) * 5.0E-7 * KI * tc + i;
		in_last := IN;

		(* calculate OUTput Y *)
		Y := p + i;

		(* check OUTput for limits *)
		IF Y >= LIM_H THEN
			Y := LIM_H;
			IF KI <> 0.0 THEN
				i := LIM_H - p;
			ELSE
				i := 0.0;
			END_IF;
			LIM := TRUE;
		ELSIF Y <= LIM_L THEN
			Y := LIM_L;
			IF KI <> 0.0 THEN
				i := LIM_L - p;
			ELSE
				i := 0.0;
			END_IF;
			LIM := TRUE;
		ELSE
			LIM := FALSE;
		END_IF;
	END_IF;
END_FUNCTION_BLOCK

