FUNCTION_BLOCK INTEGRATE

	VAR_INPUT
		E :	BOOL := TRUE;
		X :	REAL;
		K :	REAL := 1.0;
	END_VAR

	VAR_IN_OUT
		Y :	REAL;
	END_VAR

	VAR
		X_LAST :	REAL;
		init :	BOOL;
		T_PLC_MS :	T_PLC_MS_block;
		last :	UDINT;
		TX :	UDINT;
	END_VAR


	T_PLC_MS();
	TX:= T_PLC_MS.T_PLC_MS;

	IF NOT init THEN
		init := TRUE;
		X_LAST := X;
	ELSIF E THEN
		Y := (X + X_LAST) * 0.5E-3 * UDINT_TO_REAL(TX-last) * K + Y;
		X_LAST := X;
	END_IF;
	last := TX;

END_FUNCTION_BLOCK

FUNCTION_BLOCK FT_PT2

	VAR_INPUT
		IN :	REAL;
		T :	TIME;
		D :	REAL;
		K :	REAL := 1.0;
	END_VAR

	VAR_OUTPUT
		OUT :	REAL;
	END_VAR

	VAR
		init :	BOOL;
		int1 :	INTEGRATE;
		int2 :	INTEGRATE;
		TN :	REAL;
		I1 :	REAL;
		I2 :	REAL;
		tn2 :	REAL;
	END_VAR

	IF NOT init OR T = T#0s THEN
		init := TRUE;
		OUT := K * IN;
		I2 := OUT;
	ELSE
		TN := TIME_TO_REAL(T) / 1000.0;
		tn2 := TN * TN;
		int1(X := IN * K / tn2 - I1 * 0.5 * D / TN - I2 / tn2, Y := I1);
		I1 := int1.Y;
		int2(X := I1,Y := I2);
		I2 := int2.Y;
		OUT := I2;
	END_IF;

END_FUNCTION_BLOCK

