		IN :	REAL;
		T :	TIME;
		D :	REAL;
		K :	REAL := 1.0;

		OUT :	REAL;

		func_block : FT_PT2;
	END_VAR
	func_block.IN := IN;
	func_block.T := T;
	func_block.D := D;
	func_block.K := K;
	func_block();
	OUT := func_block.OUT;
