FUNCTION_BLOCK FT_RMP

	VAR_INPUT
		RMP :	BOOL := TRUE;
		IN :	REAL;
		KR :	REAL;
		KF :	REAL;
	END_VAR

	VAR_OUTPUT
		OUT :	REAL;
		BUSY :	BOOL;
		UD :	BOOL;
	END_VAR

	VAR
		TX :	TIME;
		last :	TIME;
		init :	BOOL;
		T_PLC_MS :	T_PLC_MS_block;
	END_VAR

	T_PLC_MS();
	TX:= SUB_TIME(UDINT_TO_TIME(T_PLC_MS.T_PLC_MS), last);

	IF NOT init THEN
		init := TRUE;
		last := TX;
		TX := t#0s;
		OUT := IN;
	END_IF;
	IF NOT RMP THEN
		OUT := IN;
		BUSY := FALSE;
	ELSIF OUT > IN THEN
		(* ramp down *)
		OUT := OUT - TIME_TO_REAL(TX) * 0.001 * KF;
		OUT := MAX(IN, OUT);
	ELSIF OUT < IN THEN
		(* ramp up *)
		OUT := OUT + TIME_TO_REAL(TX) * 0.001 * KR;
		OUT := MIN(IN, OUT);
	END_IF;

	(* set BUSY and DIR flags *)
	IF OUT < IN THEN
		BUSY := TRUE;
		UD := TRUE;
	ELSIF OUT > IN THEN
		BUSY := TRUE;
		UD := FALSE;
	ELSE
		BUSY := FALSE;
	END_IF;
	last := ADD_TIME(last, TX);

END_FUNCTION_BLOCK

