FUNCTION GCD:INT

	VAR_INPUT
		A :	DINT;
		B :	DINT;
	END_VAR


	VAR
		t :	DINT;
		_A :	DINT;
		_B :	DINT;
	END_VAR

	_A := A;
	_B := B;

	IF _A = DINT#0 THEN
		GCD := DINT_TO_INT(ABS(_B));
	ELSIF _B = DINT#0 THEN
		GCD := DINT_TO_INT(ABS(_A));
	ELSE
		_A := ABS(_A);
		_B := ABS(_B);
		GCD := 1;

		WHILE NOT((DINT_TO_DWORD(_A) AND DWORD#1) > DWORD#0 OR (DINT_TO_DWORD(_B) AND DWORD#1) > DWORD#0) DO
			_A := DWORD_TO_DINT(SHR(DINT_TO_DWORD(_A),1));
			_B := DWORD_TO_DINT(SHR(DINT_TO_DWORD(_B),1));
			GCD := DWORD_TO_INT(SHR(INT_TO_DWORD(GCD),1));
		END_WHILE;
		WHILE _A > DINT#0 DO
			IF NOT((DINT_TO_DWORD(_A) AND DWORD#1) > DWORD#0) THEN
				_A := DWORD_TO_DINT(SHR(DINT_TO_DWORD(_A),1));
			ELSIF NOT((DINT_TO_DWORD(_B) AND DWORD#1) > DWORD#0) THEN
				_B := DWORD_TO_DINT(SHR(DINT_TO_DWORD(_B),1));
			ELSE
				t := DWORD_TO_DINT(SHR(DINT_TO_DWORD(ABS(_A-_B)),1));
				IF _A < _B THEN
					_B := t;
				ELSE
					_A := t;
				END_IF;
			END_IF;
		END_WHILE;
		GCD := GCD * DINT_TO_INT(_B);
	END_IF;

END_FUNCTION

PROGRAM program0
  VAR
    A :	DINT;
	B :	DINT;
    LocalOUT  : INT;
  END_VAR

  LocalOUT := GCD(A, B);
END_PROGRAM

FUNCTION GDF:REAL

	VAR_INPUT
		X :	REAL;
	END_VAR

	IF X = 0.0 THEN
		GDF := 0.0;
	ELSIF X > 15.0 THEN
		GDF := 1.5707963267949;
	ELSIF X < -15.0 THEN
		GDF := -1.5707963267949;
	ELSE
		GDF := ATAN(EXP(X)) * 2.0 - 1.5707963267949;
	END_IF;

END_FUNCTION

PROGRAM program0
  VAR
    X :	REAL;
    LocalOUT  : REAL;
  END_VAR

  LocalOUT := GDF(X);
END_PROGRAM

FUNCTION BIT_OF_DWORD : BOOL
  VAR_INPUT
    IN : DWORD;
    N : INT;
  END_VAR

  BIT_OF_DWORD := (SHR(IN,N) AND 16#00000001) > 0;
END_FUNCTION

FUNCTION_BLOCK GEN_BIT_Block

	VAR_INPUT
		IN0 :	DWORD;
		IN1 :	DWORD;
		IN2 :	DWORD;
		IN3 :	DWORD;
		CLK :	BOOL;
		STEPS :	INT;
		REP :	INT;
		RST :	BOOL;
	END_VAR


	VAR_OUTPUT
		Q0 :	BOOL;
		Q1 :	BOOL;
		Q2 :	BOOL;
		Q3 :	BOOL;
		CNT :	INT;
		RUN :	BOOL;
	END_VAR


	VAR
		r0 :	DWORD;
		R1  :	DWORD;
		R2 :	DWORD;
		r3 :	DWORD;
		rx :	INT := 1;
	END_VAR

	IF CLK AND NOT RST THEN
		RUN := (REP = 0) OR (rx <= REP);
		IF RUN THEN
			IF CNT = STEPS THEN
				CNT := 0;
			END_IF;

			IF CNT = 0 THEN
				r0 := IN0;
				R1  := IN1;
				R2 := IN2;
				r3 := IN3;
			END_IF;

			IF (CNT < STEPS) THEN
				Q0 := BIT_OF_DWORD(r0,0);
				Q1 := BIT_OF_DWORD(R1 ,0);
				Q2 := BIT_OF_DWORD(R2,0); 
				Q3 := BIT_OF_DWORD(r3,0); 
				r0 := SHR(r0,1);
				R1  := SHR(R1 ,1);
				R2 := SHR(R2,1);
				r3 := SHR(r3,1);
			END_IF;

			CNT := CNT +1;
			IF (CNT = STEPS) AND (REP <> 0) THEN rx := rx +1; END_IF;
			IF (rx > REP) AND (REP <> 0) THEN RUN := FALSE; END_IF;
		END_IF;
	ELSE
		IF RST THEN
			RUN := FALSE;
			Q0 := FALSE;
			Q1 := FALSE;
			Q2 := FALSE;
			Q3 := FALSE;
			r0 := DWORD#0;
			R1  := DWORD#0;
			R2 := DWORD#0;
			r3 := DWORD#0;
			CNT := 0;
			rx := 1;
		END_IF;
	END_IF;

END_FUNCTION_BLOCK

