  END_VAR
	func_block.IN0  :=IN0;
	func_block.IN1  :=IN1;
	func_block.IN2  :=IN2;
	func_block.IN3  :=IN3;
	func_block.CLK  :=CLK;
	func_block.STEPS  :=STEPS;
	func_block.REP  :=REP;
	func_block.RST  :=RST;
	func_block();
	Q0 := func_block.Q0;
	Q1 := func_block.Q1;
	Q2 := func_block.Q2;
	Q3 := func_block.Q3;
	CNT := func_block.CNT;
	RUN := func_block.RUN;

END_PROGRAM

