		TL2 :	TIME;
		TS :	BOOL;
	END_VAR


	VAR_OUTPUT
		Q :	BOOL;
		TH :	TIME;
		TL :	TIME;
	END_VAR


	VAR
		T_PLC_MS :	T_PLC_MS_block;
		t_HIGH :	TIME;
		t_LOW :	TIME;
		TX :	TIME;
		START :	TIME;
		init :	BOOL;
		et :	TIME;
	END_VAR

	T_PLC_MS();
	TX:= UDINT_TO_TIME(T_PLC_MS.T_PLC_MS);

	IF NOT init THEN
		START := TX;
		init := TRUE;
		TH := T#0s;
		TL := T#0s;
	END_IF;

	IF TS THEN
		t_HIGH := TH2;
		t_LOW := TL2;
	ELSE
		t_HIGH := TH1;
		t_LOW := TL1;
	END_IF;

	IF ENQ THEN
		et := SUB_TIME(TX , START);
		IF NOT Q THEN
			IF et >= t_LOW THEN
				Q := TRUE;
				START := TX;
				TL := T#0s;
			ELSE
				TL := et;
			END_IF;
		ELSE
			IF et >= t_HIGH THEN
				Q := FALSE;
				START := TX;
				TH := T#0s;
			ELSE
				TH := et;
			END_IF;
		END_IF;
	ELSE
		Q := FALSE;
		TH := T#0s;
		TL := T#0s;
		START := TX;
	END_IF;

END_FUNCTION_BLOCK

