	END_VAR


	VAR
		TX :	TIME;
		last :	TIME;
		init :	BOOL;
		T_PLC_MS :	T_PLC_MS_block;
		FB_rdm :	RDM_Block;
	END_VAR

	T_PLC_MS();
	TX:= SUB_TIME(UDINT_TO_TIME(T_PLC_MS.T_PLC_MS) , last);

	IF NOT init THEN
		init := TRUE;
		last := TX;
		TX := t#0s;
	END_IF;

	IF TX >= PT THEN
		last := ADD_TIME(last , PT);
		TX := SUB_TIME(TX, PT);

		FB_rdm(LAST:=0.0);
		OUT := AM * (FB_rdm.RDM - 0.5) + OS;
		Q := TRUE;
	ELSE
		Q := FALSE;
	END_IF;

END_FUNCTION_BLOCK

