FUNCTION_BLOCK GEN_SQR_Block

	VAR_INPUT
		PT :	TIME;
		AM :	REAL := REAL#1.0;
		OS :	REAL;
		DC :	REAL := REAL#0.5;
		DL :	REAL;
	END_VAR


	VAR_OUTPUT
		Q :	BOOL;
		Out :	REAL;
	END_VAR


	VAR
		TX :	TIME;
		last :	TIME;
		init :	BOOL;
		DLL: REAL;
		DCC: REAL;
		T_PLC_MS :	T_PLC_MS_block;
	END_VAR

	IF DC = 0.0 THEN
		Out := -AM * 0.5 + OS;
		Q := FALSE;
		RETURN;
	ELSIF DC = 1.0 THEN
		Out := AM * 0.5 + OS;
		Q := TRUE;
		RETURN;
	END_IF;

	T_PLC_MS();
	TX:= SUB_TIME(UDINT_TO_TIME(T_PLC_MS.T_PLC_MS) , last);
	DLL := MODR(DL,1.0);
	IF DLL < 0.0 THEN DLL := 1.0 - DLL; END_IF;
	DCC := MODR(DC,1.0);
	IF DCC < 0.0 THEN DCC := 1.0 - DCC; END_IF;

	IF NOT init THEN
		init := TRUE;
		last := TX;
		TX := t#0s;
	END_IF;

	IF TX >= PT THEN
		last := ADD_TIME( last , PT);
		TX := SUB_TIME(TX, PT);
	END_IF;

	IF MULTIME_B(PT, DL + DC) >= PT THEN
		IF TX >= MULTIME_B(PT, DL + DC - 1.0) THEN
			Out := -AM * 0.5 + OS;
			Q := FALSE;
		END_IF;
		IF TX >= MULTIME_B(PT, DL) THEN
			Out := AM * 0.5 + OS;
			Q := TRUE;
		END_IF;
	ELSE
		IF TX >= MULTIME_B(PT, DL) THEN
			Out := AM * 0.5 + OS;
			Q := TRUE;
		END_IF;
		IF TX >= MULTIME_B(PT, DL + DC) THEN
			Out := -AM * 0.5 + OS;
			Q := FALSE;
		END_IF;
	END_IF;

END_FUNCTION_BLOCK

