		ONN :	REAL;
		OFF :	REAL;
	END_VAR


	VAR_OUTPUT
		Q :	BOOL;
		WIN :	BOOL;
	END_VAR

	IF ONN >= OFF THEN
		IF IN < OFF THEN
			Q := FALSE;
			WIN := FALSE;
		ELSIF  IN > ONN THEN
			Q := TRUE;
			WIN := FALSE;
		ELSE
			WIN := TRUE;
		END_IF;
	ELSE
		IF IN > OFF THEN
			Q := FALSE;
			WIN := FALSE;
		ELSIF  IN < ONN THEN
			Q := TRUE;
			WIN := FALSE;
		ELSE
			WIN := TRUE;
		END_IF;
	END_IF;

