		_r_edge :	BOOL;
		edge :	BOOL;
	END_VAR

	IF NOT MAN THEN
		Q := INN;
		STATUS := BYTE#100;
		edge := FALSE;
	ELSIF NOT s_edge AND SET THEN
		Q := TRUE;
		edge := TRUE;
		STATUS := BYTE#101;
	ELSIF NOT _r_edge AND RST THEN
		Q := FALSE;
		edge := TRUE;
		STATUS := BYTE#102;
	ELSIF NOT edge THEN
		Q := M_I;
		STATUS := BYTE#103;
	END_IF;

	(* remember levels of MANUAL SIGNals *)
	s_edge := SET;
	_r_edge := RST;

