		Q3 :	BOOL;
		STATUS :	BYTE;
	END_VAR


	VAR
		edge :	BOOL;
		POS :	INT;
		tog :	BOOL;
	END_VAR

	IF man THEN
		IF NOT TOG THEN
			Q0 := M0;
			Q1 := M1;
			Q2 := M2;
			Q3 := M3;
			STATUS := BYTE#101;
		END_IF;
		IF STP AND NOT edge THEN
			tog := TRUE;
			CASE POS OF
				0:	Q0 := TRUE;
					Q1 := FALSE;
					Q2 := FALSE;
					Q3 := FALSE;
					STATUS := BYTE#110;
				1:	Q0 := FALSE;
					Q1 := TRUE;
					Q2 := FALSE;
