					Q3 := FALSE;
					STATUS := BYTE#112;
				3:	Q0 := FALSE;
					Q1 := FALSE;
					Q2 := FALSE;
					Q3 := TRUE;
					STATUS := BYTE#113;
			END_CASE;
			POS := INC(POS,1,3);
		END_IF;
	ELSE
		Q0 := I0;
		Q1 := I1;
		Q2 := I2;
		Q3 := I3;
		STATUS := BYTE#100;
		tog := FALSE;
		POS := 0;
	END_IF;

	edge := STP;

