TYPE REAL2:

	STRUCT
		R1  : REAL;
		RX : REAL;
	END_STRUCT;

END_TYPE

FUNCTION_BLOCK R2_ADD_Block

	VAR_INPUT
		X :	REAL2;
		Y :	REAL;
	END_VAR

	VAR_OUTPUT
		R2_ADD :	REAL2;
	END_VAR

	VAR
		temp :	REAL;
	END_VAR


	temp := X.RX;
	R2_ADD.RX := Y + X.R1  + X.RX;
	R2_ADD.R1  := temp - R2_ADD.RX + Y + X.R1 ;

END_FUNCTION_BLOCK


FUNCTION_BLOCK T_PLC_MS_block
	VAR_OUTPUT
		T_PLC_MS :	UDINT;
	END_VAR

	VAR
		PLC_TICKS_PER_SEC :	INT;
		PLC_SYS_TICK_CNT :	DINT;
	END_VAR

	VAR
		debug :	BOOL;(*Debug-Mode ON / OFF*)
		N :	INT;(*Debug-Faktor*)
		Offset :	UDINT;(*Debug-Offset*)
		temp :	DWORD := DWORD#1;(*Debug-Offset*)
		MODE :	BOOL;(*modus*)
		faktor :	UDINT;(*Systemtakt-Faktor*)
		init :	BOOL;
		v_plc_ticks_per_sec :	UDINT;
		base :	UDINT := UDINT#1000;
	END_VAR


	IF init = FALSE THEN
		v_plc_ticks_per_sec := INT_TO_UDINT(PLC_TICKS_PER_SEC);
		IF v_plc_ticks_per_sec = UDINT#1024 THEN
			faktor := UDINT#1;
			MODE := FALSE;
		ELSIF v_plc_ticks_per_sec > UDINT#0 THEN
			IF v_plc_ticks_per_sec <= base THEN
				faktor := base / v_plc_ticks_per_sec;
				MODE := FALSE;
			ELSE
				faktor := v_plc_ticks_per_sec / base;
				MODE := TRUE;
			END_IF;
		ELSE
			faktor := UDINT#1;
		END_IF;
		init := TRUE;
	END_IF;

	IF MODE THEN
		T_PLC_MS := DINT_TO_UDINT(PLC_SYS_TICK_CNT) / faktor;
	ELSE
		T_PLC_MS := DINT_TO_UDINT(PLC_SYS_TICK_CNT) * faktor;
	END_IF;

	IF debug THEN
		T_PLC_MS := (DWORD_TO_UDINT(SHL(UDINT_TO_DWORD(T_PLC_MS),N) OR SHL(temp,N)) - UDINT#1) + Offset;
	END_IF;
END_FUNCTION_BLOCK

FUNCTION_BLOCK METER_Block

	VAR_INPUT
		M1 :	REAL;
		M2 :	REAL;
		I1 :	BOOL;
		I2 :	BOOL;
		D :	REAL := 1.0;
		RST :	BOOL;
	END_VAR

	VAR_IN_OUT
		MX :	REAL;
	END_VAR


	VAR RETAIN 
		MR :	REAL2;
	END_VAR


	VAR
		MX1 :	REAL;(*current consumPTion VALue on M1 and M2*)
		MX2 :	REAL;(*current consumPTion VALue on M1 and M2*)
		TX :	UDINT;
		last :	UDINT;
		tc :	REAL;
		init :	BOOL;
		T_PLC_MS :	T_PLC_MS_block;
		R2_ADD :	R2_ADD_Block;
	END_VAR


	T_PLC_MS();
	TX:= T_PLC_MS.T_PLC_MS;
	IF NOT init THEN
		init := TRUE;
		last := TX;
		mr.RX := mx;
		mr.R1  := 0.0;
	ELSIF TX = last THEN
		RETURN;
	ELSE
		tc := UDINT_TO_REAL(TX - last) * 0.001;
	END_IF;
	last := TX;

	(* reset *)
	IF RST THEN
		mr.R1  := 0.0;
		mr.RX := 0.0;
	ELSE
		MX1 := SEL(I1,0.0,M1);
		MX2 := SEL(I2,0.0,M2);
		R2_ADD(X:=MR,Y:=(SEL(I1,0.0,mX1) + SEL(I2, 0.0, mX2)) / D * TC);
		MR:=R2_ADD.R2_ADD;
		MX := mr.RX;
	END_IF;

END_FUNCTION_BLOCK


PROGRAM program0

	VAR
		M1 :	REAL;
		M2 :	REAL;
		I1 :	BOOL;
		I2 :	BOOL;
		D :	REAL := 1.0;
		RST :	BOOL;

		MX :	REAL;

		func_block : METER_Block;
	END_VAR

	func_block.M1 := M1;
	func_block.M2 := M2;
	func_block.I1 := I1;
	func_block.I2 := I2;
	func_block.D := D;
	func_block.RST := RST;
	func_block.MX := MX;

	func_block();

	MX  := func_block.MX;

END_PROGRAM

FUNCTION DAY_OF_WEEK:INT

	VAR_INPUT
		IDATE :	UDINT;
	END_VAR


	DAY_OF_WEEK := UDINT_TO_INT((IDATE / UDINT#86400 + UDINT#3) MOD UDINT#7) + INT#01;
END_FUNCTION

FUNCTION LEAP_OF_DATE:BOOL

	VAR_INPUT
		IDATE :	UDINT;
	END_VAR

	LEAP_OF_DATE := SHL(UDINT_TO_DWORD((IDATE + UDINT#43200) / UDINT#31557600), 30) = DWORD#16#80000000;
END_FUNCTION

FUNCTION DAY_OF_YEAR:INT
	VAR_INPUT
		IDATE :	UDINT;
	END_VAR

	DAY_OF_YEAR  := UDINT_TO_INT(((IDATE) / UDINT#86400) MOD UDINT#1461);
	IF DAY_OF_YEAR  > 729 THEN
		IF DAY_OF_YEAR  > 1095 THEN DAY_OF_YEAR  := DAY_OF_YEAR  - 1095; ELSE DAY_OF_YEAR  := DAY_OF_YEAR  - 729; END_IF;
	ELSIF DAY_OF_YEAR  > 364 THEN
		DAY_OF_YEAR  := DAY_OF_YEAR  - 364;
	ELSE
		DAY_OF_YEAR  := DAY_OF_YEAR  + 1;
	END_IF;
END_FUNCTION

FUNCTION MONTH_OF_DATE:INT

	VAR_INPUT
		IDATE :	UDINT;
	END_VAR

	MONTH_OF_DATE := DAY_OF_YEAR(IDATE);
	IF MONTH_OF_DATE < 32 THEN
		MONTH_OF_DATE := 1;
	ELSIF LEAP_OF_DATE((IDATE)) THEN
		MONTH_OF_DATE := (MONTH_OF_DATE * 53 + 1668) / 1623;
	ELSE
		MONTH_OF_DATE := (MONTH_OF_DATE * 53 + 1700) / 1620;
	END_IF;
END_FUNCTION

FUNCTION YEAR_OF_DATE:INT
	VAR_INPUT
		IDATE :	UDINT;
	END_VAR

	YEAR_OF_DATE := UDINT_TO_INT((IDATE+UDINT#43200) / UDINT#31557600 + UDINT#1970);
END_FUNCTION


FUNCTION_BLOCK METER_STAT_Block

	VAR_INPUT
		IN :	REAL;
		DI :	UDINT;
		RST :	BOOL;
	END_VAR


	VAR_IN_OUT
		LAST_DAY  :	REAL;
		CURRENT_DAY  :	REAL;
		LAST_WEEK :	REAL;
		CURRENT_WEEK :	REAL;
		LAST_MONTH :	REAL;
		CURRENT_MONTH :	REAL;
		LAST_YEAR  :	REAL;
		CURRENT_YEAR  :	REAL;
	END_VAR


	VAR RETAIN 
		YEAR_START :	REAL;
		MONTH_START :	REAL;
		week_START :	REAL;
		DAY_START :	REAL;
		last_run :	UDINT;
	END_VAR

	IF RST THEN
		Last_DAY  := 0.0;
		Current_DAY  := 0.0;
		DAY_START := IN;
		Last_week := 0.0;
		Current_week := 0.0;
		Week_START := IN;
		Last_MONTH := 0.0;
		Current_MONTH := 0.0;
		MONTH_START := IN;
		last_YEAR  := 0.0;
		current_YEAR  := 0.0;
		YEAR_START := IN;
	ELSE
		Current_DAY  := IN - DAY_START;
		Current_Week := In - Week_START;
		Current_MONTH := IN - MONTH_START;
		Current_YEAR  := IN - YEAR_START;
	END_IF;

	IF YEAR_OF_DATE(DI) > YEAR_OF_DATE(last_run) THEN
		(* a new YEAR  has STARTed *)
		last_YEAR  := current_YEAR;
		current_YEAR  := 0.0;
		YEAR_START := IN;
		last_MONTH := current_MONTH;
		current_MONTH := 0.0;
		MONTH_START := IN;
		last_DAY  := current_DAY;
		current_DAY  := 0.0;
		DAY_START := IN;
	ELSIF MONTH_OF_DATE(DI) > MONTH_OF_DATE(last_run) THEN
		(* a new MONTH has STARTed, january is alrerady done by YEAR  CHAnge *)
		last_MONTH := current_MONTH;
		current_MONTH := 0.0;
		MONTH_START := IN;
		last_DAY  := current_DAY;
		current_DAY  := 0.0;
		DAY_START := IN;
	ELSIF DAY_OF_YEAR(DI) > DAY_OF_YEAR(last_run) THEN
		(* DAY  has CHAged, fiRST DAY  of YEAR  and fiRST DAY  of MONTH has already been taken care of *)
		last_DAY  := current_DAY;
		current_DAY  := 0.0;
		DAY_START := IN;
	END_IF;
	IF DAY_OF_WEEK(DI) < DAY_OF_WEEK(last_run) THEN
		(* a new week has STARTed *)
		last_week := current_week;
		current_week := 0.0;
		week_START := IN;
	END_IF;
	last_run := di;

END_FUNCTION_BLOCK


