	func_block();
	MIRROR  := func_block.MIRROR;

END_PROGRAM

FUNCTION MIX:REAL

	VAR_INPUT
		A :	REAL;
		B :	REAL;
		M :	REAL;
	END_VAR

	MIX := (1.0 - M) * A + M * B;

END_FUNCTION

PROGRAM program0
	VAR
		A :	REAL;
		B :	REAL;
		M :	REAL;

		OUT : REAL;
	END_VAR

	OUT := MIX(A, B, M);

END_PROGRAM

FUNCTION FLOOR2 : DINT
	VAR_INPUT
		X : REAL;
	END_VAR

	FLOOR2 := REAL_TO_DINT(X);
	IF DINT_TO_REAL(FLOOR2) > X THEN
		FLOOR2 := FLOOR2 - DINT#1;
	END_IF;

END_FUNCTION

FUNCTION MODR: REAL

	VAR_INPUT
		IN :	REAL;
		DIVI :	REAL;
	END_VAR

	IF DIVI = 0.0 THEN
		MODR := 0.0;
	ELSE
		MODR := IN - DINT_TO_REAL(FLOOR2(IN / DIVI)) * DIVI;
	END_IF;

END_FUNCTION

