TYPE
	oscat_aW0_255	: ARRAY [0..255] OF WORD;
	oscat_NW_BUF_SHORT : ARRAY [0..1407] OF BYTE;
	oscat_NW_BUF_LONG  : ARRAY [0..4095] OF BYTE;

