	END_VAR

	VAR_IN_OUT
		PT :	oscat_NW_BUF_LONG;
	END_VAR

	VAR
		POS :	INT;
		SIZE2 :	INT;
	END_VAR

	POS := 0;
	SIZE2 := UINT_TO_INT(SIZE);

	WHILE POS < SIZE2 DO
		PT[POS] := TO_UPPER(PT[POS]);
		POS := POS + 1;
	END_WHILE;

	_BUFFER_UPPERCASE := TRUE;

END_FUNCTION_BLOCK

