FUNCTION_BLOCK TP_X
	VAR_INPUT
		IN :	BOOL;
		PT :	TIME;
	END_VAR


	VAR_OUTPUT
		Q :	BOOL;
		ET :	TIME;
	END_VAR


	VAR
		edge :	BOOL;
		START :	TIME;
		TX :	TIME;
		T_PLC_MS :	T_PLC_MS_block;
	END_VAR


	T_PLC_MS();
	TX := UDINT_TO_TIME(T_PLC_MS.T_PLC_MS);

	IF IN AND NOT edge THEN
		START := TX;
		Q := PT > t#0ms;
	ELSIF Q THEN
		ET := TX - START;
		IF ET >= PT THEN
			Q := FALSE;
			ET := t#0ms;
		END_IF;
	END_IF;
	edge := IN;

END_FUNCTION_BLOCK

FUNCTION_BLOCK PWM_DC
	VAR_INPUT
		F :	REAL;
		DC :	REAL;
	END_VAR

	VAR_OUTPUT
		Q :	BOOL;
	END_VAR

	VAR
		CLK :	CLK_Prg;
		pulse :	TP_X;
		tmp :	REAL;
	END_VAR

	IF F > 0.0 THEN
		tmp := 1000.0/F;
		CLK(PT := REAL_TO_TIME2(tmp));
		Pulse(IN := CLK.Q, PT := REAL_TO_TIME2(tmp*DC));
		Q := pulse.Q;
	END_IF;
END_FUNCTION_BLOCK

