FUNCTION_BLOCK FINDP_Block

	VAR_INPUT
		STR :	STRING;
		SRC :	STRING;
		POS :	INT;
	END_VAR


	VAR_OUTPUT
		FINDP :	INT;
	END_VAR

	VAR
		i :	INT;
		ls :	INT;
		lx :	INT;
		stp :	INT;
		st_tmp :	STRING;
	END_VAR


	ls := LEN(STR);
	lx := LEN(SRC);
	IF ls < lx OR lx = 0 THEN RETURN; END_IF;
	stp := ls - lx + 1;
	FOR i := MAX(POS,1) TO stp DO
		st_tmp := MID(STR,lx,i);
		IF EQ_STRING(st_tmp,src) THEN
			FINDP := i;
			RETURN;
		END_IF;
	END_FOR;
	FINDP := 0;

END_FUNCTION_BLOCK

FUNCTION_BLOCK REPLACE_ALL_Block

	VAR_INPUT
		STR :	STRING;
		SRC :	STRING;
		REP :	STRING;
	END_VAR


	VAR_OUTPUT
		REPLACE_ALL :	STRING;
	END_VAR

	VAR
		POS :	INT;
		lp :	INT;
		lx :	INT;
		FINDP :	FINDP_Block;
		st_tmp :	STRING;
	END_VAR


	REPLACE_ALL := str;
	lx := LEN(SRC);
	lp := LEN(rep);

	FINDP.str := REPLACE_ALL;
	FINDP.src := src;
	FINDP.POS := 1;
	FINDP();
	POS := FINDP.FINDP;

	WHILE POS > 0 DO
		st_tmp := REPLACE_ALL;
		REPLACE_ALL := REPLACE(st_tmp,rep,lx,POS);

		FINDP.str := REPLACE_ALL;
		FINDP.src := src;
		FINDP.POS := POS + lp;
		FINDP();
		POS := FINDP.FINDP;

	END_WHILE;

END_FUNCTION_BLOCK

