FUNCTION_BLOCK RMP_SOFT_Block

	VAR_INPUT
		IN :	BOOL;
		VAL :	BYTE;
		PT_ON :	TIME := T#100ms;
		PT_OFF :	TIME := T#100ms;
	END_VAR

	VAR_OUTPUT
		OUT :	BYTE := BYTE#00;
	END_VAR


	VAR
		rmp :	_RMP_B;
		tmp :	BYTE;
	END_VAR


	tmp := SEL(IN, BYTE#0, VAL);
	IF tmp > OUT THEN
		(* we need to ramp down *)
		rmp(DIR := TRUE, E := TRUE, TR := PT_ON, RMP := OUT);
		OUT := rmp.RMP; 
		(* make sure OUT does not surpass tmp *)
		OUT := MIN(OUT, tmp);
	ELSIF tmp < OUT THEN
		(* we need to ramp up *)
		rmp(DIR := FALSE, E := TRUE, TR := PT_OFF, RMP := OUT);
		OUT := rmp.RMP; 
		(* make sure OUT does not surpass tmp *)
		OUT := MAX(OUT, tmp);
	ELSE
		(* no ramp necessary *)
		rmp(E := FALSE, RMP := OUT);
		OUT := rmp.RMP; 
	END_IF;


END_FUNCTION_BLOCK


