	RT(SET := SET, SDT := SDT, SMS := SMS);
	UDT := rt.xdt;
	XMS := rt.XMS;

	dso := DST(udt) AND DEN;

	LDT := UDT + _INT_TO_UDINT(ofs + BOOL_TO_INT(DSO) * 60) * UDINT#60;

