TYPE
  oscat_FILE_SERVER_DATA : STRUCT
	FILE_OPEN	: BOOL;
    FILENAME 	: STRING;
    MODE	 	: BYTE;
    OFFSET   	: UDINT;
    FILE_SIZE   : UDINT;
    AUTO_CLOSE	: TIME;
    ERROR	 	: BYTE;
  END_STRUCT;

  oscat_NW_BUF_LONG  : ARRAY [0..4095] OF BYTE;
  oscat_NETWORK_BUFFER :
  STRUCT
    SIZE   : UINT;	
    BUFFER : oscat_NW_BUF_LONG;
  END_STRUCT;
END_TYPE

FUNCTION_BLOCK FILE_BLOCK

	VAR_IN_OUT
		MODE :	BYTE;
		FILENAME :	STRING;
		FSD :	oscat_FILE_SERVER_DATA;
		PT :	oscat_NETWORK_BUFFER;
	END_VAR

	VAR_INPUT
		POS :	UDINT;
	END_VAR

	VAR_OUTPUT
		ERROR :	BYTE;
		DATA :	BYTE;
	END_VAR

	VAR
		STEPP :	INT;
		i :	INT;
		data_START :	UDINT;
		data_STOP :	UDINT;
	END_VAR

	CASE STEPP OF
	0:	IF MODE > BYTE#0 THEN
			ERROR := BYTE#0;
			IF FSD.FILE_OPEN AND (FSD.FILE_SIZE = UDINT#0 OR POS >= FSD.FILE_SIZE) THEN
				ERROR := BYTE#255;
				MODE := BYTE#0;
			ELSIF POS < data_START OR POS > data_STOP OR NOT FSD.FILE_OPEN THEN 
				FSD.FILENAME := FILENAME;
				FSD.MODE := BYTE#1; 
				FSD.OFFSET := POS;
				PT.SIZE := UINT#65535; 
				data_START := UDINT#0;
				data_STOP := UDINT#0;
				STEPP := 10;
			ELSE 
				i := UDINT_TO_INT(POS - data_START); 
				DATA := PT.BUFFER[i];
				MODE := BYTE#0;
			END_IF;
		END_IF;

	10:	IF FSD.MODE = BYTE#0 THEN 
			IF FSD.ERROR > BYTE#0 THEN
				ERROR := FSD.ERROR; 
				MODE := BYTE#0;
			ELSE
				data_START := POS;
				data_STOP := POS + UINT_TO_UDINT(PT.SIZE) - UDINT#1;
			END_IF;
			STEPP := 0;
		END_IF;
	END_CASE;
END_FUNCTION_BLOCK

