TYPE oscat_url :
    STRUCT
    PROTOCOL : oscat_STRING10;
    USER     : oscat_STRING32;
    PASSWORD : oscat_STRING32;
    DOMAIN   : oscat_STRING80;
    PORT     : WORD;
