FUNCTION_BLOCK SEL2_OF_3_Block

	VAR_INPUT
		IN1 :	REAL;
		IN2 :	REAL;
		IN3 :	REAL;
		D :	REAL;
	END_VAR

	VAR_OUTPUT
		Y :	REAL;
		W :	INT;
		E :	BOOL;
	END_VAR

	VAR
		D12 :	BOOL;
		D23 :	BOOL;
		D31 :	BOOL;
	END_VAR

	D12 := ABS(IN1-IN2) <= D;
	D23 := ABS(IN2-IN3) <= D;
	D31 := ABS(IN3-IN1) <= D;

	IF (D12 AND D23) OR (D12 AND D31) OR (D23 AND D31) THEN
		Y := (IN1 + IN2 + IN3) * 0.333333333333;
		E := FALSE;
		W := 0;
	ELSIF D12 THEN
		Y := (IN1 + IN2) * 0.5;
		E := FALSE;
		W := 3;
	ELSIF D23 THEN
		Y := (IN2 + IN3) * 0.5;
		E := FALSE;
		W := 1;
	ELSIF D31 THEN
		Y := (IN3 + IN1) * 0.5;
		E := FALSE;
		W := 2;
	ELSE
		E := TRUE;
		W := 4;
	END_IF;

END_FUNCTION_BLOCK

