FUNCTION_BLOCK SELECT_8_Block

	VAR_INPUT
		E :	BOOL;
		SET :	BOOL;
		IN :	BYTE;
		UP :	BOOL;
		DN :	BOOL;
		RST :	BOOL;
	END_VAR

