		Q7 :	BOOL;
		STATE :	INT;
	END_VAR

	VAR
		last_up :	BOOL;
		last_dn :	BOOL;
	END_VAR

	IF RST THEN
		STATE := 0;
	ELSIF SET THEN
		STATE := _BYTE_TO_INT(IN);
	ELSIF up AND NOT last_up THEN
		STATE := INC(STATE,1,7);
	ELSIF dn AND NOT last_dn THEN
		STATE := INC(STATE,-1,7);
	END_IF;
	last_UP := UP;
	last_DN := DN;

	Q0 := FALSE;
	Q1 := FALSE;
	Q2 := FALSE;
	Q3 := FALSE;
	Q4 := FALSE;
	Q5 := FALSE;
	Q6 := FALSE;
	Q7 := FALSE;

	IF e THEN
		CASE STATE OF
			0: Q0 := TRUE;
			1: Q1 := TRUE;
			2: Q2 := TRUE;
			3: Q3 := TRUE;
			4: Q4 := TRUE;
			5: Q5 := TRUE;
			6: Q6 := TRUE;
			7: Q7 := TRUE;
		END_CASE;
	END_IF;

END_FUNCTION_BLOCK

