FUNCTION_BLOCK SEQUENCE_4_Block

	VAR_INPUT
		IN0 :	BOOL := TRUE;
		IN1 :	BOOL := TRUE;
		IN2 :	BOOL := TRUE;
		IN3 :	BOOL := TRUE;
		START :	BOOL;
		RST :	BOOL;
		WAIT0 :	TIME;
		DELAY0 :	TIME;
		WAIT1 :	TIME;
		DELAY1 :	TIME;
		WAIT2 :	TIME;
		DELAY2 :	TIME;
		WAIT3 :	TIME;
		DELAY3 :	TIME;
		STOP_ON_ERROR :	BOOL;
	END_VAR

	VAR_OUTPUT
		Q0 :	BOOL;
		Q1 :	BOOL;
		Q2 :	BOOL;
		Q3 :	BOOL;
		QX :	BOOL;
		RUN :	BOOL;
		_STEP :	INT := -1;
		STATUS :	BYTE;
	END_VAR

	VAR
		last :	TIME;
		edge :	BOOL;
		TX :	TIME;
		init :	BOOL;
		T_PLC_MS :	T_PLC_MS_block;
	END_VAR

	T_PLC_MS();
	TX:= UDINT_TO_TIME(T_PLC_MS.T_PLC_MS);

	IF NOT init THEN
		last := TX;
		init := TRUE;
		STATUS := BYTE#110;
	END_IF;

	IF RST THEN
		_STEP := -1;
		Q0 := FALSE;
		Q1 := FALSE;
		Q2 := FALSE;
		Q3 := FALSE;
		STATUS := BYTE#110;
		run := FALSE;

	ELSIF START AND NOT edge THEN
		_STEP := 0;
		last := TX;
		STATUS := BYTE#111;
		Q0 := FALSE;
		Q1 := FALSE;
		Q2 := FALSE;
		Q3 := FALSE;
		run := TRUE;
	END_IF;
	edge := START;

	IF STATUS > BYTE#0 AND STATUS < BYTE#100 AND STOP_on_ERROR THEN RETURN; END_IF;

	IF run AND _STEP = 0 THEN
		IF NOT q0 AND IN0 AND SUB_TIME(TX, last) <= wait0 THEN
			Q0 := TRUE;
			last := TX;
		ELSIF NOT q0 AND SUB_TIME(TX, last) > wait0 THEN
			STATUS := BYTE#1;
			run := FALSE;
		ELSIF q0 AND SUB_TIME(TX, last) >= DELAY0 THEN
			_STEP := 1;
			last := TX;
		END_IF;
	END_IF;
	IF run AND _STEP = 1 THEN
		IF NOT Q1 AND IN1 AND SUB_TIME(TX, last) <= wait1 THEN
			Q0 := FALSE;
			Q1 := TRUE;
			last := TX;
		ELSIF NOT Q1 AND SUB_TIME(TX, last) > wait1 THEN
			STATUS := BYTE#2;
			q0 := FALSE;
			run := FALSE;
		ELSIF Q1 AND SUB_TIME(TX, last) >= DELAY1 THEN
			_STEP := 2;
			last := TX;
		END_IF;
	END_IF;
	IF run AND _STEP = 2 THEN
		IF NOT Q2 AND IN2 AND SUB_TIME(TX, last) <= wait2 THEN
			Q1 := FALSE;
			Q2 := TRUE;
			last := TX;
		ELSIF NOT Q2 AND SUB_TIME(TX, last) > wait2 THEN
			STATUS := BYTE#3;
			Q1 := FALSE;
			run := FALSE;
		ELSIF Q2 AND SUB_TIME(TX, last) >= DELAY2 THEN
			_STEP := 3;
			last := TX;
		END_IF;
	END_IF;
	IF run AND _STEP = 3 THEN
		IF NOT q3 AND IN3 AND SUB_TIME(TX, last) <= wait3 THEN
			Q2 := FALSE;
			Q3 := TRUE;
			last := TX;
		ELSIF NOT q3 AND SUB_TIME(TX, last) > wait3 THEN
			STATUS := BYTE#4;
			Q2 := FALSE;
			run := FALSE;
		ELSIF q3 AND SUB_TIME(TX, last) >= DELAY3 THEN
			_STEP := -1;
			q3 := FALSE;
			run := FALSE;
			STATUS := BYTE#110;
		END_IF;
	END_IF;
	QX := q0 OR Q1 OR Q2 OR q3;

END_FUNCTION_BLOCK

