FUNCTION_BLOCK SH_2_Block

	VAR_INPUT
		IN :	REAL;
		PT :	TIME;
		N :	INT := INT#16;
		DISC :	INT;
	END_VAR


	VAR_OUTPUT
		OUT :	REAL;
		TRIG :	BOOL;
		AVG :	REAL;
		HIGH :	REAL;
		LOW :	REAL;
	END_VAR

	VAR
		M :	INT;
		buf :	oscat_arr_0_15;
		buf2 :	oscat_arr_0_15;
		last :	TIME;
		i :	INT;
		I2 :	INT;
		START :	INT;
		temp :	REAL;
		STOP :	INT;
		TX :	TIME;
		D2 :	INT;
		T_PLC_MS :	T_PLC_MS_block;
	END_VAR


	T_PLC_MS();
	TX:= UDINT_TO_TIME(T_PLC_MS.T_PLC_MS);
	D2 := WORD_TO_INT(SHR(INT_TO_WORD(disc),1));

	IF SUB_TIME(TX, last) >= PT THEN
		last := TX;
		TRIG := TRUE;

		M := LIMIT(1,N,16);

		i := M-1;
		WHILE (i>=1) DO
		i2 := i-1;
		buf2[i] := buf2[i2];
		i:=i-1;
		END_WHILE;

		buf2[0] := IN;
		OUT := IN;
		buf := buf2;

		(* sort the ARRAY lowest VALue AT 0 *)
		FOR START := 0 TO M - 2 DO
			FOR i := START+1 TO M - 1 DO
				IF buf[START] > buf[i] THEN
					temp := buf[START];
					buf[START] := buf[i];
					buf[i] := temp;
				END_IF;
			END_FOR;
		END_FOR;

		STOP := M - 1 - D2;
		START := D2;
		IF NOT EVEN(INT_TO_DINT(disc)) THEN START := START + 1; END_IF;
		AVG := 0.0;
		FOR i := START TO STOP DO AVG := AVG + buf[i]; END_FOR;
		AVG := AVG / INT_TO_REAL(STOP - START +1);
		LOW := buf[START];
		HIGH := buf[STOP];
	ELSE
		TRIG := FALSE;
	END_IF;
END_FUNCTION_BLOCK

