FUNCTION_BLOCK TREND



	VAR_INPUT
		X :	REAL;
	END_VAR


	VAR_OUTPUT
		Q :	BOOL;
		TU :	BOOL;
		TD :	BOOL;
		D :	REAL;
	END_VAR


	VAR
		last_x :	REAL;
	END_VAR


	TU := X > last_X;
	TD := X < last_X;
	Q := TU OR TD;
	D := X - LAST_X;

	last_X := X;



END_FUNCTION_BLOCK

