	S1 :	REAL;
	A :	REAL;
	S2 :	REAL;
	S3 :	REAL;
    CEIL5_OUT : REAL;
  END_VAR

  CEIL5_OUT := TRIANGLE_A(S1, A, S2, S3);
END_PROGRAM

