FUNCTION_BLOCK TUNE_Block

	VAR_INPUT
		SET :	BOOL;
		SU :	BOOL;
		SD :	BOOL;
		RST :	BOOL;
		SS :	REAL := 0.1;
		LIMIT_L :	REAL;
		LIMIT_H :	REAL := 100.0;
		RST_VAL :	REAL;
		SET_VAL :	REAL := 100.0;
		T1 :	TIME := T#500ms;
		T2 :	TIME := T#2s;
		S1 :	REAL := 2.0;
		S2 :	REAL := 10.0;
	END_VAR


	VAR_OUTPUT
		Y :	REAL;
	END_VAR


	VAR
		TX :	UDINT;
		START :	UDINT;
		START2 :	UDINT;
		STATE :	INT;
		IN :	BOOL;
		STEP2 :	REAL;
		SPEED :	REAL;
		Y_START :	REAL;
		Y_START2 :	REAL;
		T_PLC_MS :	T_PLC_MS_block;
	END_VAR


	T_PLC_MS();
	TX:= T_PLC_MS.T_PLC_MS;

	IF RST THEN
		Y := RST_VAL;
		STATE := 0;
	ELSIF SET THEN
		Y := SET_VAL;
		STATE := 0;
	ELSIF STATE > 0 THEN
		IF STATE = 1 THEN
			IN := su;
		ELSE
			IN := sd;
		END_IF;
		IF NOT IN AND TX - START <= TIME_TO_UDINT2(T1) THEN
			Y := Y_START + STEP2;
			STATE := 0;
		ELSIF IN AND TX - START >= TIME_TO_UDINT2(T2) THEN
			Y := Y_START2 + UDINT_TO_REAL(TX - START2) * S2 / SPEED;
		ELSIF IN AND TX - START >= TIME_TO_UDINT2(T1) THEN
			Y := Y_START + UDINT_TO_REAL(TX - START - TIME_TO_UDINT2(T1)) * S1 / SPEED;
			START2 := TX;
			Y_START2 := Y;
		ELSIF NOT IN THEN
			STATE := 0;
		END_IF;
	ELSIF su THEN
		STATE := 1;
		START := TX;
		STEP2 := ss;
		SPEED := 1000.0;
		Y_START := Y;
	ELSIF sd THEN

		STATE := 2;
		START := TX;
		STEP2 := -ss;
		SPEED := -1000.0;
		Y_START := Y;
	END_IF;

END_FUNCTION_BLOCK

