FUNCTION_BLOCK RDM_Block
	VAR_INPUT
		last :	REAL;
	END_VAR
	VAR_OUTPUT
		RDM :	REAL;
	END_VAR
	VAR
		T_PLC_MS :	T_PLC_MS_block;
		tn :	DWORD;
		tc :	INT;
	END_VAR
	T_PLC_MS();
	tn := UDINT_TO_DWORD(T_PLC_MS.T_PLC_MS);
	tc := BIT_COUNT(tn);

	tn:=BIT_LOAD_DW(tn,BIT_OF_DWORD(tn,2),31); (* tn.31 := tn.2; *)
	tn:=BIT_LOAD_DW(tn,BIT_OF_DWORD(tn,5),30); (* tn.30 := tn.5; *)
	tn:=BIT_LOAD_DW(tn,BIT_OF_DWORD(tn,4),29); (* tn.29 := tn.4; *)
	tn:=BIT_LOAD_DW(tn,BIT_OF_DWORD(tn,1),28); (* tn.28 := tn.1; *)
	tn:=BIT_LOAD_DW(tn,BIT_OF_DWORD(tn,0),27); (* tn.27 := tn.0; *)
	tn:=BIT_LOAD_DW(tn,BIT_OF_DWORD(tn,7),26); (* tn.26 := tn.7; *)
	tn:=BIT_LOAD_DW(tn,BIT_OF_DWORD(tn,6),25); (* tn.25 := tn.6; *)
	tn:=BIT_LOAD_DW(tn,BIT_OF_DWORD(tn,3),24); (* tn.24 := tn.3; *)

	tn := ROL(tn,BIT_COUNT(tn)) OR DWORD#16#80000001;
	tn := UDINT_TO_DWORD(DWORD_TO_UDINT(tn) MOD UDINT#71474513 + _INT_TO_UDINT(tc) + UDINT#77);
	RDM := FRACT(_DWORD_TO_REAL(tn) / 10000000.0 * (2.71828182845904523536028747135266249 - LIMIT_REAL(0.0,last,1.0)));
END_FUNCTION_BLOCK

FUNCTION_BLOCK RDM22
	VAR_INPUT
		last :	INT;
		LOW :	INT;
		HIGH :	INT;
	END_VAR

	VAR_OUTPUT
		RDM2 :	INT;
	END_VAR


	VAR
		RDM_p :	RDM_Block;
	END_VAR

	RDM_p(last:=FRACT(INT_TO_REAL(last) * 3.14159265358979323846264338327950288));
	RDM2 := DINT_TO_INT(D_TRUNC(RDM_p.RDM * INT_TO_REAL(HIGH - LOW + 1))) + LOW;
END_FUNCTION_BLOCK


FUNCTION_BLOCK ARRAY_SHUFFLE2
	VAR_IN_OUT
		PT :	oscat_PT_ARRAY;
	END_VAR

	VAR_INPUT
		SIZE :	UINT;
	END_VAR

	VAR_OUTPUT
		ARRAY_SHUFFLE :	BOOL;
	END_VAR
	VAR
		temp :	REAL;
		POS :	INT;
		i :	INT;
		STOP :	INT;
		RDM2 :	RDM22;
	END_VAR

	STOP :=LIMIT_INT(1,UINT_TO_INT(SIZE),1000);
	FOR i := 1 TO STOP DO
			RDM2(last:=i+POS,LOW:=1,HIGH:=STOP);
			POS := RDM2.RDM2;
			(* swap elements *)
			temp := PT[i];
			PT[i] := PT[POS];
			PT[POS] := temp;
	END_FOR;

	ARRAY_SHUFFLE := TRUE;
END_FUNCTION_BLOCK

