TYPE
	oscat_PT_ARRAY: ARRAY [1..100] OF REAL;
	oscat_stack_array: ARRAY [1..32]   OF INT;
END_TYPE

FUNCTION _INT_TO_UDINT:UDINT
	VAR_INPUT
		IN :	INT;
