FUNCTION_BLOCK TREND_DW
	VAR_INPUT
		X :	DWORD;
	END_VAR
	VAR_OUTPUT
		Q :	BOOL;
		TU :	BOOL;
		TD :	BOOL;
		D :	DWORD;
	END_VAR

	VAR
		last_X :	DWORD;
	END_VAR

	IF X > last_X THEN
		TU := TRUE;
		TD := FALSE;
		D := UDINT_TO_DWORD(DWORD_TO_UDINT(X) - DWORD_TO_UDINT(last_X));
		Q := TRUE;
	ELSIF X < last_X THEN
		TD := TRUE;
		TU := FALSE;
		D := UDINT_TO_DWORD(DWORD_TO_UDINT(last_X) - DWORD_TO_UDINT(X));
		Q := FALSE;
	ELSE
		TU := FALSE;
		TD := FALSE;
		D := DWORD#0;
	END_IF;
	last_X := X;
END_FUNCTION_BLOCK

FUNCTION_BLOCK _RMP_NEXT
	VAR_INPUT
		E :	BOOL := TRUE;
		IN :	BYTE;
		TR :	TIME;
		TF :	TIME;
		TL :	TIME;
	END_VAR

	VAR_OUTPUT
		DIR :	BOOL;
		UP :	BOOL;
		DN :	BOOL;
	END_VAR

	VAR_IN_OUT
		OUT :	BYTE;
	END_VAR
	VAR
		rmX :	_RMP_B;
		DIRX :	TREND_DW;
		t_lock :	TP;
		Xen :	BOOL;
		XDIR :	BOOL;
	END_VAR

	DIRX(X := BYTE_TO_DWORD(IN));

	t_lock(IN := FALSE, PT := TL);

	IF DIRX.TU AND (OUT < IN) THEN
		IF NOT XDIR AND Xen THEN t_lock(IN := TRUE); END_IF;
		Xen := TRUE;
		XDIR := TRUE;
	ELSIF DIRX.TD AND (OUT > IN) THEN
		IF XDIR AND Xen THEN t_lock(IN := TRUE); END_IF;
		Xen := TRUE;
		XDIR := FALSE;
	ELSIF Xen THEN
		IF (XDIR AND (OUT >= IN)) OR (NOT XDIR AND (OUT <= IN)) THEN
			Xen := FALSE;
			IF TL > t#0s THEN t_lock(IN := TRUE); END_IF;
		END_IF;
	END_IF;

	IF NOT t_lock.Q AND Xen THEN
		UP := XDIR;
		DIR := XDIR;
		DN := NOT XDIR;
	ELSE
		UP := FALSE;
		DN := FALSE;
	END_IF;

	rmX(RMP := OUT, E := E AND (UP OR DN) , DIR := DIR, TR := SEL(DIR, TF, TR));
	OUT := rmX.RMP;
END_FUNCTION_BLOCK

