FUNCTION_BLOCK ONTIME_Block

	VAR_INPUT
		IN :	BOOL;
		RST :	BOOL;
	END_VAR


	VAR_IN_OUT
		SECONDS :	UDINT;
		CYCLES :	UDINT;
	END_VAR


	VAR
		tx :	UDINT;
		last :	UDINT;
		edge :	BOOL;
		init :	BOOL;
		ms :	UDINT;
		T_PLC_MS :	T_PLC_MS_Block;
	END_VAR

	T_PLC_MS();
	tx:= T_PLC_MS.T_PLC_MS;

	IF NOT init THEN
		init := TRUE;
		last := tx;
		ms := UDINT#0;
	END_IF;
	IF RST THEN
		SECONDS := UDINT#0;
		CYCLES := UDINT#0;
		last := tx;
		ms := UDINT#0;
	ELSIF IN THEN
		(* add the current milliseconds *)
		ms := (tx - last) + ms;
		IF ms >= UDINT#1000 THEN
			seconds := seconds + UDINT#1;
			ms := ms - UDINT#1000;
		END_IF;
		cycles := cycles + BOOL_TO_UDINT(NOT edge);
	END_IF;
	last := tx;
	edge := in;

END_FUNCTION_BLOCK

FUNCTION_BLOCK ACTUATOR_PUMP_Block

	VAR_INPUT
		IN :	BOOL;
		MANUAL :	BOOL;
		RST :	BOOL := FALSE;
		MIN_ONTIME :	TIME := T#10s;
		MIN_OFFTIME :	TIME := T#10s;
		RUN_EVERY :	TIME := T#10000m;
	END_VAR


	VAR_OUTPUT
		PUMP :	BOOL;
		RUNTIME :	UDINT;
		CYCLES :	UDINT;
	END_VAR


	VAR
		tx :	TIME;
		last_change :	TIME;
		meter :	ONTIME_Block;
		old_man :	BOOL;
		init :	BOOL;
		T_PLC_MS :	T_PLC_MS_Block;
	END_VAR

	T_PLC_MS();
	tx:= UDINT_TO_TIME(T_PLC_MS.T_PLC_MS);

	IF NOT init THEN
		init := TRUE;
		last_change := tx;
	ELSIF rst THEN
		rst := FALSE;
		runtime := UDINT#0;
		cycles := UDINT#0;
	ELSIF manual AND NOT pump AND NOT old_man THEN
		last_change := tx;
		pump := TRUE;
	ELSIF NOT manual AND old_man AND pump AND NOT in THEN
		last_change := tx;
		pump := FALSE;
	ELSIF in AND NOT pump AND tx - last_change >= min_offtime THEN
		last_change := tx;
		pump := TRUE;
	ELSIF pump AND NOT in AND NOT manual AND tx - last_change >= min_ontime THEN
		last_change := tx;
		pump := FALSE;
	ELSIF NOT pump AND (tx - last_change >= run_every) AND (run_every > T#0s) THEN
		last_change := tx;
		pump := TRUE;
	END_IF;

	meter(in := pump, SECONDS := runtime, CYCLES := cycles);
	cycles := meter.CYCLES;
	runtime := meter.SECONDS;

	old_man := manual;

END_FUNCTION_BLOCK

