FUNCTION_BLOCK ACTUATOR_UD_Block

	VAR_INPUT
		UD :	BOOL;
		_ON :	BOOL;
		MANUAL :	BOOL;
		UP :	BOOL;
		DN :	BOOL;
		OFF :	BOOL;
		YUP_IN :	BOOL;
		YDN_IN :	BOOL;
		_TON :	TIME;
		TOFF :	TIME;
		OUT_RETURN :	BOOL;
	END_VAR


	VAR_OUTPUT
		YUP :	BOOL;
		YDN :	BOOL;
		STATUS :	BYTE;
	END_VAR


	VAR
		tx :	TIME;
		last :	TIME;
		init :	BOOL;
		T_PLC_MS :	T_PLC_MS_Block;
	END_VAR

	T_PLC_MS();
	tx:= UDINT_TO_TIME(T_PLC_MS.T_PLC_MS);

	IF NOT init THEN
		last := tx;
		init := TRUE;
	ELSIF off THEN
		Yup := FALSE;
		Ydn := FALSE;
		last := tx;
		status := BYTE#101;

	ELSIF ((Yup OR Ydn) AND tx - last < _TON) THEN RETURN;
	ELSIF NOT yup AND NOT ydn AND tx - last < toff THEN	RETURN;

	ELSIF manual THEN
		status := BYTE#102;
		IF yup AND NOT up OR ydn AND NOT dn THEN
			ydn := FALSE;
			yup := FALSE;
			last := tx;
		ELSIF UP AND NOT DN AND NOT OFF THEN
			Ydn := FALSE;
			Yup := TRUE;
			last := tx;
			status := BYTE#103;
		ELSIF DN AND NOT UP AND NOT OFF THEN
			Yup := FALSE;
			Ydn := TRUE;
			last := tx;
			status := BYTE#104;
		ELSE
			IF YUP OR YDN THEN LAST := tx; END_IF;
			Yup := FALSE;
			Ydn := FALSE;
		END_IF;

	ELSE
		IF yup AND NOT ud OR ydn AND UD THEN
			yup := FALSE;
			ydn := FALSE;
			last := tx;
		ELSIF Ud AND _ON AND NOT OFF THEN
			Ydn := FALSE;
			Yup := TRUE;
			last := tx;
			status := BYTE#111;

		ELSIF NOT UD AND _ON AND NOT OFF THEN
			Yup := FALSE;
			Ydn := TRUE;
			last := tx;
			status := BYTE#112;
		ELSE
			IF Yup OR Ydn THEN last := tx; END_IF;
			Yup := FALSE;
			Ydn := FALSE;
			status := BYTE#110;
		END_IF;
	END_IF;

	IF Ydn AND Yup_in AND out_return THEN
		Ydn := FALSE;
		status := BYTE#1;
	END_IF;
	IF Yup AND Ydn_in AND out_return THEN
		Yup := FALSE;
		status := BYTE#2;
	END_IF;

END_FUNCTION_BLOCK

