FUNCTION AOUT:DWORD
	VAR_INPUT
		IN :	REAL;
		BITS :	BYTE;
		SIGN :	BYTE;
		LOW :	REAL;
		HIGH :	REAL;
	END_VAR

	VAR
		in2 :	REAL;
		sx :	BOOL;
	END_VAR

	IF sign < BYTE#32 THEN
		sx := sign_R(in);
		in2 := ABS(in);
	ELSE
