FUNCTION _INT_TO_UDINT:UDINT
	VAR_INPUT
		IN :	INT;
	END_VAR

	_INT_TO_UDINT := DINT_TO_UDINT(INT_TO_DINT(IN));
END_FUNCTION

FUNCTION BIT_OF_DWORD:BOOL
	VAR_INPUT
		IN :	DWORD;
		N :	INT;
	END_VAR
	BIT_OF_DWORD := (SHR(in,n) AND DWORD#1) > DWORD#0;
END_FUNCTION

FUNCTION EVEN:BOOL
	VAR_INPUT
		IN :	DINT;
	END_VAR
	even := NOT BIT_OF_DWORD(DINT_TO_DWORD(in),0);
END_FUNCTION

FUNCTION_BLOCK _ARRAY_SORT_Block
	VAR_IN_OUT
		PT :	oscat_pt_ARRAY;
	END_VAR

	VAR_INPUT
		SIZE :	UINT;
	END_VAR

	VAR_OUTPUT
		_ARRAY_SORT :BOOL;
	END_VAR

	VAR
		stack_count :	INT;
		stack :	oscat_stack_array;
		links :	INT;
		rechts :	INT;
		pivot :	REAL;
		i :	INT;
		j :	INT;
		ende_innen :	BOOL;
		ende_aussen :	BOOL;
		tmp :	REAL;
		x :	INT;
	END_VAR


	links := 1;
	rechts := DWORD_TO_INT(SHR(UINT_TO_DWORD(size),2)); 
	stack_count := 1; 

	WHILE NOT ende_aussen DO
		IF links < rechts THEN
			x := DWORD_TO_INT(SHR(UDINT_TO_DWORD(_INT_TO_UDINT(rechts)+ _INT_TO_UDINT(links)),1));
			pivot := PT[x];
			i := links - 1;
			j := rechts + 1;

			ende_innen := FALSE;
			REPEAT
				REPEAT	i := i+1;	UNTIL (PT[i] >= pivot) OR NOT (i < rechts)	END_REPEAT;
				REPEAT	j := j-1;	UNTIL (PT[j] <= pivot) OR NOT (j > links)	END_REPEAT;
				IF i >= j THEN
					ende_innen := TRUE;
				ELSE
					tmp := PT[j];
					PT[j] := PT[i];
					PT[i] := tmp;
				END_IF;

			UNTIL ende_innen END_REPEAT;

			stack[stack_count] := rechts;	
			IF Stack_count < 32 THEN
				stack_count := stack_count +1;
			ELSE
				ende_aussen := TRUE;
				_ARRAY_SORT := FALSE;				
			END_IF;
			rechts := MAX(links, i-1);

		ELSE
			IF stack_count = 1 THEN
				ende_aussen := TRUE;
			ELSE
				links := rechts+1;
				stack_count := stack_count - 1;	
				rechts:= stack[stack_count];
			END_IF;
		END_IF;
	END_WHILE;

	_ARRAY_SORT := TRUE;			
END_FUNCTION_BLOCK


FUNCTION_BLOCK _ARRAY_MEDIAN_Block

	VAR_IN_OUT
		PT :	oscat_pt_ARRAY;
	END_VAR

	VAR_INPUT
		SIZE :	UINT;
	END_VAR

	VAR_OUTPUT
		_ARRAY_MEDIAN :	REAL;
	END_VAR

	VAR
		i :	INT;
		i2 :	INT;
		stop :	INT;
		_array_sort :	_ARRAY_SORT_Block;
	END_VAR


	(* Array sortieren *)
	_array_sort.pt   := pt;
	_array_sort.size := size;
	_array_sort();
	pt := _array_sort.pt;

	stop :=LIMIT_INT(1,UINT_TO_INT(size),1000);
	IF even(INT_TO_DINT(stop)) THEN
	    i := WORD_TO_INT(SHR(INT_TO_WORD(stop),1));
	    i2 := i+1;
		_array_median := (pt[i] + pt[i2]) * 0.5;
	ELSE
	    i := WORD_TO_INT(SHR(INT_TO_WORD(stop),1))+1;
		_array_median := pt[i];
	END_IF;

END_FUNCTION_BLOCK


