FUNCTION_BLOCK BLIND_CONTROL_Block

	VAR_INPUT
		UP :	BOOL;
		DN :	BOOL;
		S_IN :	BYTE;
		PI :	BYTE;
		AI :	BYTE;
		T_UD :	TIME;
		T_ANGLE :	TIME;
		SENS :	BYTE := 5;
		T_LOCKOUT :	TIME := T#100ms;
	END_VAR


	VAR_OUTPUT
		POS :	BYTE;
		ANG :	BYTE;
		MU :	BOOL;
		MD :	BOOL;
		STATUS :	BYTE;
	END_VAR


	VAR
		act :	BLIND_ACTUATOR_Block;
		delta :	BYTE;
		bTimeTest :	BOOL;
		iPos :	BYTE;
		iAngel :	BYTE;
	END_VAR

	IF bTimeTest THEN
		PI:=iPos;
		AI:=iAngel;
		UP:=TRUE;
		DN:=TRUE;
	END_IF;

	act(T_UD:=T_UD, T_ANGLE:=T_ANGLE, T_lockout := T_Lockout);

	IF UP AND DN THEN
		IF _BYTE_TO_INT(act.pos) < _BYTE_TO_INT(pi) - _BYTE_TO_INT(delta) THEN
			act.UP := TRUE;
			act.DN := FALSE;
			delta := BYTE#0;
			STATUS := BYTE#121;
		ELSIF _BYTE_TO_INT(act.pos) > _BYTE_TO_INT(pi) + _BYTE_TO_INT(delta) THEN
			act.UP := FALSE;
			act.DN := TRUE;
			delta := BYTE#0;
			STATUS := BYTE#122;
		ELSIF _BYTE_TO_INT(act.ang) < _BYTE_TO_INT(ai) - _BYTE_TO_INT(delta) AND T_angle > T#100ms THEN
			act.UP := TRUE;
			act.DN := FALSE;
			delta := SHR(sens,2);
			STATUS := BYTE#123;
		ELSIF _BYTE_TO_INT(act.ang) > _BYTE_TO_INT(ai) + _BYTE_TO_INT(delta) AND T_angle > T#100ms THEN
			act.UP := FALSE;
			act.DN := TRUE;
			delta := SHR(sens,2);
			STATUS := BYTE#124;
		ELSE
			act.UP := FALSE;
			act.DN := FALSE;
			delta := sens;
			STATUS := S_IN;
		END_IF;
	ELSE
		act.UP := UP;
		act.DN := DN;
		STATUS := S_IN;
	END_IF;

	act(T_UD:=T_UD, T_ANGLE:=T_ANGLE, T_lockout := T_Lockout);
	pos := act.pos;
	ang := act.ang;
	MU := act.QU;
	md := act.QD;
	status := act.status;

END_FUNCTION_BLOCK

