FUNCTION_BLOCK BLIND_CONTROL_S_Block

	VAR_INPUT
		UP :	BOOL;
		DN :	BOOL;
		S_IN :	BYTE := BYTE#125;
		PI :	BYTE;
		T_UP :	TIME;
		T_DN :	TIME;
		RU :	BOOL;
		RD :	BOOL;
		T_LOCKOUT :	TIME := T#100ms;
		T_EXT :	TIME;
		EXT_TRIG :	BYTE := BYTE#5;
		R_POS_TOP :	BYTE := BYTE#255;
		R_POS_BOT :	BYTE;
	END_VAR


	VAR_OUTPUT
		POS :	BYTE;
		MU :	BOOL;
		MD :	BOOL;
		STATUS :	BYTE;
	END_VAR


	VAR
		T_PLC_MS :	T_PLC_MS_Block;
		rmp :	_RMP_NEXT;
		tx :	TIME;
		last :	TIME;
		pi_last :	BYTE;
	END_VAR

	T_PLC_MS();
	tx:= UDINT_TO_TIME(T_PLC_MS.T_PLC_MS);

	IF UP  AND NOT DN THEN
		rmp.IN := BYTE#255;
		STATUS := BYTE#121;
	ELSIF DN AND NOT UP THEN
		rmp.IN := BYTE#0;
		STATUS := BYTE#122;
	ELSIF NOT (UP OR DN) THEN
		rmp.IN := PI;
		STATUS := S_IN;
	END_IF;

	rmp(E := UP OR DN, TR := T_UP, TF := T_DN, TL := T_LOCKOUT, OUT := POS);
	pos := rmp.OUT;

	CASE _BYTE_TO_INT(STATUS) OF
		0:	
			last := tx;
			PI_last := PI XOR BYTE#255;
			STATUS := BYTE#128;	

		121: 
			MU := TRUE;
			MD := FALSE;
			IF POS >= USINT_TO_BYTE(USINT#255 - BYTE_TO_USINT(EXT_TRIG)) THEN
				POS := BYTE#255;
				last := tx;
				STATUS := BYTE#129;	
			END_IF;

		122:	
			MD := TRUE;
			MU := FALSE;
			IF POS <= EXT_TRIG THEN
				POS := BYTE#0;
				last := tx;
				STATUS := BYTE#129;	
			END_IF;

		123:	
			MD := rmp.DN;
			MU := rmp.UP;
			IF NOT (rmp.DN OR rmp.UP) THEN
				IF POS <= EXT_TRIG THEN
					MD := TRUE;
					last := tx;
					STATUS := BYTE#129;
				ELSIF POS >= USINT_TO_BYTE(USINT#255 - BYTE_TO_USINT(EXT_TRIG)) THEN
					MU := TRUE;
					last := tx;
					STATUS := BYTE#129;	
				ELSE
					STATUS := S_IN;
				END_IF;
			END_IF;

		124:
			MD := rmp.DN;
			MU := rmp.UP;
			IF NOT(rmp.DN OR rmp.UP) THEN
				PI_last := PI;
				STATUS := S_IN;
			END_IF;

		127:
			IF (tx - last) >= T_LOCKOUT THEN
					STATUS := S_IN;
			END_IF;

		128:
			MU := TRUE;
			MD := FALSE;
			rmp.IN := BYTE#255;
			IF (tx - last) >= (T_UP +  T_EXT) THEN
				MU := FALSE;
				last := tx;
				STATUS := BYTE#127;	
			END_IF;

		129: 
			IF (tx - last) >= T_EXT THEN
				MU := FALSE;
				MD := FALSE;
				last := tx;
				STATUS := BYTE#127;
			END_IF;

	ELSE
		MU := FALSE;
		MD := FALSE;
		IF PI <> PI_last THEN
			PI_last := PI;
			rmp.IN := PI;
			STATUS := BYTE#123;	
		ELSIF POS = BYTE#0 AND RU THEN
			rmp.IN := R_POS_BOT;
			STATUS := BYTE#124;	
		ELSIF pos = BYTE#255 AND RD THEN
			rmp.IN := R_POS_TOP;
			STATUS := BYTE#124;	
		ELSE
			STATUS := S_IN;
		END_IF;
	END_CASE;

END_FUNCTION_BLOCK

