FUNCTION_BLOCK BLIND_NIGHT_Block

	VAR_INPUT
		UP :	BOOL;
		DN :	BOOL;
		S_IN :	BYTE;
		PI :	BYTE;
		AI :	BYTE;
		E_NIGHT :	BOOL := TRUE;
		E_DAY :	BOOL := TRUE;
		DTIN :	UDINT;
		SUNRISE :	UDINT;
		SUNSET :	UDINT;
		SUNRISE_OFFSET :	TIME;
		SUNSET_OFFSET :	TIME;
		NIGHT_POSITION :	BYTE;
		NIGHT_ANGLE :	BYTE;
	END_VAR


	VAR_OUTPUT
		QU :	BOOL;
		QD :	BOOL;
		STATUS :	BYTE;
		PO :	BYTE;
		AO :	BYTE;
	END_VAR


	VAR
		night :	BOOL;
		last_night :	UDINT;
		last_day :	UDINT;
	END_VAR

	IF NOT (up AND dn) AND night THEN
		night := FALSE;
	ELSIF (DT_TO_TOD2(dtin) > sunset + TIME_TO_UDINT2(sunset_offset)) AND (last_night < DT_TO_DATE2(dtin)) AND NOT night AND e_night THEN
		night := TRUE;
		last_night := DT_TO_DATE2(dtin);
	ELSIF (DT_TO_TOD2(dtin) > sunrise + TIME_TO_UDINT2(sunrise_offset)) AND (last_day < DT_TO_DATE2(dtin)) AND night AND e_day AND (last_night < DT_TO_DATE2(dtin)) THEN
		night := FALSE;
		last_day := DT_TO_DATE2(dtin);
	END_IF;

	IF UP AND DN AND night THEN
		status := BYTE#141;
		po := night_position;
		ao := night_angle;
	ELSE
		QU := UP;
		QD := DN;
		po := pi;
		ao := ai;
		status := s_in;
	END_IF;

END_FUNCTION_BLOCK

