		CLEAN :	STRING;
	END_VAR

	VAR
		pos :	INT;
		stop :	INT;
		char :	STRING;
	END_VAR

	CLEAN := IN;
	stop := LEN(in);
	pos := 1;
	WHILE pos <= stop DO
		char := MID(CLEAN, 1, pos);
		IF FIND(cx,char) > 0 THEN
			pos := pos + 1;
		ELSE
			CLEAN := DELETE(CLEAN, 1, pos);
			stop := stop - 1;	
		END_IF;
	END_WHILE;

END_FUNCTION_BLOCK

