FUNCTION_BLOCK CLICK_DEC

	VAR_INPUT
		IN :	BOOL;
		TC :	TIME;
	END_VAR

	VAR_OUTPUT
		Q0 :	BOOL;
		Q1 :	BOOL;
		Q2 :	BOOL;
		Q3 :	BOOL;
	END_VAR

	VAR
		tx :	TP;
		edge :	BOOL;
		cnt :	INT := INT#-1;
	END_VAR

	IF in = FALSE THEN
		Q0 := FALSE;
		Q1 := FALSE;
		Q2 := FALSE;
		Q3 := FALSE;
	END_IF;

	IF in AND NOT edge AND NOT tx.q THEN
		cnt := 0;
	ELSIF tx.Q AND NOT IN AND edge THEN
		cnt := cnt + 1;
	ELSIF NOT tx.Q THEN
		CASE cnt OF
			0 : Q0 := TRUE;
			1 : Q1 := TRUE;
			2 : Q2 := TRUE;
			3 : Q3 := TRUE;
		END_CASE;
		cnt := -1;
	END_IF;

	edge := IN;
	tx(in := IN, pt := TC);

END_FUNCTION_BLOCK

