	VAR_INPUT
		IN :	REAL;
		KP :	REAL := 1.0;
		KI :	REAL := 1.0;
		LIM_L :	REAL := -1.0E38;
		LIM_H :	REAL := 1.0E38;
		RST :	BOOL;
	END_VAR

	VAR_OUTPUT
		Y :	REAL;
		LIM :	BOOL;
	END_VAR

	VAR
		init :	BOOL;
		tx :	UDINT;
		tc :	REAL;
		t_last :	UDINT;
		in_last :	REAL;
		i :	REAL;
		p :	REAL;
		T_PLC_US :	T_PLC_US_Block;
	END_VAR

	IF NOT init OR RST THEN
		init := TRUE;
		in_last := in;
		T_PLC_US();
		t_last := T_PLC_US.T_PLC_US;
		i := 0.0;
		tc := 0.0;
	ELSE
		(* read last cycle time in Microseconds *)
		T_PLC_US();
		tx := T_PLC_US.T_PLC_US;
		tc := UDINT_TO_REAL(tx - t_last);
		t_last := tx;

		(* calculate proportional part *)
		p := KP * IN;

		(* run integrator *)
		i := (IN + in_last) * 5.0E-7 * KI * tc + i;
		in_last := IN;

		(* calculate output Y *)
		Y := p + i;

		(* check output for limits *)
		IF Y >= LIM_H THEN
			Y := LIM_H;
			IF ki <> 0.0 THEN
				i := LIM_H - p;
			ELSE
				i := 0.0;
			END_IF;
			LIM := TRUE;
		ELSIF Y <= LIM_L THEN
			Y := LIM_L;
			IF ki <> 0.0 THEN
				i := LIM_L - p;
			ELSE
				i := 0.0;
			END_IF;
			LIM := TRUE;
		ELSE
			LIM := FALSE;
		END_IF;
	END_IF;
END_FUNCTION_BLOCK

FUNCTION_BLOCK FT_DERIV
	VAR_INPUT
		IN :	REAL;
		K :	REAL := 1.0;
		RUN :	BOOL := TRUE;
	END_VAR

	VAR_OUTPUT
		OUT :	REAL;
	END_VAR

	VAR
		old :	REAL;
		tx :	UDINT;
		last :	UDINT;
		init :	BOOL;
		tc :	REAL;
		T_PLC_US :	T_PLC_US_Block;
	END_VAR

	T_PLC_US();
	tx:= T_PLC_US.T_PLC_US;
	tc := UDINT_TO_REAL(tx - last);

	IF NOT init THEN
		init := TRUE;
		old := in;
	ELSIF run AND tc > 0.0 THEN
		out := (in - old) / tc * 1000000.0 * K;
		old := in;
	ELSE
		out := 0.0;
	END_IF;

	last := tx;

	T_PLC_US();
	tx:= T_PLC_US.T_PLC_US;

	IF NOT init THEN
		init := TRUE;
	ELSIF run AND tx - last > UDINT#0 THEN
		out := (in - old) / UDINT_TO_REAL(tx - last) * 1000000.0 * K;
	ELSE
		out := 0.0;
	END_IF;
	old := in;
	last := tx;
END_FUNCTION_BLOCK

FUNCTION_BLOCK FT_PIDWL
	VAR_INPUT
		IN :	REAL;
		KP :	REAL := 1.0;
		TN :	REAL := 1.0;
		TV :	REAL := 1.0;
		LIM_L :	REAL := -1.0E38;
		LIM_H :	REAL := 1.0E38;
		RST :	BOOL;
	END_VAR

	VAR_OUTPUT
		Y :	REAL;
		LIM :	BOOL;
	END_VAR

	VAR
		piwl :	FT_PIWL;
		diff :	FT_DERIV;
	END_VAR

	IF rst THEN
		piwl(rst := TRUE);
		piwl.RST := FALSE;
	ELSE
		IF TN = 0.0 THEN
			piwl(in := IN * KP, KP := 1.0, KI := 0.0, LIM_L := LIM_L, LIM_H := LIM_H);
		ELSE
			piwl(in := IN * KP, KP := 1.0, KI := 1.0 / TN, LIM_L := LIM_L, LIM_H := LIM_H);
		END_IF;

		diff(IN := IN, K := KP * TV);
		Y := piwl.Y + diff.out;

		IF Y < LIM_L THEN
			LIM := TRUE;
			Y := LIM_L;
		ELSIF Y > LIM_H THEN
			LIM := TRUE;
			Y := LIM_H;
		ELSE
			LIM := FALSE;
		END_IF;
	END_IF;
END_FUNCTION_BLOCK

FUNCTION_BLOCK CTRL_OUT
	VAR_INPUT
		CI :	REAL;
		OFFSET :	REAL;
		MAN_IN :	REAL;
		LIM_L :	REAL;
		LIM_H :	REAL;
		MANUAL :	BOOL;
	END_VAR

	VAR_OUTPUT
		Y :	REAL;
		LIM :	BOOL;
	END_VAR

	Y := SEL(manual, CI, MAN_IN) + OFFSET;

	IF Y >= LIM_H THEN
		Y := LIM_H;
		LIM := TRUE;
	ELSIF Y <= lim_L THEN
		Y := LIM_L;
		LIM := TRUE;
	ELSE
		LIM := FALSE;
	END_IF;
END_FUNCTION_BLOCK

FUNCTION DEAD_ZONE:REAL

	VAR_INPUT
		X :	REAL;
		L :	REAL;
	END_VAR

	IF ABS(x) > L THEN
		dead_zone := X;
	ELSE
		DEAD_ZONE := 0.0;
	END_IF;

END_FUNCTION

FUNCTION CTRL_IN:REAL
	VAR_INPUT
		SET_POINT :	REAL;
		ACTUAL :	REAL;
		NOISE :	REAL;
	END_VAR
	CTRL_IN := DEAD_ZONE(SET_POINT - ACTUAL, NOISE);
END_FUNCTION

FUNCTION_BLOCK CTRL_PID
	VAR_INPUT
		ACT :	REAL;
		SET :	REAL;
		SUP :	REAL;
		OFS :	REAL;
		M_I :	REAL;
		MAN :	BOOL;
		RST :	BOOL := FALSE;
		KP :	REAL := 1.0;
		TN :	REAL := 1.0;
		TV :	REAL := 1.0;
