FUNCTION_BLOCK DEAD_BAND_A
	VAR_INPUT
		X :	REAL;
		T :	TIME;
		KL :	REAL := 1.0;
		LM :	REAL;
	END_VAR

	VAR_OUTPUT
		Y :	REAL;
		L :	REAL;
	END_VAR

	VAR
		tp1 :	FT_PT1;
		tp2 :	FT_PT1;
	END_VAR

	tp1(in := X, T:= T);
	tp2(in := ABS(tp1.out - X), T := MULTIME(T, 4.0));
	L := MIN(KL * tp2.out, LM);

	IF X > L THEN
		Y := X - L;
	ELSIF X < -L THEN
		Y := X + L;
	ELSE
		Y := 0.0;
	END_IF;
END_FUNCTION_BLOCK

