	IN :	REAL;
	N :	INT;
	RST :	BOOL;
	OUT :	REAL;
	func_block : DELAY;
  END_VAR
	func_block.IN  :=IN;
	func_block.N  :=N;
	func_block.RST  :=RST;
	func_block();
	OUT := func_block.OUT;

