FUNCTION_BLOCK ENERGY
	VAR_INPUT
		J :	REAL;
		C :	REAL;
		WH :	REAL;
	END_VAR

	VAR_OUTPUT
		YJ :	REAL;
		YC :	REAL;
		YWH :	REAL;
	END_VAR

	YJ := J + Wh * 3600.0 + C * 4.1868;
	YC := YJ * 0.238845896627496;
	YWh := YJ * 2.7777777778E-004;
END_FUNCTION_BLOCK

