		DT_IN :	UDINT;
		TS :	TIME;
	END_VAR

	VAR_OUTPUT
		STATUS_TO_ESR :	oscat_esr_data;
	END_VAR


	IF status < BYTE#100 THEN
		status_to_ESR.typ := BYTE#1;
	ELSIF status < BYTE#200 THEN
		status_to_ESR.typ := BYTE#2;
