	IF s0 <> X0 AND ((s0 < BYTE#100) OR (S0 > BYTE#99 AND S0 < BYTE#200 AND mode >= BYTE#2) OR (S0 > BYTE#199 AND mode = BYTE#3)) THEN

		status_to_ESR.status := s0;
