FUNCTION_BLOCK FADE
	VAR_INPUT
		IN1 :	REAL;
		IN2 :	REAL;
		F :	BOOL;
		TF :	TIME;
		RST :	BOOL;
	END_VAR

	VAR_OUTPUT
		Y :	REAL;
	END_VAR

	VAR
		rmx :	RMP_W;
	END_VAR
	rmx(rst := rst AND NOT F, set := rst AND F, pt := TF, up := F);
	Y := (in2 - In1) / 65535.0 * _WORD_TO_REAL(rmx.out) + in1;

END_FUNCTION_BLOCK

