FUNCTION_BLOCK FIFO_16
	VAR_INPUT
		DIN :	DWORD;
		E :	BOOL := TRUE;
		RD :	BOOL;
		WD :	BOOL;
		RST :	BOOL;
	END_VAR

	VAR_OUTPUT
