	END_VAR

	VAR_OUTPUT
		FINDB :	INT;
	END_VAR

	VAR
		pos :	INT;
		length :	INT;
		string_temp :	STRING;
	END_VAR

	length := LEN(str2);
	pos := LEN(str1) - length +1;
	WHILE (pos >= 1) DO
		string_temp := MID(str1,length,pos);
		IF EQ_STRING(string_temp,str2) THEN
			FindB := pos;
			RETURN;
		END_IF;
	pos := pos -1;
	END_WHILE;
	FindB := 0;

