FUNCTION_BLOCK FT_PID

	VAR_INPUT
		IN :	REAL;
		KP :	REAL := 1.0;
		TN :	REAL := 1.0;
		TV :	REAL := 1.0;
		ILIM_L :	REAL := -1.0E38;
		ILIM_H :	REAL := 1.0E38;
		IEN :	BOOL := TRUE;
		RST :	BOOL := FALSE;
	END_VAR

	VAR_OUTPUT
		Y :	REAL;
		LIM :	BOOL;
	END_VAR

	VAR
		integ :	FT_INT_Block;
		diff :	FT_DERIV;
	END_VAR


	IF TN > 0.0 THEN
		integ(IN := IN, K := 1.0 / TN, RUN := IEN, RST := RST, OUT_MIN := ILIM_L, OUT_MAX := ILIM_H);
	ELSE
		integ(RST := FALSE);
	END_IF;

	(* run differentiator *)
	diff(IN := IN, K := TV);

	(* combine both values *)
	Y := KP * (integ.Out + diff.out + IN);

	(* check if integrator has reached its limits and set overflow *)
	LIM := integ.LIM;

END_FUNCTION_BLOCK

