		diff(IN := IN, K := KP * TV);
		Y := piwl.Y + diff.out;

		IF Y < LIM_L THEN
			LIM := TRUE;
			Y := LIM_L;
		ELSIF Y > LIM_H THEN
			LIM := TRUE;
			Y := LIM_H;
		ELSE
			LIM := FALSE;
		END_IF;
	END_IF;
