FUNCTION_BLOCK ONTIME_Block

	VAR_INPUT
		IN :	BOOL;
		RST :	BOOL;
	END_VAR


	VAR_IN_OUT
		SECONDS :	UDINT;
		CYCLES :	UDINT;
	END_VAR


	VAR
		tx :	UDINT;
		last :	UDINT;
		edge :	BOOL;
		init :	BOOL;
		ms :	UDINT;
		T_PLC_MS :	T_PLC_MS_Block;
	END_VAR

	T_PLC_MS();
	tx:= T_PLC_MS.T_PLC_MS;

	IF NOT init THEN
		init := TRUE;
		last := tx;
		ms := UDINT#0;
	END_IF;
	IF RST THEN
		SECONDS := UDINT#0;
		CYCLES := UDINT#0;
		last := tx;
		ms := UDINT#0;
	ELSIF IN THEN
		(* add the current milliseconds *)
		ms := (tx - last) + ms;
		IF ms >= UDINT#1000 THEN
			seconds := seconds + UDINT#1;
			ms := ms - UDINT#1000;
		END_IF;
		cycles := cycles + BOOL_TO_UDINT(NOT edge);
	END_IF;
	last := tx;
	edge := in;

END_FUNCTION_BLOCK

FUNCTION_BLOCK F_LAMP_Block

	VAR_INPUT
		SWITCH :	BOOL;
		DIMM :	BYTE := BYTE#255;
		RST :	BOOL;
		T_NO_DIMM :	UINT := UINT#100;
		T_MAINTENANCE :	UINT := UINT#15000;
	END_VAR


	VAR_OUTPUT
		LAMP :	BYTE;
		STATUS :	BYTE;
	END_VAR


	VAR_IN_OUT
		ONTIME :	UDINT;
		CYCLES :	UDINT;
	END_VAR


	VAR
		runtime :	ONTIME_Block;
	END_VAR

	runtime(in := switch, SECONDS := ONTIME , CYCLES := CYCLES);
	CYCLES := runtime.CYCLES;
	ONTIME := runtime.SECONDS;

	IF RST THEN
		ONTIME := UDINT#0;
		CYCLES := UDINT#0;
	END_IF;
	IF SWITCH THEN
		IF ontime < UINT_TO_UDINT(T_NO_DIMM) * UDINT#3600 THEN
			LAMP := BYTE#255;
			STATUS := BYTE#111;
		ELSE
			LAMP := DIMM;
			STATUS := BYTE#112;
		END_IF;
	ELSE
		LAMP := BYTE#0;
		STATUS := BYTE#110;
	END_IF;

	IF ontime >= UINT_TO_UDINT(T_maintenance) * UDINT#3600 AND T_Maintenance > UINT#0 THEN
		STATUS := BYTE#120;
	END_IF;

END_FUNCTION_BLOCK

