		last :	TIME;
		init :	BOOL;
		T_PLC_MS :	T_PLC_MS_Block;
		FB_rdm :	RDM_block;
	END_VAR

	T_PLC_MS();
	tx:= UDINT_TO_TIME(T_PLC_MS.T_PLC_MS) - last;

	IF NOT init THEN
		init := TRUE;
		last := tx;
		tx := t#0s;
	END_IF;

	IF tx >= pt THEN
		last := last + pt;
		tx := tx - pt;

		FB_rdm(last:=0.0);
		out := am * (FB_rdm.RDM - 0.5) + os;
		q := TRUE;
	ELSE
		q := FALSE;
	END_IF;

END_FUNCTION_BLOCK

