		E :	BOOL;
		MODE :	INT;
		OUT :	BYTE;
		_TP :	BOOL;
		func_block : INTERLOCK_4_Block;
	END_VAR
	func_block.I0 := I0;
	func_block.I1 := I1;
	func_block.I2 := I2;
	func_block.I3 := I3;
	func_block.E := E;
	func_block.MODE := MODE;
