	VAR
		UDP_TCP :	BOOL;
		S_ENABLE :	BOOL;
		R_ENABLE :	BOOL;
		ERROR :	DWORD;
		IP_C :	oscat_IP_C;
		S_BUF :	oscat_NETWORK_BUFFER;
		R_BUF :	oscat_NETWORK_BUFFER;

