FUNCTION_BLOCK IS_SORTED_Block

	VAR_IN_OUT
		PT :	oscat_pt_ARRAY;
	END_VAR

	VAR_INPUT
		SIZE :	UINT;
	END_VAR

	VAR_OUTPUT
		IS_SORTED :	BOOL;
	END_VAR

	VAR
		i :	INT;
		i2 :	INT;
		stop :	INT;
	END_VAR

	stop :=LIMIT_INT(1,UINT_TO_INT(size),1000);
	stop := stop -1;
	FOR i := 1 TO stop DO
		i2 := i+1;
		IF pt[i] > pt[i2] THEN
			IS_SORTED := FALSE;
			RETURN;
		END_IF;
	END_FOR;

	IS_SORTED := TRUE;

END_FUNCTION_BLOCK

