FUNCTION_BLOCK M_T_Block

	VAR_INPUT
		IN :	BOOL;
		TMAX :	TIME := t#10d;
		RST :	BOOL;
	END_VAR


	VAR_OUTPUT
		PT :	TIME;
		ET :	TIME;
	END_VAR


	VAR
		edge :	BOOL;
		start :	TIME;
		tx :	TIME;
		T_PLC_MS :	T_PLC_MS_Block;
	END_VAR


	(*@KEY@: WORKSHEET
	NAME: M_T
	IEC_LANGUAGE: ST
	*)
	(* read system timer *)
	T_PLC_MS();
	tx:= UDINT_TO_TIME(T_PLC_MS.T_PLC_MS);

	IF RST OR ET >= TMAX THEN
		PT := t#0s;
		ET := PT;
	ELSIF IN THEN
		IF NOT edge THEN start := tx; END_IF;
		ET := tx - start;
	ELSE
		PT := ET;
	END_IF;
	edge := IN;

END_FUNCTION_BLOCK

