FUNCTION PARITY:BOOL

	VAR_INPUT
		IN :	DWORD;
	END_VAR

	VAR
		in2 :	DWORD;
	END_VAR


	in2:=in;
	WHILE in2 > DWORD#0 DO
		parity := parity XOR BIT_OF_DWORD(in2,0) XOR BIT_OF_DWORD(in2,1) XOR BIT_OF_DWORD(in2,2) XOR BIT_OF_DWORD(in2,3);
		in2 := SHR(in2,4);
	END_WHILE;

END_FUNCTION

