		T_SHORT :	TIME := T#100ms;
		T_LONG :	TIME := T#1s;
		SHORT :	BOOL;
		MIDDLE :	BOOL;
		LONG :	BOOL;

		func_block : PULSE_LENGTH_Block;
	END_VAR
	func_block.IN := IN;
	func_block.T_SHORT := T_SHORT;
	func_block.T_LONG := T_LONG ;

	func_block();
	SHORT  := func_block.SHORT;
	MIDDLE  := func_block.MIDDLE;
	LONG  := func_block.LONG;
