FUNCTION_BLOCK PULSE_T_Block

	VAR_INPUT
		IN :	BOOL;
		T1 :	TIME;
		T2 :	TIME;
		RST :	BOOL;
	END_VAR


	VAR_OUTPUT
		Q :	BOOL;
	END_VAR


	VAR
		init :	BOOL;
		last :	TIME;
		tx :	TIME;
		edge :	BOOL;
		T_PLC_MS :	T_PLC_MS_Block;
	END_VAR

	T_PLC_MS();
	tx:= UDINT_TO_TIME(T_PLC_MS.T_PLC_MS);

	IF NOT init THEN
		init := TRUE;
		last := tx;
	ELSIF RST THEN
		Q := FALSE;
	ELSIF IN AND NOT edge AND NOT Q THEN
		last := tx;
		Q := TRUE;
	ELSIF NOT IN AND edge AND ((tx - last) > T1) THEN
		Q := FALSE;
	ELSIF (tx - last) >= T2 THEN
		Q := FALSE;
	END_IF;

	edge := IN;

END_FUNCTION_BLOCK

