		ET :	TIME;
	END_VAR


	VAR
		edge :	BOOL;
		start :	TIME;
		tx :	TIME;
		T_PLC_MS :	T_PLC_MS_block;
	END_VAR


	T_PLC_MS();
	tx := UDINT_TO_TIME(T_PLC_MS.T_PLC_MS);

	IF IN AND NOT edge THEN
		start := tx;
		Q := PT > t#0ms;
	ELSIF Q THEN
		ET := tx - start;
		IF ET >= PT THEN
			Q := FALSE;
			ET := t#0ms;
		END_IF;
	END_IF;
	edge := IN;

END_FUNCTION_BLOCK

