		Q :	BOOL;
	END_VAR

	VAR
		clk :	CLK_Prg;
		pulse :	TP_X;
		tmp :	REAL;
	END_VAR

	IF F > 0.0 THEN
		tmp := 1000.0/F;
		CLK(PT := REAL_TO_TIME2(tmp));
		Pulse(in := clk.Q, pt := REAL_TO_TIME2(tmp*DC));
		Q := pulse.Q;
	END_IF;
END_FUNCTION_BLOCK

