FUNCTION_BLOCK SEQUENCE_64_Block

	VAR_INPUT
		START :	BOOL;
		SMAX :	INT;
		RST :	BOOL;
	END_VAR

	VAR_OUTPUT
		STATE :	INT := INT#-1;
		TRIG :	BOOL;
	END_VAR

	VAR_IN_OUT
		PROG :	oscat_array64_time;
	END_VAR

	VAR
		T_PLC_MS :	T_PLC_MS_block;
		tx :	TIME;
		last :	TIME;
		edge :	BOOL;
	END_VAR

	T_PLC_MS();
	tx:= UDINT_TO_TIME(T_PLC_MS.T_PLC_MS);
	TRIG := FALSE;

	IF RST THEN
		STATE := -1;

	ELSIF START AND NOT edge THEN
		STATE := 0;
		last := tx;
		TRIG := TRUE;

	ELSIF (STATE >= 0) THEN
		IF (tx - last) >= PROG[STATE] THEN
			STATE := INC2(STATE, 1, -1, SMAX);
			last := tx;
			TRIG := TRUE;
		END_IF;
	END_IF;

	edge := START;
END_FUNCTION_BLOCK

