			Q4 := Q5;
			Q5 := Q6;
			Q6 := Q7;
			Q7 := D7;
		ELSE
			Q7 := Q6;
			Q6 := Q5;
			Q5 := Q4;
			Q4 := Q3;
			Q3 := Q2;
