	END_VAR

	VAR
		last :	TIME;
		tx :	TIME;
		T_PLC_MS :	T_PLC_MS_block;
	END_VAR

	T_PLC_MS();
	tx:= UDINT_TO_TIME(T_PLC_MS.T_PLC_MS);

	IF tx - last >= PT THEN
		last := tx;
		out := in;
		trig := TRUE;
	ELSE
		trig := FALSE;
	END_IF;

END_FUNCTION_BLOCK

