FUNCTION_BLOCK SPEED_Block

	VAR_INPUT
		MS :	REAL;
		KMH :	REAL;
		KN :	REAL;
		MH :	REAL;
	END_VAR

	VAR_OUTPUT
		YMS :	REAL;
		YKMH :	REAL;
		YKN :	REAL;
		YMH :	REAL;
	END_VAR

	Yms := ms +
			kmh * 0.27777777777778 +
			kn * 0.5144444 +
			mh * 0.44704;
	Ykmh := Yms * 3.6;
	Ykn := Yms * 1.94384466037535;
	Ymh := Yms * 2.23693629205440;

END_FUNCTION_BLOCK

