  	out_STRING_TO_TOD :	UDINT;
    func_block : STRING_TO_TOD_Block;
  END_VAR
	func_block._TOD  := _TOD;
	func_block();
	out_STRING_TO_TOD  := func_block.out_STRING_TO_TOD;
END_PROGRAM

