		IN :	BOOL;
		RST :	BOOL;
		T_DEBOUNCE :	TIME := T#10ms;
		T_RECONFIG :	TIME := T#1s;
		T_ON_MAX :	TIME := T#0h;
		Q :	BOOL := FALSE;

		func_block : SWITCH_I_Block;
