FUNCTION MODR:REAL



	VAR_INPUT
		IN :	REAL;
		DIVI :	REAL;
	END_VAR


	IF divi = 0.0 THEN
		MODR := 0.0;
	ELSE
		MODR := in - DINT_TO_REAL(FLOOR2(in / divi)) * divi;
	END_IF;

END_FUNCTION

FUNCTION RAD:REAL


	VAR_INPUT
		DEG :	REAL;
	END_VAR


	Rad := modR(0.0174532925199433 * deg , 6.283185307179586476);

END_FUNCTION

FUNCTION TRIANGLE_A:REAL



	VAR_INPUT
		S1 :	REAL;
		A :	REAL;
		S2 :	REAL;
		S3 :	REAL;
	END_VAR


	IF A = 0.0 THEN
		TRIANGLE_A := SQRT((s1+s2+S3) * (s1+s2-S3) * (S2+S3-S1) * (S3+S1-S2)) * 0.25;
	ELSE
		TRIANGLE_A := S1 * S2 * SIN(RAD(A)) * 0.5;
	END_IF;

END_FUNCTION

