	VAR
		IN :	oscat_url;
		URL_TO_STRING :	oscat_STRING250;

		func_block : URL_TO_STRING_Block;
	END_VAR
	func_block.IN := IN;

	func_block();
	URL_TO_STRING  := func_block.URL_TO_STRING;
