FUNCTION_BLOCK V3_DPRO_Block

	VAR_INPUT
		A :	oscat_vector_3;
		B :	oscat_vector_3;
	END_VAR


	VAR_OUTPUT
		V3_DPRO :	REAL;
	END_VAR


	V3_DPRO := A.X * B.X + A.Y * B.Y + A.Z * B.Z;

