FUNCTION_BLOCK V3_ANG_Block

	VAR_INPUT
		A :	oscat_vector_3;
		B :	oscat_vector_3;
	END_VAR


	VAR_OUTPUT
		V3_ANG :	REAL;
	END_VAR


	VAR
		d :	REAL;
		V3_ABS :	V3_ABS_Block;
		V3_DPRO :	V3_DPRO_Block;
	END_VAR

	V3_ABS(A:=A);
	d :=V3_ABS.V3_ABS;

	V3_ABS(A:=B);
	d := d * V3_ABS.V3_ABS;

	IF d > 0.0 THEN
		V3_DPRO(A:=A,B:=B);
		V3_ANG := ACOS(LIMIT(-1.0, V3_DPRO.V3_DPRO / d,1.0));
	ELSE
		V3_ANG := 0.0;

	END_IF;

END_FUNCTION_BLOCK

