FUNCTION_BLOCK ACTUATOR_UD_Block

	VAR_INPUT
		UD :	BOOL;
		_ON :	BOOL;
		MANUAL :	BOOL;
		UP :	BOOL;
		DN :	BOOL;
		OFF :	BOOL;
		YUP_IN :	BOOL;
		YDN_IN :	BOOL;
		_TON :	TIME;
		TOFF :	TIME;
		OUT_RETURN :	BOOL;
	END_VAR


	VAR_OUTPUT
		YUP :	BOOL;
		YDN :	BOOL;
		STATUS :	BYTE;
	END_VAR


	VAR
		tx :	TIME;
		last :	TIME;
		init :	BOOL;
		T_PLC_MS :	T_PLC_MS_Block;
	END_VAR

	T_PLC_MS();
	tx:= UDINT_TO_TIME(T_PLC_MS.T_PLC_MS);

	IF NOT init THEN
		last := tx;
		init := TRUE;
	ELSIF off THEN
		Yup := FALSE;
		Ydn := FALSE;
		last := tx;
		status := BYTE#101;

	ELSIF ((Yup OR Ydn) AND tx - last < _TON) THEN RETURN;
	ELSIF NOT yup AND NOT ydn AND tx - last < toff THEN	RETURN;

	ELSIF manual THEN
		status := BYTE#102;
		IF yup AND NOT up OR ydn AND NOT dn THEN
			ydn := FALSE;
			yup := FALSE;
			last := tx;
		ELSIF UP AND NOT DN AND NOT OFF THEN
			Ydn := FALSE;
			Yup := TRUE;
			last := tx;
			status := BYTE#103;
		ELSIF DN AND NOT UP AND NOT OFF THEN
