FUNCTION_BLOCK A_TRIG

	VAR_INPUT
		IN :	REAL;
		RES :	REAL;
	END_VAR

	VAR_OUTPUT
		Q :	BOOL;
		D :	REAL;
	END_VAR

	VAR
		last_in :	REAL;
	END_VAR

	D := IN - LAST_IN;
	IF ABS(D) >= res THEN
		Q := TRUE;
		last_in := IN;
	ELSE
		Q := FALSE;
	END_IF;

END_FUNCTION_BLOCK

