FUNCTION_BLOCK BLIND_CONTROL_Block

	VAR_INPUT
		UP :	BOOL;
		DN :	BOOL;
		S_IN :	BYTE;
		PI :	BYTE;
		AI :	BYTE;
		T_UD :	TIME;
		T_ANGLE :	TIME;
