FUNCTION_BLOCK BLIND_SCENE_Block

	VAR_INPUT
		UP :	BOOL;
		DN :	BOOL;
		S_IN :	BYTE;
		PI :	BYTE;
		AI :	BYTE;
		ENABLE :	BOOL;
		SWRITE :	BOOL;
		SCENE :	BYTE;
	END_VAR


