		QD := TRUE;
	ELSE
		QU := UP;
		QD := DN;
		status := S_IN;
		po := pi;
		ao := ai;
	END_IF;

	IF swrite THEN
		status := BYTE#176;	
		sx[x][0] := pi;
		sx[x][1] := ai;
		IF enable THEN sx[x][2] := BYTE#1; ELSE sx[x][2] := BYTE#0; END_IF; 
	END_IF;

