		QD := NOT Alarm_up;
		status := BYTE#113;
	ELSIF Door THEN
		QU := TRUE;
		QD := FALSE;
		status := BYTE#114;
	ELSIF Rain AND NOT (up XOR dn) THEN
		QU := rain_up;
		QD := NOT rain_up;
		status := BYTE#115;
	ELSE
		QU := UP;
		QD := DN;
		status := S_IN;
		po := pi;
		ao := ai;
	END_IF;

