	STATUS  := func_block.STATUS;
	FAIL  := func_block.FAIL;
	RUNTIME1  := func_block.RUNTIME1;
	RUNTIME2  := func_block.RUNTIME2;
	CYCLES  := func_block.CYCLES;
END_PROGRAM

