		CLOG :	CLOG_Block;
		CSQRT :	CSQRT_Block;
	END_VAR

	y.re := (X.re - X.im)*(X.re + X.im) + 1.0;
	y.im := 2.0 * X.re * X.im;
	CSQRT(X:=y);
	y    := CSQRT.CSQRT;
	y.re := y.re + x.re;
	y.im := y.im + x.im;
	CLOG(X:=y);
	CASINH  := CLOG.CLOG;
END_FUNCTION_BLOCK

