FUNCTION_BLOCK CLICK_Block

	VAR_INPUT
		IN :	BOOL;
		T_DEBOUNCE :	TIME := T#10ms;
		T_SHORT :	TIME := T#200ms;
		T_PAUSE :	TIME := T#500ms;
		T_RECONFIG :	TIME := T#1m;
	END_VAR


	VAR_OUTPUT
		Q :	BOOL;
		SINGLE :	BOOL;
		DOUBLE :	BOOL;
		TRIPLE :	BOOL;
		STATUS :	BYTE;
	END_VAR


	VAR
		s_in :	SW_RECONFIG_Block;
		tx :	TIME;
		state :	INT;
		last :	TIME;
		T_PLC_MS :	T_PLC_MS_Block;
	END_VAR

	s_in(in := in, TD := T_debounce, TR := T_reconfig);

	T_PLC_MS();
	tx:= UDINT_TO_TIME(T_PLC_MS.T_PLC_MS);

	IF s_in.Q XOR Q THEN
		last := tx;
		IF s_in.Q THEN state := state + 1; END_IF;
	END_IF;
	Q := s_in.Q;

	IF state > 0 THEN
		IF (Q AND tx - last > t_short) OR (NOT Q AND tx - last > t_pause) THEN
			CASE state OF
				1:	single := TRUE;
					status := BYTE#111;
				2:	double := TRUE;
					status := BYTE#112;
				3:	triple := TRUE;
					status := BYTE#113;
			END_CASE;
			state := 0;
		END_IF;
	ELSIF NOT q THEN
		single := FALSE;
		double := FALSE;
		triple := FALSE;
		status := BYTE#110;
		last := tx;
		state := 0;
	END_IF;

END_FUNCTION_BLOCK

