FUNCTION_BLOCK CLICK_CNT
	VAR_INPUT
		IN :	BOOL;
		N :	INT;
		TC :	TIME;
	END_VAR

	VAR_OUTPUT
		Q :	BOOL;
	END_VAR

	VAR
		tx :	TP;
		edge :	BOOL;
		cnt :	INT := INT#-1;
	END_VAR

	Q := FALSE;

	IF in AND NOT edge AND NOT tx.q THEN
		cnt := 0;
	ELSIF tx.Q AND NOT IN AND edge THEN
		cnt := cnt + 1;
	ELSIF NOT tx.Q THEN
		Q := cnt=N;
		cnt := -1;
	END_IF;
	edge := IN;
	tx(in := IN, pt := TC);
END_FUNCTION_BLOCK

