			END_IF;
			dx := SHL(dx, 1);
		END_FOR;
	END_WHILE;

	FOR bits := 0 TO 31 DO
		IF (CRC_GEN AND DWORD#16#8000_0000) > DWORD#0 THEN (* CRC_GEN.31 *)
			CRC_GEN := (SHL(CRC_GEN, 1) OR BOOL_TO_DWORD((DX AND BYTE#16#80) > BYTE#0)) XOR PN; (* DX.7 *)
