END_FUNCTION

FUNCTION_BLOCK CTRL_PID
	VAR_INPUT
		ACT :	REAL;
		SET :	REAL;
		SUP :	REAL;
		OFS :	REAL;
		M_I :	REAL;
		MAN :	BOOL;
