FUNCTION DEAD_BAND:REAL

	VAR_INPUT
		X :	REAL;
		L :	REAL;
	END_VAR

	IF X > L THEN
		DEAD_BAND := X - L;
	ELSIF X < -L THEN
		DEAD_BAND := X + L;
	ELSE
		DEAD_BAND := 0.0;
	END_IF;

END_FUNCTION

