	func_block : DEAD_BAND_A;
  END_VAR
	func_block.X   :=X ;
	func_block.T   :=T ;
	func_block.KL  :=KL;
	func_block.LM  :=LM;
	func_block();
	Y := func_block.Y;
	L := func_block.L;
END_PROGRAM

