FUNCTION_BLOCK DEBOUNCE_Block

	VAR_INPUT
		IN :	BOOL;
		TD :	TIME;
		PM :	BOOL;
	END_VAR


	VAR_OUTPUT
		Q :	BOOL;
	END_VAR


	VAR
