		Q5 :	BOOL;
		Q6 :	BOOL;
		Q7 :	BOOL;
	END_VAR


	VAR
		X :	BYTE;
	END_VAR

	X:=BIT_LOAD_B(X,A0,0); (* X.0 := A0; *)
	X:=BIT_LOAD_B(X,A1,1); (* X.1 := A1; *)
	X:=BIT_LOAD_B(X,A2,2); (* X.2 := A2; *)

	Q0 := FALSE;
	Q1 := FALSE;
	Q2 := FALSE;
	Q3 := FALSE;
	Q4 := FALSE;
	Q5 := FALSE;
	Q6 := FALSE;
	Q7 := FALSE;

	CASE _BYTE_TO_INT(X) OF
		0 : Q0 := D;
		1 : Q1 := D;
		2 : Q2 := D;
		3 : Q3 := D;
		4 : Q4 := D;
		5 : Q5 := D;
		6 : Q6 := D;
		7 : Q7 := D;
	END_CASE;

