	END_VAR


	VAR
		T_PLC_MS :	T_PLC_MS_Block;
		tx :	TIME;
		tl :	TIME;
		tn :	TIME;
		init :	BOOL;
		last_dir :	BOOL;
		start :	BYTE;
	END_VAR


	T_PLC_MS();
	tx := UDINT_TO_TIME(T_PLC_MS.T_PLC_MS);

	IF E AND init AND (dir = last_dir) AND (RMP <> SEL(DIR, BYTE#0, BYTE#255)) AND TR = tn THEN
		RMP := FRMP_B(start, DIR, tx - tl, TR);
	ELSE
		init := TRUE;
		tl := tx;
		tn := tr;
		start := RMP;
	END_IF;
	last_dir := dir;
END_FUNCTION_BLOCK

FUNCTION_BLOCK CLICK_MODE_Block

	VAR_INPUT
		IN :	BOOL;
		T_LONG :	TIME := T#500ms;
	END_VAR


	VAR_OUTPUT
		SINGLE :	BOOL;
		DOUBLE :	BOOL;
		LONG :	BOOL;
		TP_LONG :	BOOL;
	END_VAR


	VAR
		Timer :	TP;
		cnt :	INT;
		last :	BOOL;
	END_VAR

	timer(in := IN, PT := T_LONG);
	single := FALSE;
	double := FALSE;

	IF timer.Q THEN
		IF NOT in AND last THEN	cnt := cnt + 1; END_IF;
	ELSE
		CASE cnt OF
			1 : single := TRUE;
			2 : double := TRUE;
		END_CASE;
		cnt := 0;
	END_IF;
	last := in;
	TP_LONG := NOT timer.Q AND (NOT LONG) AND IN;
	LONG := NOT timer.Q AND in;

END_FUNCTION_BLOCK

FUNCTION_BLOCK DIMM_2_Block

	VAR_INPUT
		SET :	BOOL;
		VAL :	BYTE := BYTE#255;
		I1 :	BOOL;
		I2 :	BOOL;
		RST :	BOOL;
		T_DEBOUNCE :	TIME := T#10ms;
		T_ON_MAX :	TIME := T#0h;
		T_DIMM_START :	TIME := T#1s;
		T_DIMM :	TIME := T#3s;
		MIN_ON :	BYTE := BYTE#50;
		MAX_ON :	BYTE := BYTE#255;
		RST_OUT :	BOOL;
		SOFT_DIMM :	BOOL := TRUE;
		DBL1_TOG :	BOOL;
		DBL2_TOG :	BOOL;
		DBL1_SET :	BOOL;
		DBL2_SET :	BOOL;
		DBL1_POS :	BYTE;
		DBL2_POS :	BYTE;
	END_VAR


	VAR_OUTPUT
		Q :	BOOL;
		D1 :	BOOL;
		D2 :	BOOL;
	END_VAR


	VAR_IN_OUT
		_OUT :	BYTE;
	END_VAR


	VAR
		t1 :	TOF;
		t2 :	TOF;
		dc1 :	CLICK_MODE_Block;
		dc2 :	CLICK_MODE_Block;
		t3 :	TON;
		dim :	_RMP_B;
	END_VAR

	t1(IN := I1, PT := T_DEBOUNCE);
	t2(IN := I2, PT := T_DEBOUNCE);
	dc1(in := t1.Q, T_LONG := T_DIMM_START);
	dc2(in := t2.Q, T_LONG := T_DIMM_START);

	IF RST THEN
		IF RST_OUT THEN _OUT := BYTE#0; END_IF;
		Q := FALSE;
		D1 := FALSE;
		D2 := FALSE;
	ELSIF set THEN
		_OUT := VAL;
		Q := TRUE;
	ELSIF dc1.SINGLE THEN
		_OUT := LIMIT(MAX(MIN_ON,BYTE#1), _OUT, MAX_ON);
		Q := TRUE;
	ELSIF dc2.SINGLE THEN
		Q := FALSE;
	ELSIF dc1.TP_LONG THEN
		IF NOT Q THEN
			_OUT := SEL(SOFT_DIMM, LIMIT(MAX(MIN_ON,BYTE#1), _OUT, MAX_ON), BYTE#1);
		END_IF;
		Q := TRUE;
		dim.DIR := TRUE;
	ELSIF dc2.TP_LONG THEN
		dim.DIR := FALSE;
	END_IF;

	IF NOT DBL1_TOG THEN D1 := FALSE; END_IF;
	IF dc1.DOUBLE THEN
		IF DBL1_SET THEN
			_OUT := DBL1_POS;
			Q := TRUE;
		ELSE
			D1 := NOT D1;
		END_IF;
	END_IF;
	IF NOT DBL2_TOG THEN D2 := FALSE; END_IF;
	IF dc2.DOUBLE THEN
		IF DBL2_SET THEN
			_OUT := DBL2_POS;
			Q := TRUE;
		ELSE
			D2 := NOT D2;
		END_IF;
	END_IF;


	dim(dir := dc2.LONG, e := dc1.LONG OR dc2.LONG , TR := T_DIMM, rmp := _OUT);
	_OUT := dim.RMP;

	IF _OUT = BYTE#0 THEN Q := FALSE; END_IF;

	IF t_ON_MAX > t#0s THEN
		t3(in := q, pt := T_ON_MAX);
		Q := Q XOR t3.Q;
	END_IF;

END_FUNCTION_BLOCK

