FUNCTION_BLOCK FIFO_16
	VAR_INPUT
		DIN :	DWORD;
		E :	BOOL := TRUE;
		RD :	BOOL;
		WD :	BOOL;
		RST :	BOOL;
	END_VAR

	VAR_OUTPUT
		DOUT :	DWORD;
		EMPTY :	BOOL := TRUE;
		FULL :	BOOL;
	END_VAR

	VAR
		fifo :	oscat_ardw_0_15;
		pr :	INT;
		pw :	INT;
	END_VAR

	IF RST THEN
		pw := pr;
		FULL := FALSE;
		EMPTY := TRUE;
		Dout := DWORD#0;
	ELSIF E THEN
		IF NOT EMPTY AND RD THEN
			Dout := fifo[pr];
			pr := INC1(pr,16);
			EMPTY := pr = pw;
			FULL := FALSE;
		END_IF;
		IF NOT FULL AND WD THEN
			fifo[pw] := Din;
			pw := INC1(pw,16);
			FULL := pw = pr;
			EMPTY := FALSE;
		END_IF;
	END_IF;
END_FUNCTION_BLOCK

