	IF RST THEN
		pw := pr;
		FULL := FALSE;
		EMPTY := TRUE;
		Dout := DWORD#0;
	ELSIF E THEN
		IF NOT EMPTY AND RD THEN
			Dout := fifo[pr];
			pr := INC1(pr,32);
			EMPTY := pr = pw;
			FULL := FALSE;
		END_IF;
		IF NOT FULL AND WD THEN
			fifo[pw] := Din;
			pw := INC1(pw,32);
			FULL := pw = pr;
			EMPTY := FALSE;
		END_IF;
	END_IF;

END_FUNCTION_BLOCK

