		FILENAME :	oscat_STRING250;
		FILE_PATH_SPLIT :	BOOL;
		X :	oscat_FILE_PATH_DATA;

		func_block : FILE_PATH_SPLIT_Block;
	END_VAR
	func_block.FILENAME := FILENAME;
	func_block.X := X;

	func_block();
	FILE_PATH_SPLIT  := func_block.FILE_PATH_SPLIT;
	X  := func_block.X;
