FUNCTION_BLOCK TP_1D
	VAR_INPUT
		IN :	BOOL;
		PT1 :	TIME;
		PTD :	TIME;
		RST :	BOOL;
	END_VAR


	VAR_OUTPUT
		Q :	BOOL;
		W :	BOOL;
	END_VAR

	VAR
		tx :	TIME;
		start :	TIME;
		ix :	BOOL;
		T_PLC_MS :	T_PLC_MS_block;
	END_VAR

	T_PLC_MS();
	tx := UDINT_TO_TIME(T_PLC_MS.T_PLC_MS);

	IF RST THEN
		Q := FALSE;
		rst := FALSE;
		W := FALSE;
	ELSIF W THEN
		IF tx - start >= PTD THEN
			W := FALSE;
		END_IF;
	ELSIF IN AND NOT ix THEN
		Q := TRUE;
		start := tx;
		in := FALSE;
	ELSIF tx - start >= PT1 THEN
		Q := FALSE;
		W := TRUE;
		start := tx;
	END_IF;

	ix := IN;

END_FUNCTION_BLOCK

FUNCTION_BLOCK FLOW_CONTROL
	VAR_INPUT
		IN :	BOOL;
		REQ :	BOOL;
		ENQ :	BOOL;
		RST :	BOOL := FALSE;
		T_AUTO :	TIME := T#1h;
		T_DELAY :	TIME := T#23h;
	END_VAR

	VAR_OUTPUT
		Q :	BOOL;
		STATUS :	BYTE;
	END_VAR

	VAR
		timer :	TP_1D;
	END_VAR

	STATUS := BYTE#100;
	IF RST THEN
		Q := FALSE;
		timer(rst := TRUE);
		timer.RST := FALSE;
		STATUS := BYTE#103;
	ELSIF ENQ THEN
		IF IN THEN
			status := BYTE#101;
		END_IF;
		IF REQ THEN
			(* timer will generate a timed pulse after TP goes high *)
			timer.PT1 := T_AUTO;
			timer.PTD := T_DELAY;
			timer.IN := TRUE;
			STATUS := BYTE#102;
		END_IF;
	END_IF;

	timer();
	timer.IN := FALSE;
	Q := (IN AND ENQ) OR timer.Q;
END_FUNCTION_BLOCK

PROGRAM program0
  VAR
	IN      :	BOOL;
	REQ     :	BOOL;
	ENQ     :	BOOL;
	RST     :	BOOL ;
	T_AUTO  :	TIME ;
	T_DELAY :	TIME ;

	Q      :	BOOL;
	STATUS :	BYTE;

	func_block : FLOW_CONTROL;
  END_VAR
	func_block.IN     :=IN     ;
	func_block.REQ    :=REQ    ;
	func_block.ENQ    :=ENQ    ;
	func_block.RST    :=RST    ;
	func_block.T_AUTO :=T_AUTO ;
	func_block.T_DELAY:=T_DELAY;
	func_block();
	Q     := func_block.Q     ;
	STATUS:= func_block.STATUS;
END_PROGRAM

