FUNCTION_BLOCK FT_INT2_Block

	VAR_INPUT
		IN :	REAL;
		K :	REAL := 1.0;
		RUN :	BOOL := TRUE;
		RST :	BOOL;
		OUT_MIN :	REAL := REAL#-1.0E-37;
		OUT_MAX :	REAL := REAL#1.0E37;
	END_VAR

	VAR_OUTPUT
		OUT :	REAL;
		LIM :	BOOL;
	END_VAR

	VAR
		integ :	INTEGRATE;
		ix :	REAL;
		val :	REAL2;
		R2_ADD :	R2_ADD_Block;
		R2_SET :	R2_SET_Block;
	END_VAR

	IF RST THEN
		R2_SET(X:=0.0);
		val:=R2_SET.R2_SET;
		out := 0.0;
	ELSE
		integ(X := IN, E := RUN, K := K, Y := ix);
		ix := integ.Y;
		R2_ADD(X:=val,Y:=ix);
		val:=R2_ADD.R2_ADD;
		ix := 0.0;
		OUT := val.RX;
	END_IF;

	(* check output for limits *)
	IF out > OUT_MIN AND out < OUT_MAX THEN
		LIM := FALSE;
	ELSE
		OUT := LIMIT(OUT_MIN, OUT, OUT_MAX);
		R2_SET(X:=OUT);
		val:=R2_SET.R2_SET;
		LIM := TRUE;
	END_IF;

END_FUNCTION_BLOCK

