FUNCTION_BLOCK FT_INT_Block

	VAR_INPUT
		IN :	REAL;
		K :	REAL := 1.0;
		RUN :	BOOL := TRUE;
		RST :	BOOL;
		OUT_MIN :	REAL := REAL#-1.0E-37;
		OUT_MAX :	REAL := REAL#1.0E37;
	END_VAR

	VAR_OUTPUT
		OUT :	REAL;
		LIM :	BOOL;
	END_VAR

	VAR
		INTEG :	INTEGRATE;
	END_VAR


	IF rst THEN
		out := 0.0;
	ELSE
		integ(X := IN, E := RUN, K := K, Y := out);
		out := integ.Y;
	END_IF;

	(* limit the outputs *)
	IF out >= OUT_MAX THEN
		out := out_max;
		LIM := TRUE;
	ELSIF out <= out_min THEN
		out := out_min;
		lim := TRUE;
	ELSE
		lim := FALSE;
	END_IF;

END_FUNCTION_BLOCK

FUNCTION_BLOCK FT_DERIV
	VAR_INPUT
		IN :	REAL;
		K :	REAL := 1.0;
		RUN :	BOOL := TRUE;
	END_VAR

	VAR_OUTPUT
		OUT :	REAL;
	END_VAR

	VAR
		old :	REAL;
		tx :	UDINT;
		last :	UDINT;
