	END_VAR

	T_PLC_US();
	tx:= T_PLC_US.T_PLC_US;
	tc := UDINT_TO_REAL(tx - last);

	IF NOT init THEN
		init := TRUE;
		old := in;
	ELSIF run AND tc > 0.0 THEN
		out := (in - old) / tc * 1000000.0 * K;
		old := in;
	ELSE
		out := 0.0;
	END_IF;

	last := tx;

	T_PLC_US();
	tx:= T_PLC_US.T_PLC_US;

	IF NOT init THEN
		init := TRUE;
	ELSIF run AND tx - last > UDINT#0 THEN
		out := (in - old) / UDINT_TO_REAL(tx - last) * 1000000.0 * K;
	ELSE
		out := 0.0;
	END_IF;
	old := in;
	last := tx;
END_FUNCTION_BLOCK

FUNCTION_BLOCK FT_PID

	VAR_INPUT
		IN :	REAL;
		KP :	REAL := 1.0;
		TN :	REAL := 1.0;
		TV :	REAL := 1.0;
		ILIM_L :	REAL := -1.0E38;
		ILIM_H :	REAL := 1.0E38;
		IEN :	BOOL := TRUE;
		RST :	BOOL := FALSE;
	END_VAR

	VAR_OUTPUT
		Y :	REAL;
		LIM :	BOOL;
	END_VAR

	VAR
		integ :	FT_INT_Block;
		diff :	FT_DERIV;
	END_VAR


	IF TN > 0.0 THEN
		integ(IN := IN, K := 1.0 / TN, RUN := IEN, RST := RST, OUT_MIN := ILIM_L, OUT_MAX := ILIM_H);
	ELSE
		integ(RST := FALSE);
	END_IF;

	(* run differentiator *)
	diff(IN := IN, K := TV);

	(* combine both values *)
	Y := KP * (integ.Out + diff.out + IN);

	(* check if integrator has reached its limits and set overflow *)
	LIM := integ.LIM;

END_FUNCTION_BLOCK

