		diff :	FT_DERIV;
	END_VAR

	IF rst THEN
		piwl(rst := TRUE);
		piwl.RST := FALSE;
	ELSE
		IF TN = 0.0 THEN
			piwl(in := IN * KP, KP := 1.0, KI := 0.0, LIM_L := LIM_L, LIM_H := LIM_H);
		ELSE
			piwl(in := IN * KP, KP := 1.0, KI := 1.0 / TN, LIM_L := LIM_L, LIM_H := LIM_H);
		END_IF;

		diff(IN := IN, K := KP * TV);
		Y := piwl.Y + diff.out;

		IF Y < LIM_L THEN
			LIM := TRUE;
			Y := LIM_L;
		ELSIF Y > LIM_H THEN
			LIM := TRUE;
			Y := LIM_H;
		ELSE
			LIM := FALSE;
		END_IF;
	END_IF;
END_FUNCTION_BLOCK

