FUNCTION_BLOCK INTEGRATE

	VAR_INPUT
		E :	BOOL := TRUE;
		X :	REAL;
		K :	REAL := 1.0;
	END_VAR

	VAR_IN_OUT
		Y :	REAL;
	END_VAR

	VAR
		X_last :	REAL;
		init :	BOOL;
		T_PLC_MS :	T_PLC_MS_block;
		last :	UDINT;
		tx :	UDINT;
	END_VAR


	T_PLC_MS();
	tx:= T_PLC_MS.T_PLC_MS;

	IF NOT init THEN
		init := TRUE;
		X_last := X;
	ELSIF E THEN
		Y := (X + X_LAST) * 0.5E-3 * UDINT_TO_REAL(tx-last) * K + Y;
		X_last := X;
	END_IF;
	last := tx;

END_FUNCTION_BLOCK

FUNCTION_BLOCK FT_PT2

	VAR_INPUT
		IN :	REAL;
		T :	TIME;
		D :	REAL;
		K :	REAL := 1.0;
	END_VAR

	VAR_OUTPUT
		OUT :	REAL;
	END_VAR

	VAR
		init :	BOOL;
		int1 :	INTEGRATE;
		int2 :	INTEGRATE;
		tn :	REAL;
		I1 :	REAL;
		I2 :	REAL;
		tn2 :	REAL;
	END_VAR

	IF NOT init OR T = T#0s THEN
		init := TRUE;
		out := K * in;
		I2 := out;
	ELSE
		TN := TIME_TO_REAL(T) / 1000.0;
		tn2 := TN * TN;
		int1(X := in * K / tn2 - I1 * 0.5 * D / TN - I2 / TN2, Y := I1);
		I1 := int1.Y;
		int2(X := I1,Y := I2);
		I2 := int2.Y;
		out := I2;
	END_IF;

END_FUNCTION_BLOCK

PROGRAM program0
	VAR
		IN :	REAL;
		T :	TIME;
		D :	REAL;
		K :	REAL := 1.0;

		OUT :	REAL;

		func_block : FT_PT2;
	END_VAR
	func_block.IN := IN;
	func_block.T := T;
	func_block.D := D;
	func_block.K := K;
	func_block();
	OUT := func_block.OUT;
END_PROGRAM

