	VAR
		RMP :	BOOL := TRUE;
		IN :	REAL;
		KR :	REAL;
		KF :	REAL;

		OUT :	REAL;
		BUSY :	BOOL;
		UD :	BOOL;

		func_block : FT_RMP;
	END_VAR
	func_block.RMP := RMP;
	func_block.IN := IN;
	func_block.KR := KR;
	func_block.KF := KF;
	func_block();
	OUT := func_block.OUT;
	BUSY := func_block.BUSY;
	UD := func_block.UD;

END_PROGRAM

