FUNCTION_BLOCK GEN_PW2_Block

	VAR_INPUT
		ENQ :	BOOL;
		TH1 :	TIME;
		TL1 :	TIME;
		TH2 :	TIME;
		TL2 :	TIME;
		TS :	BOOL;
	END_VAR


	VAR_OUTPUT
		Q :	BOOL;
		TH :	TIME;
		TL :	TIME;
	END_VAR


	VAR
		T_PLC_MS :	T_PLC_MS_Block;
		t_high :	TIME;
		t_low :	TIME;
		tx :	TIME;
		start :	TIME;
		init :	BOOL;
		et :	TIME;
	END_VAR

	T_PLC_MS();
	tx:= UDINT_TO_TIME(T_PLC_MS.T_PLC_MS);

	IF NOT init THEN
		start := tx;
		init := TRUE;
		TH := T#0s;
		TL := T#0s;
	END_IF;

	IF TS THEN
		t_high := TH2;
		t_low := TL2;
	ELSE
		t_high := TH1;
		t_low := TL1;
	END_IF;

	IF ENQ THEN
		et := tx - start;
		IF NOT Q THEN
			IF et >= t_low THEN
				Q := TRUE;
				start := tx;
				TL := T#0s;
			ELSE
				TL := et;
			END_IF;
		ELSE
			IF et >= t_high THEN
				Q := FALSE;
				start := tx;
				TH := T#0s;
			ELSE
				TH := et;
			END_IF;
		END_IF;
	ELSE
		Q := FALSE;
		TH := T#0s;
		TL := T#0s;
		start := tx;
	END_IF;

END_FUNCTION_BLOCK

