FUNCTION_BLOCK GEN_SQR_Block

	VAR_INPUT
		PT :	TIME;
		AM :	REAL := REAL#1.0;
		OS :	REAL;
		DC :	REAL := REAL#0.5;
		DL :	REAL;
	END_VAR


	VAR_OUTPUT
		Q :	BOOL;
		Out :	REAL;
	END_VAR


	VAR
		tx :	TIME;
		last :	TIME;
		init :	BOOL;
		T_PLC_MS :	T_PLC_MS_Block;
	END_VAR

	IF dc = 0.0 THEN
		out := -am * 0.5 + os;
		Q := FALSE;
		RETURN;
	ELSIF dc = 1.0 THEN
		out := am * 0.5 + os;
		Q := TRUE;
		RETURN;
	END_IF;

	T_PLC_MS();
	tx:= UDINT_TO_TIME(T_PLC_MS.T_PLC_MS) - last;
	DL := modR(dl,1.0);
	IF dl < 0.0 THEN dl := 1.0 - dl; END_IF;
	dc := modR(dc,1.0);
	IF dc < 0.0 THEN dc := 1.0 - dc; END_IF;

	IF NOT init THEN
		init := TRUE;
		last := tx;
		tx := t#0s;
	END_IF;

	IF tx >= pt THEN
		last := last + pt;
		tx := tx - pt;
	END_IF;

	IF multime(pt, dl + dc) >= pt THEN
		IF tx >= multime(pt, dl + dc - 1.0) THEN
			out := -am * 0.5 + os;
			Q := FALSE;
		END_IF;
		IF tx >= multime(pt, dl) THEN
			out := am * 0.5 + os;
			Q := TRUE;
		END_IF;
	ELSE
		IF tx >= multime(pt, dl) THEN
			out := am * 0.5 + os;
			Q := TRUE;
		END_IF;
		IF tx >= multime(pt, dl + dc) THEN
			out := -am * 0.5 +os;
			Q := FALSE;
		END_IF;
	END_IF;

END_FUNCTION_BLOCK

