		FIFO :	oscat_IP_FIFO_DATA;
    ID :	BYTE;
    STATE :	BYTE;

		func_block : IP_FIFO_Block;
	END_VAR
	func_block.FIFO := FIFO;
	func_block.ID := ID;
  func_block.STATE := STATE;

	func_block();
  FIFO  := func_block.FIFO;
	ID  := func_block.ID;
