	VAR
		X :	REAL;
		XY :	oscat_XY;
		PTS :	INT;

		LINEAR_INT :	REAL;

		func_block : LINEAR_INT_Block;
	END_VAR
	func_block.X := X;
	func_block.XY := XY;
	func_block.PTS := PTS;

	func_block();
	LINEAR_INT := func_block.LINEAR_INT;


END_PROGRAM

