		RUN :	BOOL;

		func_block : M_D_Block;
	END_VAR
	func_block.START := START;
	func_block.STOP := STOP;
	func_block.TMAX := TMAX;
	func_block.RST := RST;

	func_block();
	PT := func_block.PT;
