FUNCTION_BLOCK PULSE_LENGTH_Block

	VAR_INPUT
		IN :	BOOL;
		T_SHORT :	TIME := T#100ms;
		T_LONG :	TIME := T#1s;
	END_VAR


	VAR_OUTPUT
		SHORT :	BOOL;
		MIDDLE :	BOOL;
		LONG :	BOOL;
	END_VAR


	VAR
		tx :	TIME;
		tn :	TIME;
		edge :	BOOL;
		T_PLC_MS :	T_PLC_MS_Block;
	END_VAR

	T_PLC_MS();
	tx:= UDINT_TO_TIME(T_PLC_MS.T_PLC_MS);

	short := FALSE;
	Middle := FALSE;
	long := FALSE;

	IF in AND NOT edge THEN
		edge := TRUE;
		tn := tx;

	ELSIF NOT in AND edge THEN
		edge := FALSE;
		tn := tx - tn;
		IF tn < t_short THEN
			short := TRUE;
		ELSIF tn > t_long THEN
			long := TRUE;
		ELSE
			Middle := TRUE;
		END_IF;

	ELSIF in AND tx - tn > t_long THEN
		long := TRUE;
	END_IF;

END_FUNCTION_BLOCK

