	END_VAR

	IF REAL_TO_DINT(0.5) = DINT#1 THEN
		_REAL_TO_DINT := REAL_TO_DINT(x);
		RETURN;
	END_IF;

	IF X > 0.0 THEN
		_REAL_TO_DINT := REAL_TO_DINT(x+0.5); 
	ELSIF X < 0.0 THEN 
		_REAL_TO_DINT := REAL_TO_DINT(x-0.5); 
