FUNCTION_BLOCK RMP_SOFT_Block

	VAR_INPUT
		IN :	BOOL;
		VAL :	BYTE;
		PT_ON :	TIME := T#100ms;
		PT_OFF :	TIME := T#100ms;
	END_VAR

	VAR_OUTPUT
		OUT :	BYTE := BYTE#00;
	END_VAR


	VAR
		rmp :	_RMP_B;
		tmp :	BYTE;
	END_VAR


	tmp := SEL(in, BYTE#0, val);
	IF tmp > out THEN
		(* we need to ramp down *)
		rmp(dir := TRUE, E := TRUE, TR := PT_ON, RMP := out);
		out := rmp.RMP; 
		(* make sure out does not surpass tmp *)
		out := MIN(out, tmp);
	ELSIF tmp < out THEN
		(* we need to ramp up *)
		rmp(dir := FALSE, E := TRUE, TR := PT_OFF, RMP := out);
		out := rmp.RMP; 
