	VAR
		E0 :	BOOL;
		E1 :	BOOL;
		E2 :	BOOL;
		E3 :	BOOL;
		T0 :	TIME;
		T1 :	TIME;
		T2 :	TIME;
		T3 :	TIME;
		Q0 :	BOOL;
		Q1 :	BOOL;
		Q2 :	BOOL;
		Q3 :	BOOL;
