		FULL :	BOOL;
	END_VAR


	VAR
		pt :	INT;
		stack :	oscat_ardw_0_15;
	END_VAR


	IF RST THEN
		pt := 0;
		EMPTY := TRUE;
		FULL := FALSE;
		Dout := DWORD#0;
	ELSIF E THEN
		IF NOT EMPTY AND RD THEN
			pt := pt - 1;
			Dout := stack[pt];
			EMPTY := pt = 0;
			FULL := FALSE;
		END_IF;
		IF NOT FULL AND WD THEN
			stack[pt] := Din;
			pt := pt + 1;
			FULL := pt > 15;
			EMPTY := FALSE;
		END_IF;
	END_IF;

END_FUNCTION_BLOCK

