		Q6 :	BOOL;
		Q31 :	BOOL;
		Q41 :	BOOL;
		Q51 :	BOOL;
		Q61 :	BOOL;
		Q32 :	BOOL;
		Q42 :	BOOL;
		Q52 :	BOOL;
		Q62 :	BOOL;
	END_VAR


	VAR
		INIT :	BOOL;
		T1 :	TOF;
		T2 :	TOF;
		T3 :	TOF;
		T4 :	TOF;
		T5 :	TOF;
		T6 :	TOF;
		tx :	TIME;
		x1 :	BOOL;
		x2 :	BOOL;
		E1 :	BOOL;
		E2 :	BOOL;
	END_VAR

	IF NOT init THEN
		init := TRUE;
		IF t_debounce < t#50ms THEN tx := t#50ms; ELSE tx := t_debounce; END_IF;
