	END_VAR


	VAR
		cx :	ACTUATOR_COIL_Block;
		tn :	TON;
		tl :	TONOF;
		open :	BOOL;
	END_VAR

	tl(in := level, T_ON := level_delay_time, T_OFF := level_delay_time);
	open := tl.Q;

	IF ALARM THEN
		IF ACLR THEN
			ALARM := FALSE;
			STATUS := BYTE#101;
			cx(in := FALSE);
		END_IF;
		RETURN;
	ELSIF LEAK THEN
		cx(in := FALSE);
		ALARM := TRUE;
		STATUS := BYTE#1;	
	ELSIF open THEN
		cx(in := TRUE);
		STATUS := BYTE#102;
	ELSE
		cx(in := FALSE);
		STATUS := BYTE#100;
	END_IF;

	tn(in := cx.out AND (MAX_VALVE_TIME > T#0s), PT := MAX_VALVE_TIME);
	IF tn.Q THEN
		ALARM := TRUE;
		STATUS := BYTE#2; 
		cx(in := FALSE);
	END_IF;

	VALVE := cx.out;
END_FUNCTION_BLOCK

