	VAR
		R_BUF :	oscat_NETWORK_BUFFER;
    Xus_TN_SCREEN :	us_TN_SCREEN;

		func_block : TN_RECEIVE_Block;
	END_VAR
	func_block.R_BUF := R_BUF;
	func_block.Xus_TN_SCREEN := Xus_TN_SCREEN;

	func_block();
  R_BUF  := func_block.R_BUF;
	Xus_TN_SCREEN  := func_block.Xus_TN_SCREEN;
END_PROGRAM

