  CASE Iin_Border OF
  0:
    in_Border_Offset := 0;

  1:
    by_BorderChar_L_T := BYTE#218; 
    by_BorderChar_T   := BYTE#196; 
    by_BorderChar_R_T := BYTE#191; 
    by_BorderChar_L   := BYTE#179; 
