FUNCTION_BLOCK TUNE_Block

	VAR_INPUT
		SET :	BOOL;
		SU :	BOOL;
		SD :	BOOL;
		RST :	BOOL;
		SS :	REAL := 0.1;
		LIMIT_L :	REAL;
		LIMIT_H :	REAL := 100.0;
		RST_VAL :	REAL;
		SET_VAL :	REAL := 100.0;
		T1 :	TIME := T#500ms;
		T2 :	TIME := T#2s;
		S1 :	REAL := 2.0;
		S2 :	REAL := 10.0;
	END_VAR


	VAR_OUTPUT
		Y :	REAL;
	END_VAR


	VAR
		tx :	UDINT;
		start :	UDINT;
		start2 :	UDINT;
		state :	INT;
		in :	BOOL;
		step2 :	REAL;
		speed :	REAL;
		Y_start :	REAL;
		Y_start2 :	REAL;
		T_PLC_MS :	T_PLC_MS_Block;
	END_VAR


	T_PLC_MS();
	tx:= T_PLC_MS.T_PLC_MS;

	IF rst THEN
		Y := RST_val;
		state := 0;
	ELSIF set THEN
		Y := SET_val;
		state := 0;
	ELSIF state > 0 THEN
		IF state = 1 THEN
			in := su;
		ELSE
			in := sd;
		END_IF;
		IF NOT in AND tx - start <= TIME_TO_UDINT2(T1) THEN
			Y := Y_start + step2;
			state := 0;
		ELSIF in AND tx - start >= TIME_TO_UDINT2(T2) THEN
