FUNCTION_BLOCK TUNE2_Block

	VAR_INPUT
		SET :	BOOL;
		SU :	BOOL;
		SD :	BOOL;
		FU :	BOOL;
		FD :	BOOL;
		RST :	BOOL;
		SS :	REAL := 0.1;
		FS :	REAL := 5.0;
		LIMIT_L :	REAL;
		LIMIT_H :	REAL := 100.0;
		RST_VAL :	REAL;
		SET_VAL :	REAL := 100.0;
		TR :	TIME := T#500ms;
		S1 :	REAL := 2.0;
		S2 :	REAL := 10.0;
	END_VAR

	VAR_OUTPUT
		Y :	REAL;
	END_VAR

	VAR
		tx :	UDINT;
		start :	UDINT;
		state :	INT;
		in :	BOOL;
		step2 :	REAL;
		speed :	REAL;
		Y_start :	REAL;
		T_PLC_MS :	T_PLC_MS_block;
	END_VAR

	T_PLC_MS();
	tx:= T_PLC_MS.T_PLC_MS;

	IF rst THEN
		Y := RST_val;
		state := 0;
	ELSIF set THEN
		Y := SET_val;
		state := 0;
	ELSIF state > 0 THEN
		CASE state OF
			1 :	
				in := su;
			2 :	
				in := sd;
			3 :	
				in := fu;
			4 :	
				in := fd;
		END_CASE;
		IF NOT in AND tx - start <= TIME_TO_UDINT2(TR) THEN
			Y := Y_start + step2;
			state := 0;
		ELSIF in AND tx - start >= TIME_TO_UDINT2(TR) THEN
			Y := Y_start + UDINT_TO_REAL(tx - start - TIME_TO_UDINT2(TR)) * speed;
		ELSIF NOT in THEN
			state := 0;
		END_IF;
	ELSIF su THEN
		state := 1;
		start := tx;
		step2 := ss;
		speed := s1 * 1.0E-3;
		Y_start := Y;
	ELSIF sd THEN
		state := 2;
		start := tx;
		step2 := -ss;
		speed := -s1 * 1.0E-3;
		Y_start := Y;
	ELSIF fu THEN
		state := 3;
		start := tx;
		step2 := fs;
		speed := s2 * 1.0E-3;
		y_start := Y;
	ELSIF fd THEN
		state := 4;
		start := tx;
		step2 := -fs;
		speed := -s2 * 1.0E-3;
		y_start := Y;
	END_IF;
END_FUNCTION_BLOCK

