FUNCTION_BLOCK AUTORUN_Block

	VAR_INPUT
		IN :	BOOL;
		TEST :	BOOL;
		ARE :	BOOL := TRUE;
		TRUN :	TIME;
		TOFF :	TIME;
	END_VAR


	VAR_OUTPUT
		OUT :	BOOL;
		ARO :	BOOL;
	END_VAR


	VAR_IN_OUT
		ARX :	BOOL;
	END_VAR


	VAR
		timer :	_RMP_B;
		val :	BYTE;
	END_VAR

	IF TOFF > T#0s THEN
		timer(DIR:= OUT, TR := SEL(OUT, TOFF, TRUN), RMP := val);
		val := timer.RMP;
	ELSE
		val := BYTE#255;
	END_IF;

	IF (NOT ARX AND ARE AND val = BYTE#0) OR TEST THEN
		val := BYTE#0;
		ARO := TRUE;
		ARX := TRUE;
	ELSIF val = BYTE#255 AND ARO THEN
		ARO := FALSE;
		ARX := FALSE;
	END_IF;

	out := IN OR ARO;

END_FUNCTION_BLOCK

FUNCTION_BLOCK GEN_PULSE_Block

	VAR_INPUT
		ENQ :	BOOL := TRUE;
		PTH :	TIME;
		PTL :	TIME;
	END_VAR


	VAR_OUTPUT
		Q :	BOOL;
	END_VAR


	VAR
		T_PLC_MS :	T_PLC_MS_block;
		tx :	TIME;
		tn :	TIME;
		init :	BOOL;
	END_VAR

	IF enq THEN
		T_PLC_MS();
		tx:= UDINT_TO_TIME(T_PLC_MS.T_PLC_MS);
		IF NOT init THEN init := TRUE; tn := tx; END_IF;
		IF tx - tn >= SEL(Q, PTL, PTH) THEN
			tn := tn + SEL(Q, PTL, PTH);
			Q := NOT Q;
		END_IF;
	ELSE
		Q := FALSE;
		init := FALSE;
	END_IF;

END_FUNCTION_BLOCK

FUNCTION_BLOCK ACTUATOR_2P_Block

	VAR_INPUT
		IN :	BYTE;
		TEST :	BOOL;
		ARE :	BOOL := TRUE;
		CYCLE_TIME :	TIME;
		SENS :	BYTE;
		SELF_ACT_TIME :	TIME;
		SELF_ACT_PULSE :	TIME;
		SELF_ACT_CYCLES :	INT := 1;
	END_VAR

	VAR_OUTPUT
		OUT :	BOOL;
		ARO :	BOOL;
	END_VAR


	VAR_IN_OUT
		ARX :	BOOL;
	END_VAR


	VAR
		timer :	AUTORUN_Block;
		pwgen :	GEN_PULSE_Block;
	END_VAR

	timer(trun := MUL_T_AI(SELF_ACT_PULSE,2 * SELF_ACT_CYCLES), toff := SELF_ACT_TIME, Test := TEST, ARE := ARE, arx := ARX);
	ARX := timer.ARX;
	ARO := timer.ARO;

	IF aro THEN
		pwgen(PTL := SELF_ACT_PULSE, PTH := SELF_ACT_PULSE);
		out := pwgen.Q;
	ELSIF in < sens THEN
		out := FALSE;
	ELSIF BYTE_TO_USINT(in) > USINT#255 - BYTE_TO_USINT(sens) THEN
		out := TRUE;
	ELSE
		pwgen.PTH := (CYCLE_TIME * BYTE_TO_TIME2(BAND_B(IN,SENS))  ) / BYTE_TO_TIME2(BYTE#255);
		pwgen.PTL := CYCLE_TIME - pwgen.PTH;
		pwgen();
		out := pwgen.Q;
	END_IF;

END_FUNCTION_BLOCK

