	VAR_INPUT
		IN :	BYTE;
	END_VAR

	_BYTE_TO_INT := USINT_TO_INT(BYTE_TO_USINT(IN));

END_FUNCTION

FUNCTION BCDC_TO_INT:INT
	VAR_INPUT
		IN :	BYTE;
	END_VAR

	BCDC_TO_INT := _BYTE_TO_INT(in AND BYTE#16#0F) + (_BYTE_TO_INT(SHR(in,4)) * 10);
END_FUNCTION

