	rmp(dir := UP, E := E, TR := PT, RMP := out);
	out := rmp.RMP;

	IF RST THEN
		out := BYTE#0;
	ELSIF SET THEN
		out := BYTE#255;
	END_IF;

low := out = BYTE#0;
high := out = BYTE#255;
busy := NOT (low OR high) AND E;

END_FUNCTION_BLOCK

FUNCTION_BLOCK BLIND_ACTUATOR_Block

	VAR_INPUT
		UP :	BOOL;
		DN :	BOOL;
		S_IN :	BYTE;
		T_UD :	TIME := T#10s;
		T_ANGLE :	TIME := T#3s;
		T_LOCKOUT :	TIME := t#100ms;
	END_VAR


	VAR_OUTPUT
		POS :	BYTE;
		ANG :	BYTE;
		QU :	BOOL;
		QD :	BOOL;
		STATUS :	BYTE;
	END_VAR


	VAR
		position :	RMP_B_Block;
		angle :	RMP_B_Block;
		lock :	INTERLOCK_Block;
	END_VAR

	lock(i1 := UP, I2 := DN, TL := T_lockout);

	angle(e := lock.Q1 OR lock.Q2, UP := lock.Q1, PT := T_Angle);
	position(e := lock.Q1 AND angle.high OR lock.Q2 AND angle.low, up := lock.Q1, PT := T_UD);

	pos := position.Out;
	ang := angle.Out;

	QU := lock.Q1;
	QD := lock.Q2;

	IF UP AND DN THEN
		status := BYTE#1;		
	ELSIF UP THEN
		status := BYTE#121;
	ELSIF DN THEN
		status := BYTE#122;
	ELSE
		status := S_IN;
	END_IF;

END_FUNCTION_BLOCK

