FUNCTION_BLOCK T_PLC_MS_block
	VAR_OUTPUT
		T_PLC_MS :	UDINT;
	END_VAR

	VAR_EXTERNAL
		PLC_TICKS_PER_SEC :	INT;
		PLC_SYS_TICK_CNT :	DINT;
	END_VAR

	VAR
		debug :	BOOL;(*Debug-Mode ON / OFF*)
		N :	INT;(*Debug-Faktor*)
		Offset :	UDINT;(*Debug-Offset*)
		temp :	DWORD := DWORD#1;(*Debug-Offset*)
		mode :	BOOL;(*modus*)
		faktor :	UDINT;(*Systemtakt-Faktor*)
		init :	BOOL;
		v_plc_ticks_per_sec :	UDINT;
		base :	UDINT := UDINT#1000;
	END_VAR


	IF init = FALSE THEN
		v_plc_ticks_per_sec := INT_TO_UDINT(PLC_TICKS_PER_SEC);
		IF v_plc_ticks_per_sec = UDINT#1024 THEN
			faktor := UDINT#1;
			mode := FALSE;
		ELSIF v_plc_ticks_per_sec > UDINT#0 THEN
			IF v_plc_ticks_per_sec <= base THEN
				faktor := base / v_plc_ticks_per_sec;
				mode := FALSE;
			ELSE
				faktor := v_plc_ticks_per_sec / base;
				mode := TRUE;
			END_IF;
		ELSE
			faktor := UDINT#1;
		END_IF;
		init := TRUE;
	END_IF;

	IF mode THEN
		T_PLC_MS := DINT_TO_UDINT(PLC_SYS_TICK_CNT) / faktor;
	ELSE
		T_PLC_MS := DINT_TO_UDINT(PLC_SYS_TICK_CNT) * faktor;
	END_IF;

	IF debug THEN
		T_PLC_MS := (DWORD_TO_UDINT(SHL(UDINT_TO_DWORD(T_PLC_MS),N) OR SHL(temp,N)) - UDINT#1) + Offset;
	END_IF;
END_FUNCTION_BLOCK

FUNCTION TIME_TO_UDINT2:UDINT
	VAR_INPUT
		X :	TIME;
	END_VAR

	TIME_TO_UDINT2 := DINT_TO_UDINT(TIME_TO_DINT(X));
END_FUNCTION

FUNCTION FRMP_B:BYTE
	VAR_INPUT
		START :	BYTE;
		DIR :	BOOL;
		TD :	TIME;
		TR :	TIME;
	END_VAR

	IF TD < TR THEN
		FRMP_B := MIN(UDINT_TO_BYTE(DWORD_TO_UDINT(SHL(TIME_TO_DWORD(TD), 8)) / TIME_TO_UDINT2(TR)), SEL(DIR, START, USINT_TO_BYTE(USINT#255 - BYTE_TO_USINT(START))));
		IF DIR THEN
			FRMP_B := USINT_TO_BYTE(BYTE_TO_USINT(START) + BYTE_TO_USINT(FRMP_B));
		ELSE
			FRMP_B := USINT_TO_BYTE(BYTE_TO_USINT(START) - BYTE_TO_USINT(FRMP_B));
		END_IF;
	ELSE
		FRMP_B := SEL(DIR, BYTE#0, BYTE#255);
	END_IF;
END_FUNCTION

FUNCTION_BLOCK _RMP_B
	VAR_INPUT
		DIR :	BOOL;
		E :	BOOL := TRUE;
		TR :	TIME;
	END_VAR


	VAR_IN_OUT
		RMP :	BYTE;
	END_VAR


	VAR
		T_PLC_MS :	T_PLC_MS_block;
		tx :	TIME;
		tl :	TIME;
		tn :	TIME;
		init :	BOOL;
		last_dir :	BOOL;
		start :	BYTE;
	END_VAR


	T_PLC_MS();
	tx := UDINT_TO_TIME(T_PLC_MS.T_PLC_MS);

	IF E AND init AND (dir = last_dir) AND (RMP <> SEL(DIR, BYTE#0, BYTE#255)) AND TR = tn THEN
		RMP := FRMP_B(start, DIR, tx - tl, TR);
	ELSE
		init := TRUE;
		tl := tx;
		tn := tr;
		start := RMP;
	END_IF;
	last_dir := dir;
END_FUNCTION_BLOCK


FUNCTION_BLOCK TREND_DW
	VAR_INPUT
		X :	DWORD;
	END_VAR
	VAR_OUTPUT
		Q :	BOOL;
		TU :	BOOL;
		TD :	BOOL;
		D :	DWORD;
	END_VAR

	VAR
		LAST_X :	DWORD;
	END_VAR

	IF X > last_X THEN
		TU := TRUE;
		TD := FALSE;
		D := UDINT_TO_DWORD(DWORD_TO_UDINT(X) - DWORD_TO_UDINT(last_X));
		Q := TRUE;
	ELSIF X < last_X THEN
		TD := TRUE;
		TU := FALSE;
		D := UDINT_TO_DWORD(DWORD_TO_UDINT(last_X) - DWORD_TO_UDINT(X));
		Q := FALSE;
	ELSE
		TU := FALSE;
		TD := FALSE;
		D := DWORD#0;
	END_IF;
	last_X := X;
END_FUNCTION_BLOCK

FUNCTION_BLOCK _RMP_NEXT
	VAR_INPUT
		E :	BOOL := TRUE;
		IN :	BYTE;
		TR :	TIME;
		TF :	TIME;
		TL :	TIME;
	END_VAR

	VAR_OUTPUT
		DIR :	BOOL;
		UP :	BOOL;
		DN :	BOOL;
	END_VAR

	VAR_IN_OUT
		OUT :	BYTE;
	END_VAR
	VAR
		rmx :	_RMP_B;
		dirx :	TREND_DW;
		t_lock :	TP;
		xen :	BOOL;
		xdir :	BOOL;
	END_VAR

	dirx(X := BYTE_TO_DWORD(in));

	t_lock(in := FALSE, pt := TL);

	IF dirx.TU AND (OUT < IN) THEN
		IF NOT xdir AND xen THEN t_lock(in := TRUE); END_IF;
		xen := TRUE;
		xdir := TRUE;
	ELSIF dirx.TD AND (OUT > IN) THEN
		IF xdir AND xen THEN t_lock(in := TRUE); END_IF;
		xen := TRUE;
		xdir := FALSE;
	ELSIF xen THEN
		IF (xdir AND (out >= in)) OR (NOT xdir AND (out <= in)) THEN
			xen := FALSE;
			IF tl > t#0s THEN t_lock(IN := TRUE); END_IF;
		END_IF;
	END_IF;

	IF NOT t_lock.Q AND xen THEN
		UP := XDIR;
		DIR := XDIR;
		DN := NOT XDIR;
	ELSE
		UP := FALSE;
		DN := FALSE;
	END_IF;

	rmx(rmp := OUT, E := E AND (UP OR DN) , dir := DIR, tr := SEL(dir, TF, TR));
	OUT := rmx.RMP;
END_FUNCTION_BLOCK

