FUNCTION_BLOCK BLIND_INPUT_Block

	VAR_INPUT
		POS :	BYTE;
		ANG :	BYTE;
		S1 :	BOOL;
		S2 :	BOOL;
		IN :	BOOL;
		PI :	BYTE;
		AI :	BYTE;
		SINGLE_SWITCH :	BOOL;
		CLICK_EN :	BOOL := TRUE;
		CLICK_TIME :	TIME := T#500ms;
		MAX_RUNTIME :	TIME := T#60s;
		MANUAL_TIMEOUT :	TIME := T#1h;
		DEBOUNCE_TIME :	TIME := T#20ms;
		DBL_CLK1 :	BOOL := FALSE;
		DBL_POS1 :	BYTE;
		DBL_ANG1 :	BYTE;
		DBL_CLK2 :	BOOL := FALSE;
		DBL_POS2 :	BYTE := BYTE#255;
		DBL_ANG2 :	BYTE := BYTE#255;
		D1_TOGGLE :	BOOL := TRUE;
		D2_TOGGLE :	BOOL := TRUE;
		MASTER_MODE :	BOOL;
	END_VAR


	VAR_OUTPUT
		QU :	BOOL := TRUE;
		QD :	BOOL := TRUE;
		STATUS :	BYTE;
		PO :	BYTE := BYTE#255;
		AO :	BYTE := BYTE#255;
		D1 :	BOOL;
		D2 :	BOOL;
	END_VAR


	VAR
		s1e :	TOF;
		s2e :	TOF;
		s1d :	CLICK_MODE_Block;
		s2d :	CLICK_MODE_Block;
		dir :	BOOL;
		tx :	TIME;
		last :	TIME;
		T_PLC_MS :	T_PLC_MS_Block;
	END_VAR

	T_PLC_MS();
	tx:= UDINT_TO_TIME(T_PLC_MS.T_PLC_MS);

	s1e(in := S1, pt := DEBOUNCE_TIME);
	s2e(in := S2, pt := DEBOUNCE_TIME);
	s1d(in := (s1e.Q AND NOT SINGLE_SWITCH) OR (s1e.Q AND SINGLE_SWITCH AND dir), t_long := CLICK_TIME);
	s2d(in := (s2e.Q AND NOT SINGLE_SWITCH) OR (s1e.Q AND SINGLE_SWITCH AND NOT dir), t_long := CLICK_TIME);

	IF NOT d1_toggle THEN d1 := FALSE; END_IF;
	IF NOT d2_toggle THEN d2 := FALSE; END_IF;

	IF (s1d.LONG AND s2d.LONG) OR (status = BYTE#139) THEN
	status := BYTE#139;
	IF NOT (s1d.LONG OR s2d.LONG)  THEN status := BYTE#130; END_IF;
	ELSIF s1d.tp_LONG THEN
		status := BYTE#132;
	ELSIF s2d.tp_LONG THEN
		status := BYTE#133;
	ELSIF  s1d.SINGLE THEN
		IF click_en THEN
			IF QU XOR QD THEN
				status := BYTE#131;
			ELSE
				status := BYTE#134;
				last := tx;
				dir := NOT dir;
			END_IF;
		END_IF;
	ELSIF  s2d.SINGLE THEN
		IF click_en THEN
			IF QU XOR QD THEN
				status := BYTE#131;
			ELSE
				status := BYTE#135;
				last := tx;
				dir := NOT dir;
			END_IF;
		END_IF;
	ELSIF in THEN
		status := BYTE#136;
		last := tx;
	ELSIF s1d.DOUBLE THEN
		IF dbl_clk1 THEN
			status := BYTE#137;
			last := tx;
		ELSE
			D1 := NOT D1;
		END_IF;
	ELSIF s2d.DOUBLE THEN
		IF dbl_clk2 THEN
			status := BYTE#138;
			last := tx;
		ELSE
			IF single_switch THEN D1 := NOT D1; ELSE D2 := NOT D2; END_IF;
		END_IF;
	END_IF;

	CASE _BYTE_TO_INT(status) OF
		0:		
				status := BYTE#130;

		130:	
				IF NOT master_mode THEN
					PO := POS;
					AO := ANG;
				END_IF;
				QU := TRUE;
				QD := TRUE;

		131:	
				QU := FALSE;
				QD := FALSE;
				PO := POS;
				AO := ANG;
				IF tx - last >= manual_timeout THEN
					status := BYTE#130;
				END_IF;

		132:	
				QU := TRUE;
				QD := FALSE;
				PO := POS; AO := ANG;
				last := tx;
				IF NOT s1d.LONG THEN status := BYTE#131; dir := NOT dir; END_IF;

		133:	
				QU := FALSE;
				QD := TRUE;
				PO := POS; AO := ANG;
				last := tx;
				IF NOT s2d.LONG THEN	status := BYTE#131; dir := NOT dir; END_IF;

		134:
				QU := TRUE;
				QD := FALSE;
				PO := POS; AO := ANG;
				IF tx - last >= max_runtime THEN status := BYTE#131; END_IF;

		135:	
				QU := FALSE;
				QD := TRUE;
				PO := POS; AO := ANG;
				IF tx - last >= max_runtime THEN status := BYTE#131;	END_IF;

		136:	
				QU := TRUE;
				QD := TRUE;
				PO := PI; AO := AI;
				IF tx-last >= max_runtime THEN status := BYTE#130; END_IF;

		137:
				QU := TRUE;
				QD := TRUE;
				PO := DBL_POS1;
				AO := DBL_ANG1;
				IF tx - last >= max_runtime THEN status := BYTE#131; END_IF;

		138:	
				QU := TRUE;
				QD := TRUE;
				PO := DBL_POS2;
				AO := DBL_ANG2;
				IF tx - last >= max_runtime THEN status := BYTE#131; END_IF;

		139:
				QU := FALSE;
				QD := FALSE;
				PO := POS;
				AO := ANG;

	END_CASE;

END_FUNCTION_BLOCK

