		QD :	BOOL;
		STATUS :	BYTE;
		PO :	BYTE;
		AO :	BYTE;
	END_VAR


	VAR
		x :	INT;
	END_VAR


	VAR RETAIN 
		sx :	oscat_blind_scene_array;
	END_VAR

	x := _BYTE_TO_INT(scene AND BYTE#2#0000_1111);

	IF enable AND (sx[x][2] > BYTE#0) AND UP AND DN THEN
		po := sx[x][0];
		ao := sx[x][1];
		status := INT_TO_BYTE(160 + x);  
		QU := TRUE;
		QD := TRUE;
	ELSE
		QU := UP;
		QD := DN;
		status := S_IN;
		po := pi;
		ao := ai;
	END_IF;

	IF swrite THEN
		status := BYTE#176;	
		sx[x][0] := pi;
		sx[x][1] := ai;
		IF enable THEN sx[x][2] := BYTE#1; ELSE sx[x][2] := BYTE#0; END_IF; 
	END_IF;

