FUNCTION_BLOCK BUFFER_SEARCH_Block
	VAR_INPUT
		SIZE :	UINT;
		STR :	STRING;
		POS :	INT;
		IGN :	BOOL;
	END_VAR

	VAR_IN_OUT
		PT :	oscat_arb_0_249;
	END_VAR

	VAR_OUTPUT
		BUFFER_SEARCH :	INT;
	END_VAR

	VAR
		i :	INT;
		end :	INT;
		k :	INT;
		k2 :	INT;
		lx :	INT;
		char :	BYTE;
		chx :	BYTE;
	END_VAR

	lx := LEN(str);
	IF pos >= 0 AND lx > 0 THEN 
		end := UINT_TO_INT(size) - lx;
		lx := lx - 1;
		FOR i := pos TO end DO
			FOR k := 0 TO lx DO
				char := INT_TO_BYTE(GET_CHAR(str,k + 1));
				k2 := i + k;
				IF IGN THEN
					chx := TO_UPPER(pt[k2]);
				ELSE
					chx := pt[k2];
				END_IF;
				IF char <> chx THEN EXIT; END_IF;
			END_FOR;
			IF k > lx THEN
				BUFFER_SEARCH := i;
				RETURN;
			END_IF;
		END_FOR;
	END_IF;
	BUFFER_SEARCH := -1;
END_FUNCTION_BLOCK

