TYPE oscat_complex :
  STRUCT
	re : REAL;
	im : REAL;
  END_STRUCT;
END_TYPE

FUNCTION_BLOCK CINV_Block

	VAR_INPUT
		X :	oscat_complex;
	END_VAR

	VAR_OUTPUT
		CINV :	oscat_complex;
	END_VAR

	VAR
		temp :	REAL;
	END_VAR

	temp := X.re * X.re + X.im * X.im;
	IF temp = 0.0 THEN CINV.re := 0.0;CINV.im := 0.0;RETURN;END_IF;
	CINV.re := X.re / temp;
	CINV.im := -X.im / temp;

