FUNCTION_BLOCK T_PLC_MS_block
	VAR_OUTPUT
		T_PLC_MS :	UDINT;
	END_VAR

	VAR_EXTERNAL
		PLC_TICKS_PER_SEC :	INT;
		PLC_SYS_TICK_CNT :	DINT;
	END_VAR

	VAR
		debug :	BOOL;(*Debug-Mode ON / OFF*)
		N :	INT;(*Debug-Faktor*)
		Offset :	UDINT;(*Debug-Offset*)
		temp :	DWORD := DWORD#1;(*Debug-Offset*)
		mode :	BOOL;(*modus*)
		faktor :	UDINT;(*Systemtakt-Faktor*)
		init :	BOOL;
		v_plc_ticks_per_sec :	UDINT;
		base :	UDINT := UDINT#1000;
	END_VAR


	IF init = FALSE THEN
		v_plc_ticks_per_sec := INT_TO_UDINT(PLC_TICKS_PER_SEC);
		IF v_plc_ticks_per_sec = UDINT#1024 THEN
			faktor := UDINT#1;
			mode := FALSE;
		ELSIF v_plc_ticks_per_sec > UDINT#0 THEN
			IF v_plc_ticks_per_sec <= base THEN
				faktor := base / v_plc_ticks_per_sec;
				mode := FALSE;
			ELSE
				faktor := v_plc_ticks_per_sec / base;
				mode := TRUE;
			END_IF;
		ELSE
			faktor := UDINT#1;
		END_IF;
		init := TRUE;
	END_IF;

	IF mode THEN
		T_PLC_MS := DINT_TO_UDINT(PLC_SYS_TICK_CNT) / faktor;
	ELSE
		T_PLC_MS := DINT_TO_UDINT(PLC_SYS_TICK_CNT) * faktor;
	END_IF;

	IF debug THEN
		T_PLC_MS := (DWORD_TO_UDINT(SHL(UDINT_TO_DWORD(T_PLC_MS),N) OR SHL(temp,N)) - UDINT#1) + Offset;
	END_IF;

END_FUNCTION_BLOCK

FUNCTION_BLOCK CLICK_Block

	VAR_INPUT
		IN :	BOOL;
		T_DEBOUNCE :	TIME := T#10ms;
		T_SHORT :	TIME := T#200ms;
		T_PAUSE :	TIME := T#500ms;
		T_RECONFIG :	TIME := T#1m;
	END_VAR


	VAR_OUTPUT
		Q :	BOOL;
		SINGLE :	BOOL;
		DOUBLE :	BOOL;
		TRIPLE :	BOOL;
		STATUS :	BYTE;
	END_VAR


	VAR
		s_in :	SW_RECONFIG_Block;
		tx :	TIME;
		state :	INT;
		last :	TIME;
		T_PLC_MS :	T_PLC_MS_Block;
	END_VAR

	s_in(in := in, TD := T_debounce, TR := T_reconfig);

	T_PLC_MS();
	tx:= UDINT_TO_TIME(T_PLC_MS.T_PLC_MS);

	IF s_in.Q XOR Q THEN
		last := tx;
		IF s_in.Q THEN state := state + 1; END_IF;
	END_IF;
	Q := s_in.Q;

	IF state > 0 THEN
		IF (Q AND tx - last > t_short) OR (NOT Q AND tx - last > t_pause) THEN
			CASE state OF
				1:	single := TRUE;
					status := BYTE#111;
				2:	double := TRUE;
					status := BYTE#112;
				3:	triple := TRUE;
					status := BYTE#113;
			END_CASE;
			state := 0;
		END_IF;
	ELSIF NOT q THEN
		single := FALSE;
		double := FALSE;
		triple := FALSE;
		status := BYTE#110;
		last := tx;
		state := 0;
	END_IF;

END_FUNCTION_BLOCK

