FUNCTION_BLOCK CLK_PULSE
	VAR_INPUT
		PT :	TIME;
		N :	INT;
		RST :	BOOL;
	END_VAR

	VAR_OUTPUT
		Q :	BOOL;
		CNT :	INT;
