END_FUNCTION

FUNCTION CMP:BOOL
	VAR_INPUT
		X :	REAL;
		Y :	REAL;
		N :	INT;
	END_VAR

	VAR
		tmp :	REAL;
	END_VAR

	tmp := ABS(x);
	IF tmp > 0.0 THEN
		tmp := EXP10(INT_TO_REAL(FLOOR(LOG(tmp))-N+1));
	ELSE
		tmp := EXP10(tmp);
	END_IF;
	CMP := ABS(X - Y) < tmp;

END_FUNCTION

