		diff :	FT_DERIV;
	END_VAR

	IF rst THEN
		piwl(rst := TRUE);
		piwl.RST := FALSE;
	ELSE
		IF TN = 0.0 THEN
			piwl(in := IN * KP, KP := 1.0, KI := 0.0, LIM_L := LIM_L, LIM_H := LIM_H);
		ELSE
			piwl(in := IN * KP, KP := 1.0, KI := 1.0 / TN, LIM_L := LIM_L, LIM_H := LIM_H);
		END_IF;

		diff(IN := IN, K := KP * TV);
		Y := piwl.Y + diff.out;

		IF Y < LIM_L THEN
			LIM := TRUE;
			Y := LIM_L;
		ELSIF Y > LIM_H THEN
			LIM := TRUE;
			Y := LIM_H;
		ELSE
			LIM := FALSE;
		END_IF;
	END_IF;
END_FUNCTION_BLOCK

FUNCTION_BLOCK CTRL_OUT
	VAR_INPUT
		CI :	REAL;
		OFFSET :	REAL;
		MAN_IN :	REAL;
		LIM_L :	REAL;
		LIM_H :	REAL;
		MANUAL :	BOOL;
	END_VAR

	VAR_OUTPUT
		Y :	REAL;
		LIM :	BOOL;
	END_VAR

	Y := SEL(manual, CI, MAN_IN) + OFFSET;

	IF Y >= LIM_H THEN
		Y := LIM_H;
		LIM := TRUE;
	ELSIF Y <= lim_L THEN
		Y := LIM_L;
		LIM := TRUE;
	ELSE
		LIM := FALSE;
	END_IF;
END_FUNCTION_BLOCK

FUNCTION DEAD_ZONE:REAL

	VAR_INPUT
		X :	REAL;
		L :	REAL;
	END_VAR

	IF ABS(x) > L THEN
		dead_zone := X;
	ELSE
		DEAD_ZONE := 0.0;
	END_IF;

