FUNCTION_BLOCK CYCLE_TIME
	VAR_INPUT
		RST :	BOOL;
	END_VAR

	VAR_OUTPUT
		CT_MIN :	TIME := t#0s;
		CT_MAX :	TIME := t#0s;
		CT_LAST :	TIME;
		SYSTIME :	TIME;
		SYSDAYS :	INT;
		CYCLES :	DWORD;
	END_VAR

	VAR
		last_cycle :	TIME;
		tx :	TIME;
		init :	BOOL;
		T_PLC_MS :	T_PLC_MS_block;
	END_VAR

	T_PLC_MS();
	tx:= UDINT_TO_TIME(T_PLC_MS.T_PLC_MS) - last_cycle;

	IF rst THEN
		ct_min := t#10h;
		ct_max := t#0ms;
		cycles := DWORD#0;
	ELSIF last_cycle > t#0s THEN
		IF tx < ct_min THEN ct_min := tx;
		ELSIF tx > ct_max THEN ct_max := tx;
		END_IF;
		ct_last := tx;
	ELSIF ct_min = t#0s THEN
		ct_min := t#0s - t#1ms;
	END_IF;
	IF init THEN
		systime := systime + tx;
			IF systime >= t#1d THEN
				systime := systime - t#1d;
				sysdays := sysdays + 1;
			END_IF;
	END_IF;
	init := TRUE;
	last_cycle := last_cycle + tx;
	cycles := UDINT_TO_DWORD(DWORD_TO_UDINT(cycles) + UDINT#1);

END_FUNCTION_BLOCK

