FUNCTION_BLOCK DEC_TO_BYTE_Block
	VAR_INPUT
		DEC :	STRING;
	END_VAR

	VAR_OUTPUT
		DEC_TO_BYTE :	BYTE;
	END_VAR

	VAR
		i :	INT;
		X :	INT;
		stop :	INT;
	END_VAR

	DEC_TO_BYTE := BYTE#0;
	stop := LEN(DEC);
	FOR I := 1 TO stop DO
		X := GET_CHAR(DEC,I);
		IF X > 47 AND X < 58 THEN
			DEC_TO_BYTE := INT_TO_BYTE(_BYTE_TO_INT(DEC_TO_BYTE) * 10 + X - 48);
