		CX :	STRING;
	END_VAR

	VAR_OUTPUT
		DEL_CHARS :	STRING;
	END_VAR

	VAR
		pos :	INT;
		stop :	INT;
		char :	STRING;
	END_VAR

	DEL_CHARS := IN;
	stop := LEN(in);
	pos := 1;
	WHILE pos <= stop DO
		char := MID(DEL_CHARS, 1, pos);
		IF FIND(cx,char) > 0 THEN
			DEL_CHARS := DELETE(DEL_CHARS, 1, pos);
			stop := stop - 1;	
		ELSE
			pos := pos + 1;
		END_IF;
	END_WHILE;

END_FUNCTION_BLOCK

