FUNCTION_BLOCK FF_RSE
	VAR_INPUT
		CS :	BOOL;
		CR :	BOOL;
		RST :	BOOL;
	END_VAR

	VAR_OUTPUT
		Q :	BOOL;
	END_VAR

	VAR
		es :	BOOL;
		er :	BOOL;
	END_VAR

	IF rst THEN
		(* asynchronous reset *)
		Q := FALSE;
	ELSIF CR AND NOT er THEN
		(* rising edge on CR *)
		Q := FALSE;
	ELSIF CS AND NOT es THEN
		(* rising edge on CS *)
		Q := TRUE;
	END_IF;

	es := CS;
	er := CR;
END_FUNCTION_BLOCK

