		buffer :	oscat_ardw_0_31;
		i :	INT;
		tmp :	INT;
	END_VAR

	N := MIN(N, UINT#32);

	(* startup initialisation *)
	IF NOT init OR rst OR N = UINT#0 THEN
		init := TRUE;
		tmp := UINT_TO_INT(N)-1;
