		tmp := UINT_TO_INT(N);
		i := INC1(i, tmp);
		Y := UDINT_TO_DWORD(DWORD_TO_UDINT(Y) + (DWORD_TO_UDINT(X) - DWORD_TO_UDINT(buffer[i])) / UINT_TO_UDINT(N));
		buffer[i] := X;
	END_IF;

