	END_VAR

	VAR
		init :	BOOL;
		buffer :	oscat_arr_0_15;
		i :	INT;
		n :	INT;
	END_VAR

	IF NOT init OR rst THEN
		init := TRUE;
		FOR i := 0 TO 15 DO
			buffer[i] := X;
		END_FOR;
		i := 15;
		Y := X;
	ELSE
		i := INC1(i, 16);
