	func_block.ICE :=ICE ;
	func_block.DIAG:=DIAG;
	func_block.ENQ :=ENQ ;
	func_block.RST :=RST ;
	func_block.TD_WAIT:=TD_WAIT;
	func_block.TD_S   :=TD_S   ;
	func_block.TD_0   :=TD_0   ;
	func_block();
	QS    := func_block.QS    ;
	Q0    := func_block.Q0    ;
	Q1    := func_block.Q1    ;
	Q2    := func_block.Q2    ;
	Q3    := func_block.Q3    ;
	ERROR := func_block.ERROR ;
	STATUS:= func_block.STATUS;


