    LocalVar0 : BYTE;
	LocalVar1 : BOOL;
	LocalVar2 : TIME;
	LocalVar3 : TIME;
    LocalOUT  : BYTE;
  END_VAR

  LocalOUT := FRMP_B(LocalVar0, LocalVar1, LocalVar2,LocalVar3);
END_PROGRAM

