  VAR
	IN  :	REAL;
	K   :	REAL;
	RUN :	BOOL;

	OUT :	REAL;

	func_block : FT_DERIV;
  END_VAR
	func_block.IN :=IN ;
	func_block.K  :=K  ;
	func_block.RUN:=RUN;
	func_block();
	OUT := func_block.OUT;
END_PROGRAM


