	END_VAR

	VAR_OUTPUT
		Y :	REAL;
		LIM :	BOOL;
	END_VAR

	VAR
		integ :	FT_INT_Block;
	END_VAR

	integ(IN := IN, K := KI, RUN := NOT LIM, RST := RST);

	(* set output value *)
	Y := KP * IN + integ.Out;

	(* check for limits *)
	IF Y < LIM_L THEN
		Y := LIM_L;
		LIM := TRUE;
	ELSIF Y > LIM_H THEN
		Y := LIM_H;
		LIM := TRUE;
	ELSE
		LIM := FALSE;
	END_IF;

END_FUNCTION_BLOCK

