	Y :	REAL;
	LIM :	BOOL;

	func_block : FT_PIWL;
  END_VAR
	func_block.IN    :=IN   ;
	func_block.KP    :=KP   ;
	func_block.KI    :=KI   ;
	func_block.LIM_L :=LIM_L;
	func_block.LIM_H :=LIM_H;
