FUNCTION_BLOCK FT_RMP

	VAR_INPUT
		RMP :	BOOL := TRUE;
		IN :	REAL;
		KR :	REAL;
		KF :	REAL;
	END_VAR

	VAR_OUTPUT
		OUT :	REAL;
		BUSY :	BOOL;
		UD :	BOOL;
	END_VAR

	VAR
		tx :	TIME;
		last :	TIME;
		init :	BOOL;
		T_PLC_MS :	T_PLC_MS_block;
	END_VAR

	T_PLC_MS();
	tx:= UDINT_TO_TIME(T_PLC_MS.T_PLC_MS) - last;

	IF NOT init THEN
		init := TRUE;
		last := tx;
		tx := t#0s;
		out := in;
	END_IF;
	IF NOT rmp THEN
		out := in;
		busy := FALSE;
	ELSIF out > in THEN
		(* ramp down *)
		out := out - TIME_TO_REAL(tx) * 0.001 * KF;
		out := MAX(in, out);
	ELSIF out < in THEN
		(* ramp up *)
		out := out + TIME_TO_REAL(tx) * 0.001 * KR;
		out := MIN(in, out);
	END_IF;

	(* set busy and dir flags *)
	IF out < in THEN
		busy := TRUE;
		ud := TRUE;
	ELSIF out > in THEN
		busy := TRUE;
		ud := FALSE;
	ELSE
		busy := FALSE;
	END_IF;
	last := last + tx;

END_FUNCTION_BLOCK

