		SECONDS := UDINT#0;
		CYCLES := UDINT#0;
		last := tx;
		ms := UDINT#0;
	ELSIF IN THEN
		(* add the current milliseconds *)
		ms := (tx - last) + ms;
		IF ms >= UDINT#1000 THEN
			seconds := seconds + UDINT#1;
			ms := ms - UDINT#1000;
		END_IF;
		cycles := cycles + BOOL_TO_UDINT(NOT edge);
	END_IF;
	last := tx;
	edge := in;

