	VAR_IN_OUT
		ONTIME :	UDINT;
		CYCLES :	UDINT;
	END_VAR


	VAR
		runtime :	ONTIME_Block;
	END_VAR

	runtime(in := switch, SECONDS := ONTIME , CYCLES := CYCLES);
	CYCLES := runtime.CYCLES;
	ONTIME := runtime.SECONDS;

	IF RST THEN
		ONTIME := UDINT#0;
		CYCLES := UDINT#0;
	END_IF;
	IF SWITCH THEN
		IF ontime < UINT_TO_UDINT(T_NO_DIMM) * UDINT#3600 THEN
			LAMP := BYTE#255;
			STATUS := BYTE#111;
		ELSE
			LAMP := DIMM;
			STATUS := BYTE#112;
		END_IF;
	ELSE
		LAMP := BYTE#0;
		STATUS := BYTE#110;
	END_IF;

	IF ontime >= UINT_TO_UDINT(T_maintenance) * UDINT#3600 AND T_Maintenance > UINT#0 THEN
		STATUS := BYTE#120;
	END_IF;

END_FUNCTION_BLOCK

