		tx := t#0s;
	END_IF;

	IF tx >= pt THEN
		last := last + pt;
		tx := tx - pt;
	END_IF;

	ltemp := temp;
	IF pt > t#0s THEN temp := fract(TIME_TO_REAL1(tx + multime(pt, dl)) / TIME_TO_REAL1(pt)); END_IF;
	out := am * temp + os;

	Q := temp < ltemp;

