		ix :	REAL;
		val :	REAL2;
		R2_ADD :	R2_ADD_Block;
		R2_SET :	R2_SET_Block;
	END_VAR

	IF RST THEN
		R2_SET(X:=0.0);
		val:=R2_SET.R2_SET;
		out := 0.0;
	ELSE
		integ(X := IN, E := RUN, K := K, Y := ix);
		ix := integ.Y;
		R2_ADD(X:=val,Y:=ix);
		val:=R2_ADD.R2_ADD;
		ix := 0.0;
		OUT := val.RX;
	END_IF;

	(* check output for limits *)
	IF out > OUT_MIN AND out < OUT_MAX THEN
		LIM := FALSE;
	ELSE
		OUT := LIMIT(OUT_MIN, OUT, OUT_MAX);
		R2_SET(X:=OUT);
		val:=R2_SET.R2_SET;
		LIM := TRUE;
	END_IF;

END_FUNCTION_BLOCK

FUNCTION WATER_DENSITY:REAL

    VAR_INPUT
        T :	REAL;
        SAT :	BOOL;
    END_VAR


    VAR
        T2 :	REAL;
        T4 :	REAL;
    END_VAR

    T2 := T * T;
    T4 := T2 * T2;
    WATER_DENSITY := (999.83952 + 16.952577*T + -7.9905127E-3*T2 + -4.6241757E-5*T2*T + 1.0584601E-7*T4 + -2.8103006E-10*T4*T) / (1.0 + 0.0168872*T);
    IF sat THEN WATER_DENSITY := WATER_DENSITY - 0.004612 + 0.000106 * T; END_IF;

END_FUNCTION

FUNCTION TIME_TO_UDINT2:UDINT
	VAR_INPUT
		X :	TIME;
	END_VAR

	TIME_TO_UDINT2 := DINT_TO_UDINT(TIME_TO_DINT(X));
END_FUNCTION

FUNCTION_BLOCK HEAT_METER_Block

	VAR_INPUT
		TF :	REAL;
		TR :	REAL;
		LPH :	REAL;
		E :	BOOL;
		RST :	BOOL;
		CP :	REAL;
		DENSITY :	REAL;
		CONTENT :	REAL;
		PULSE_MODE :	BOOL;
		RETURN_METER :	BOOL;
		AVG_TIME :	TIME := T#5s;
	END_VAR


	VAR_OUTPUT
		C :	REAL;
	END_VAR


	VAR_IN_OUT
		Y :	REAL;
	END_VAR


	VAR
		tx :	UDINT;
		last :	UDINT;
		int1 :	FT_INT2_Block;
		edge :	BOOL;
		x :	REAL;
		init :	BOOL;
		Y_last :	REAL;
		T_PLC_MS :	T_PLC_MS_Block;
		WATER_ENTHALPY :	WATER_ENTHALPY_Block;
		wa_TF :	REAL;
		wa_TR :	REAL;
	END_VAR

	IF rst THEN
		int1(rst := TRUE);
		int1.rst := FALSE;
		C := 0.0;
		Y := 0.0;
	ELSIF e THEN
		water_enthalpy(T:=TF);
		wa_TF:=water_enthalpy.Result;

		water_enthalpy(T:=TR);
		wa_TR:=water_enthalpy.Result;

		X := (WATER_DENSITY(SEL(return_meter, TF, TR), FALSE) * (wa_TF - wa_TR) * (1.0 - content) + CP * Density * content * (TF-TR));
	END_IF;

	int1(run := NOT pulse_mode AND e, in := X * LPH * 2.77777777777E-4);
	IF pulse_mode THEN
		IF NOT edge AND E THEN Y := Y + X * LPH; END_IF;
	ELSE
		Y := int1.Out;
	END_IF;

	edge := e;

	T_PLC_MS();
	tx:= T_PLC_MS.T_PLC_MS;

	IF NOT init THEN
		init := TRUE;
		last := tx;
	END_IF;

	IF (tx - last >= TIME_TO_UDINT2(AVG_TIME)) AND (avg_time > T#0s) THEN
		last := tx;
		C := (Y - Y_last) * 3.6E12 / TIME_TO_REAL(AVG_TIME);
		Y_last := Y;
	END_IF;

END_FUNCTION_BLOCK

