FUNCTION_BLOCK HTML_DECODE

	VAR_INPUT
		IN :	oscat_STRING250;
	END_VAR


	VAR_OUTPUT
		HTML_DECODE :	oscat_STRING250;
	END_VAR


	VAR
		pos :	INT;
		end :	INT;
		tmp :	oscat_STRING10;
		code :	BYTE;
		size :	INT;
		CHR_TO_STRING :	CHR_TO_STRING;
		CHARCODE :	CHARCODE;
		HEX_TO_DWORD :	HEX_TO_DWORD;
		FINDP :	FINDP;
	END_VAR

	HTML_DECODE := IN;

	pos := FIND(HTML_DECODE, '&');
	WHILE pos > 0 DO
		tmp := MID(HTML_DECODE, 2, pos + 1);
		IF EQ_STRING(tmp,'#x') OR EQ_STRING(tmp,'#X') THEN

			IF pos+13 > LEN(HTML_DECODE) THEN
			size := LEN(HTML_DECODE) - pos - 2;
			ELSE
			size := 10;
			END_IF; 

			tmp := MID(HTML_DECODE, size, pos + 3);
			end := FIND(tmp, ';');
			HEX_TO_DWORD(Hex:=LEFT(tmp, end - 1));
			CODE := DWORD_TO_BYTE(HEX_TO_DWORD.HEX_TO_DWORD);
			CHR_TO_STRING(C:=CODE);
			HTML_DECODE := REPLACE(HTML_DECODE, CHR_TO_STRING.CHR_TO_STRING, end + 3, pos);
		ELSE
			tmp := LEFT(tmp,1);
			IF EQ_STRING(tmp,'#') THEN

				IF pos+12 > LEN(HTML_DECODE) THEN
					size := LEN(HTML_DECODE) - pos - 1;
				ELSE
					size := 10;
				END_IF; 

				tmp := MID(HTML_DECODE, size, pos + 2);
				end := FIND(tmp, ';');
				tmp := LEFT(tmp, end - 1);
				CODE := INT_TO_BYTE(STRING_TO_INT(tmp));
				CHR_TO_STRING(C:=CODE);
				HTML_DECODE := REPLACE(HTML_DECODE, CHR_TO_STRING.CHR_TO_STRING, end + 2, pos);
			ELSE
				IF pos+11 > LEN(HTML_DECODE) THEN
					size := LEN(HTML_DECODE) - pos ;
				ELSE
					size := 10;
				END_IF; 

				tmp := MID(HTML_DECODE, size, pos + 1);
				end := FIND(tmp, ';');
				CHARCODE(STR:=LEFT(tmp, end - 1));
				CODE := CHARCODE.CHARCODE;
				CHR_TO_STRING(C:=CODE);
				HTML_DECODE := REPLACE(HTML_DECODE, CHR_TO_STRING.CHR_TO_STRING, end + 1, pos);
			END_IF;
		END_IF;
		FINDP(str:=HTML_DECODE,src:='&',pos:=pos + 1);
		pos := FINDP.FINDP;
	END_WHILE;

END_FUNCTION_BLOCK

FUNCTION_BLOCK HTML_ENCODE

	VAR_INPUT
		IN :	oscat_STRING250;
		M :	BOOL;
	END_VAR


	VAR_OUTPUT
		HTML_ENCODE :	oscat_STRING250;
	END_VAR


	VAR
		pt_out :	oscat_aB1_255;
		pos_in :	INT;
		pos_out :	INT;
		stop :	INT;
		B :	INT;
		tmp :	oscat_STRING10;
		i :	INT;
		BUF_TO_STRING :	BUF_TO_STRING;
		CHARNAME :	CHARNAME;
		CODE :	CODE;
	END_VAR

	pos_in := 1;
	stop := LEN(in);
	FOR pos_out := 1 TO 250 DO
		IF pos_in > stop THEN EXIT; END_IF;
		B := GET_CHAR(IN,pos_in);
		CASE B OF
			34: 
				IF pos_out > 244 THEN EXIT; END_IF;
				pt_out[pos_out] := BYTE#38;
				pos_out := pos_out + 1;
				pt_out[pos_out] := BYTE#113;
				pos_out := pos_out + 1;
				pt_out[pos_out] := BYTE#117;
				pos_out := pos_out + 1;
				pt_out[pos_out] := BYTE#111;
				pos_out := pos_out + 1;
				pt_out[pos_out] := BYTE#116;
				pos_out := pos_out + 1;
				pt_out[pos_out] := BYTE#59;
			38:
				IF pos_out > 245 THEN EXIT; END_IF;
				pt_out[pos_out] := BYTE#38;
				pos_out := pos_out + 1;
				pt_out[pos_out] := BYTE#97;
				pos_out := pos_out + 1;
				pt_out[pos_out] := BYTE#109;
				pos_out := pos_out + 1;
				pt_out[pos_out] := BYTE#112;
				pos_out := pos_out + 1;
				pt_out[pos_out] := BYTE#59;
			60: 
				IF pos_out > 246 THEN EXIT; END_IF;
				pt_out[pos_out] := BYTE#38;
				pos_out := pos_out + 1;
				pt_out[pos_out] := BYTE#108;
				pos_out := pos_out + 1;
				pt_out[pos_out] := BYTE#116;
				pos_out := pos_out + 1;
				pt_out[pos_out] := BYTE#59;
			62:
				IF pos_out > 246 THEN EXIT; END_IF;
				pt_out[pos_out] := BYTE#38;
				pos_out := pos_out + 1;
				pt_out[pos_out] := BYTE#103;
				pos_out := pos_out + 1;
				pt_out[pos_out] := BYTE#116;
				pos_out := pos_out + 1;
				pt_out[pos_out] := BYTE#59;
		ELSE
			IF M AND B > 127 THEN
				CHARNAME(C:=INT_TO_BYTE(B));
				tmp := CHARNAME.CHARNAME;
				IF pos_out + LEN(tmp) + 2 <= 250 THEN
					pt_out[pos_out] := BYTE#38;
					pos_out := pos_out + 1;
					FOR i := 1 TO LEN(tmp) DO
						CODE(STR:=tmp,POS:=i);
						pt_out[pos_out] := CODE.CODE;
						pos_out := pos_out + 1;
					END_FOR;
					pt_out[pos_out] := BYTE#59;
				END_IF;
			ELSE
			pt_out[pos_out] := INT_TO_BYTE(B);
			END_IF;
		END_CASE;
		pos_in := pos_in + 1;
	END_FOR;

	pos_out := pos_out - 1;

	FOR pos_in := 0 TO 1 DO
	BUF_TO_STRING.REQ        := pos_in>0;
	BUF_TO_STRING.BUF_FORMAT := TRUE;
	BUF_TO_STRING.BUF_OFFS   := DINT#0;
	BUF_TO_STRING.BUF_CNT    := INT_TO_DINT(pos_out);
	BUF_TO_STRING.BUFFER     := pt_out;
	BUF_TO_STRING.DST        := HTML_ENCODE;
	BUF_TO_STRING();
	pt_out  := BUF_TO_STRING.BUFFER;
	HTML_ENCODE := BUF_TO_STRING.DST;
	END_FOR;

END_FUNCTION_BLOCK

