FUNCTION_BLOCK HYST_Block

	VAR_INPUT
		IN :	REAL;
		_ON :	REAL;
		OFF :	REAL;
	END_VAR


	VAR_OUTPUT
		Q :	BOOL;
		WIN :	BOOL;
	END_VAR

	IF _ON >= OFF THEN
		IF IN < OFF THEN
			Q := FALSE;
			WIN := FALSE;
		ELSIF  IN > _ON THEN
			Q := TRUE;
			WIN := FALSE;
		ELSE
			WIN := TRUE;
		END_IF;
	ELSE
		IF IN > OFF THEN
			Q := FALSE;
			WIN := FALSE;
		ELSIF  IN < _ON THEN
			Q := TRUE;
			WIN := FALSE;
		ELSE
			WIN := TRUE;
		END_IF;
	END_IF;

END_FUNCTION_BLOCK

