		I1 :	BOOL;
		I2 :	BOOL;
		I3 :	BOOL;
		E :	BOOL;
		MODE :	INT;
		OUT :	BYTE;
		_TP :	BOOL;
		func_block : INTERLOCK_4_Block;
	END_VAR
	func_block.I0 := I0;
