	END_VAR

	IF NOT IP_C.C_ENABLE THEN
		IP_C.C_PORT := WORD#0; 
		IP_C.C_IP := DWORD#00; 
		IP_C.C_MODE := SEL(UDP_TCP,BYTE#5,BYTE#4);
