	R_ENABLE := IP_C.C_STATE > BYTE#127;
	S_ENABLE := R_ENABLE AND (IP_C.MAILBOX[1] > BYTE#0 OR IP_C.C_MODE <> BYTE#5);
	ERROR := IP_C.ERROR;

	t(IN:= IP_C.ERROR > DWORD#0, PT:=T#5s);
	IF t.Q THEN
		IP_C.TIME_RESET := TRUE;
	END_IF;

