	VAR
		X :	REAL;
		LAMBERT_W :	REAL;
		func_block : LAMBERT_W_Block;
	END_VAR
	func_block.X := X;
	func_block();
	LAMBERT_W := func_block.LAMBERT_W;

END_PROGRAM

