	VAR
		IP_C :	oscat_IP_C;
		S_BUF :	oscat_NETWORK_BUFFER_SHORT;
		R_BUF :	oscat_NETWORK_BUFFER_SHORT;
		VMAP :	oscat_MB_VMAP;
		DATA :	oscat_aW0_255;
		DATA_SIZE :	INT;
