		block := DWORD_TO_UDINT(SHR_DWORD(UDINT_TO_DWORD(SIZE),6)) + BOOL_TO_UDINT((UDINT_TO_BYTE(SIZE) AND BYTE#16#3F) > BYTE#55);	
		pad_1 := FALSE;
		POS := UDINT#0;
		End := SIZE;
		SIZE := MIN(UDINT#64,end);
		MODE := 2;

