		MN :	INT;
		TR :	BOOL;
	END_VAR


	VAR
		timer :	TON;
		edge :	BOOL;
	END_VAR

	TR := FALSE;
	IF ENQ THEN
		IF (NOT edge AND clk) OR timer.q THEN
				MN := INC1(MN, MM);
