		IN3 :	BOOL;
		IN4 :	BOOL;
		IN5 :	BOOL;
		IN6 :	BOOL;
		IN7 :	BOOL;
		IN8 :	BOOL;
	END_VAR


	VAR_OUTPUT
		OUT1 :	BOOL;
