FUNCTION_BLOCK NET_VAR_DWORD8_Block

	VAR_INPUT
		IN1 :	DWORD;
		IN2 :	DWORD;
		IN3 :	DWORD;
		IN4 :	DWORD;
		IN5 :	DWORD;
		IN6 :	DWORD;
		IN7 :	DWORD;
		IN8 :	DWORD;
	END_VAR


	VAR_OUTPUT
		OUT1 :	DWORD;
