	END_VAR

	VAR
		tmp :	STRING;
		a :	INT;
		b :	INT;
		c :	STRING;
		stp :	INT;
	END_VAR


	REPLACE_CHARS := STR;

	a := LEN(src);
	b := LEN(rep);
	IF a < b THEN
		rep := LEFT(rep, a);
	ELSIF b < a THEN
		src := LEFT(src, b);
	END_IF;

	stp := LEN(str);
	FOR a := 1 TO stp DO
		c := MID(REPLACE_CHARS, 1, a);
		b := FIND(src, c);
		IF b > 0 THEN
			tmp := MID(rep, 1, b);
			REPLACE_CHARS := REPLACE(REPLACE_CHARS, tmp, 1, a);
		END_IF;
	END_FOR;

