		init :	BOOL;
		last_dir :	BOOL;
		start :	BYTE;
	END_VAR


	T_PLC_MS();
	tx := UDINT_TO_TIME(T_PLC_MS.T_PLC_MS);

	IF E AND init AND (dir = last_dir) AND (RMP <> SEL(DIR, BYTE#0, BYTE#255)) AND TR = tn THEN
		RMP := FRMP_B(start, DIR, tx - tl, TR);
	ELSE
		init := TRUE;
		tl := tx;
		tn := tr;
		start := RMP;
	END_IF;
	last_dir := dir;
END_FUNCTION_BLOCK

FUNCTION_BLOCK RMP_SOFT_Block

	VAR_INPUT
		IN :	BOOL;
		VAL :	BYTE;
		PT_ON :	TIME := T#100ms;
		PT_OFF :	TIME := T#100ms;
	END_VAR

	VAR_OUTPUT
		OUT :	BYTE := BYTE#00;
	END_VAR


	VAR
		rmp :	_RMP_B;
		tmp :	BYTE;
	END_VAR


	tmp := SEL(in, BYTE#0, val);
	IF tmp > out THEN
		(* we need to ramp down *)
		rmp(dir := TRUE, E := TRUE, TR := PT_ON, RMP := out);
		out := rmp.RMP; 
		(* make sure out does not surpass tmp *)
		out := MIN(out, tmp);
	ELSIF tmp < out THEN
		(* we need to ramp up *)
		rmp(dir := FALSE, E := TRUE, TR := PT_OFF, RMP := out);
		out := rmp.RMP; 
		(* make sure out does not surpass tmp *)
		out := MAX(out, tmp);
	ELSE
		(* no ramp necessary *)
		rmp(E := FALSE, RMP := out);
		out := rmp.RMP; 
	END_IF;


END_FUNCTION_BLOCK


