FUNCTION_BLOCK SCHEDULER_2_Block

	VAR_INPUT
		E0 :	BOOL;
		E1 :	BOOL;
		E2 :	BOOL;
		E3 :	BOOL;
		C0 :	UINT;
		C1 :	UINT;
		C2 :	UINT;
		C3 :	UINT;
		O0 :	UINT;
		O1 :	UINT;
