TYPE
  oscat_aB0_19	: ARRAY [0..19]	OF BYTE;
  oscat_aB0_63	: ARRAY [0..63]	OF BYTE;
  oscat_aDW0_4	: ARRAY [0..4] 	OF DWORD;
  oscat_sDW0_79	: ARRAY [0..79] OF DWORD;
oscat_STRING250             : STRING;
END_TYPE

FUNCTION DWORD_OF_BYTE:DWORD
	VAR_INPUT
		B3 :	BYTE;
		B2 :	BYTE;
		B1 :	BYTE;
		B0 :	BYTE;
	END_VAR

	DWORD_OF_BYTE := SHL(SHL(SHL(BYTE_TO_DWORD(B3),8) OR BYTE_TO_DWORD(B2),8) OR BYTE_TO_DWORD(B1),8) OR BYTE_TO_DWORD(B0);

END_FUNCTION

FUNCTION_BLOCK SHA1_STREAM_Block

	VAR_IN_OUT
		MODE :	INT;
		BUF :	oscat_aB0_63;
		SHA1 :	oscat_aB0_19;
		SIZE :	UDINT;
	END_VAR


	VAR_OUTPUT
		POS :	UDINT;
	END_VAR


	VAR
		hash :	oscat_aDW0_4;
		end :	UDINT;
		block :	UDINT;
		pad_1 :	BOOL;
		w :	oscat_sDW0_79;
		n :	INT;
		n1 :	INT;
		n2 :	INT;
		n3 :	INT;
		n4 :	INT;
		a :	DWORD;
		b :	DWORD;
		c :	DWORD;
		d :	DWORD;
		e :	DWORD;
		f :	DWORD;
		k :	DWORD;
		x :	DWORD;
	END_VAR

	CASE MODE OF

	1:	
		hash[0] := DWORD#16#67452301;
		hash[1] := DWORD#16#EFCDAB89;
		hash[2] := DWORD#16#98BADCFE;
		hash[3] := DWORD#16#10325476;
		hash[4] := DWORD#16#C3D2E1F0;

		FOR n := 16 TO 79 DO
			w[n] := DWORD#0;
		END_FOR;

		block := DWORD_TO_UDINT(SHR(UDINT_TO_DWORD(SIZE),6)) + BOOL_TO_UDINT((UDINT_TO_BYTE(SIZE) AND BYTE#16#3F) > BYTE#55);

		pad_1 := FALSE;
		POS := UDINT#0;
		End := SIZE;
		SIZE := MIN(UDINT#64,End);
		MODE := 2;

	2:	FOR n := UDINT_TO_INT(SIZE) TO 63 DO
			BUF[n] := BYTE#0;
		END_FOR;

		IF SIZE < UDINT#64 AND NOT pad_1 THEN
			BUF[SIZE] := BYTE#2#1000_0000;
			pad_1 := TRUE;
		END_IF;

		POS := POS + SIZE;
		SIZE := MIN(UDINT#64,End - POS);

		n := 0;	
		FOR n4 := 0 TO 15 DO
			n1 := n + 1;
			n2 := n + 2;
			n3 := n + 3;
			w[n4] := DWORD_OF_BYTE(BUF[n],BUF[n1],BUF[n2],BUF[n3]);
			n := n + 4;
		END_FOR;

		IF block = UDINT#0 THEN
			w[15] := SHL(UDINT_TO_DWORD(End),3);
			MODE := 3;
		ELSE
			block := block - UDINT#1;
		END_IF;

		FOR n := 16 TO 79 DO 
			n1 := n - 3;
			n2 := n - 8;
			n3 := n - 14;
			n4 := n - 16;
			w[n] := ROL(w[n1] XOR w[n2] XOR w[n3] XOR w[n4],1);
		END_FOR;

		a := hash[0];
		b := hash[1];
		c := hash[2];
		d := hash[3];
		e := hash[4];

		FOR n := 0 TO 79 DO
			IF n <= 19 THEN
				f := (b AND c) OR (NOT(b) AND d);
				k := DWORD#16#5A827999;
			ELSIF n <= 39 THEN
				f := b XOR c XOR d;
				k := DWORD#16#6ED9EBA1;
			ELSIF n <= 59 THEN
				f := (b AND c) OR (b AND d) OR (c AND d);
				k := DWORD#16#8F1BBCDC;
			ELSE
				f := b XOR c XOR d;
				k := DWORD#16#CA62C1D6;
			END_IF;

			x := UDINT_TO_DWORD(DWORD_TO_UDINT(ROL(a,5)) + DWORD_TO_UDINT(f) + DWORD_TO_UDINT(e) + DWORD_TO_UDINT(k) + DWORD_TO_UDINT(w[n]));
			e := d;
			d := c;
			c := ROL(b,30);
			b := a;
			a := x;
		END_FOR;

		hash[0] := UDINT_TO_DWORD(DWORD_TO_UDINT(hash[0]) + DWORD_TO_UDINT(a));
		hash[1] := UDINT_TO_DWORD(DWORD_TO_UDINT(hash[1]) + DWORD_TO_UDINT(b));
		hash[2] := UDINT_TO_DWORD(DWORD_TO_UDINT(hash[2]) + DWORD_TO_UDINT(c));
		hash[3] := UDINT_TO_DWORD(DWORD_TO_UDINT(hash[3]) + DWORD_TO_UDINT(d));
		hash[4] := UDINT_TO_DWORD(DWORD_TO_UDINT(hash[4]) + DWORD_TO_UDINT(e));

	END_CASE;

	IF MODE = 3 THEN
		n2 := 0;
		FOR n := 0 TO 4 DO
			FOR n1 := 0 TO 3 DO
				hash[n] := ROL(hash[n],8);
				SHA1[n2] := DWORD_TO_BYTE(hash[n]);
				n2 := n2 + 1;
			END_FOR;
		END_FOR;
	END_IF;

END_FUNCTION_BLOCK

FUNCTION_BLOCK SHA1_STR_Block

	VAR_INPUT
		RUN :	BOOL;
	END_VAR


	VAR_OUTPUT
		DONE :	BOOL;
	END_VAR


	VAR_IN_OUT
		STR :	oscat_STRING250;
		SHA1 :	oscat_aB0_19;
	END_VAR


	VAR
		run_last :	BOOL;
		SHA1_STREAM :	SHA1_STREAM_Block;
		buf :	oscat_aB0_63;
		mode :	INT;
		size :	UDINT;
		pos :	UDINT;
		i :	INT;
		i2 :	INT;
		CODE :	CODE;
	END_VAR

	CASE mode OF
	0:	
		IF RUN AND NOT run_last THEN
			DONE := FALSE;
			mode := 1; 
			size := INT_TO_UDINT(LEN(STR));
		END_IF;

	2:	
		IF size > UDINT#0 THEN
			i2 := 0;
			FOR i := 1 TO UDINT_TO_INT(SIZE) DO
				CODE(STR:=MID(STR,1,UDINT_TO_INT(POS) + i),POS:=1);
				buf[i2] := CODE.CODE;
				i2 := i2 + 1;
			END_FOR;
		END_IF;

	3:	DONE := TRUE;
		mode := 0; 

	END_CASE;

	IF mode > 0 THEN
		SHA1_STREAM(MODE:=mode, BUF:=buf, SHA1:=SHA1, SIZE:=size);
		mode := SHA1_STREAM.MODE;
		buf := SHA1_STREAM.BUF;
		SHA1 := SHA1_STREAM.SHA1;
		size := SHA1_STREAM.SIZE;
		pos := SHA1_STREAM.POS;
	END_IF;

	run_last := RUN;

END_FUNCTION_BLOCK

