FUNCTION_BLOCK SH_2_Block

	VAR_INPUT
		IN :	REAL;
		PT :	TIME;
		N :	INT := INT#16;
		DISC :	INT;
	END_VAR


	VAR_OUTPUT
		OUT :	REAL;
		TRIG :	BOOL;
		AVG :	REAL;
		HIGH :	REAL;
		LOW :	REAL;
	END_VAR

	VAR
		M :	INT;
		buf :	oscat_arr_0_15;
		buf2 :	oscat_arr_0_15;
		last :	TIME;
		i :	INT;
		I2 :	INT;
		start :	INT;
		temp :	REAL;
		stop :	INT;
		tx :	TIME;
		d2 :	INT;
		T_PLC_MS :	T_PLC_MS_Block;
	END_VAR


	T_PLC_MS();
	tx:= UDINT_TO_TIME(T_PLC_MS.T_PLC_MS);
	d2 := WORD_TO_INT(SHR(INT_TO_WORD(disc),1));

	IF tx - last >= PT THEN
		last := tx;
		trig := TRUE;

		M := LIMIT(1,N,16);

		i := M-1;
		WHILE (i>=1) DO
		i2 := i-1;
		buf2[i] := buf2[i2];
		i:=i-1;
		END_WHILE;

		buf2[0] := in;
		out := in;
		buf := buf2;

		(* sort the ARRAY lowest value AT 0 *)
		FOR start := 0 TO M - 2 DO
			FOR i := start+1 TO M - 1 DO
				IF buf[start] > buf[i] THEN
					temp := buf[start];
					buf[start] := buf[i];
					buf[i] := temp;
				END_IF;
			END_FOR;
		END_FOR;

		stop := M - 1 - d2;
		start := d2;
		IF NOT even(INT_TO_DINT(disc)) THEN start := start + 1; END_IF;
		avg := 0.0;
		FOR i := start TO stop DO avg := avg + buf[i]; END_FOR;
		avg := avg / INT_TO_REAL(stop - start +1);
		low := buf[start];
		high := buf[stop];
	ELSE
		Trig := FALSE;
	END_IF;
END_FUNCTION_BLOCK

