FUNCTION_BLOCK TMIN


	VAR_INPUT
		IN :	BOOL;
		PT :	TIME;
	END_VAR


	VAR_OUTPUT
		Q :	BOOL;
	END_VAR


	VAR
		pm :	TP;
	END_VAR

	pm(in := IN, PT := PT);
	Q := IN OR pm.Q;

END_FUNCTION_BLOCK

PROGRAM program0
