    FB_FIX.L:=LEN(Xus_TN_INPUT_CONTROL_DATA.st_Input_Mask);
    FB_FIX.C:=BYTE#32;
    FB_FIX.M:=Xus_TN_INPUT_CONTROL_DATA.in_Input_Option;
      FB_FIX();
