    Xus_TN_INPUT_CONTROL_DATA.in_Cursor_X := Xus_TN_INPUT_CONTROL_DATA.in_X;

    Xus_TN_INPUT_CONTROL_DATA.bo_Update_All   := FALSE;
    Xus_TN_INPUT_CONTROL_DATA.bo_Update_Input := FALSE;

  END_IF;

