	FB_FIX.str:=Ist_STRING;
	FB_FIX.L:=Iin_LENGTH;
	FB_FIX.C:=BYTE#32;
	FB_FIX.M:=Iin_OPTION;
	FB_FIX();

	FB_TN_SC_WRITE.Iin_Y			:= Iin_Y;
