FUNCTION_BLOCK TO_UML_Block

	VAR_INPUT
		IN :	BYTE;
	END_VAR


	VAR_OUTPUT
		TO_UML :	STRING;
	END_VAR

	CASE _BYTE_TO_INT(in) OF
		196:
			TO_UML := 'Ae';
		214:
			TO_UML := 'Oe';
		220:
			TO_UML := 'Ue';
		223:
			TO_UML := 'ss';
		228:
			TO_UML := 'ae';
		246:
			TO_UML := 'oe';
		252:
