FUNCTION_BLOCK TREND



	VAR_INPUT
		X :	REAL;
	END_VAR


	VAR_OUTPUT
		Q :	BOOL;
		TU :	BOOL;
		TD :	BOOL;
		D :	REAL;
	END_VAR


