	VAR
		pos :	INT;
		new :	STRING;
		HEX_TO_DWORD :	HEX_TO_DWORD_Block;
	END_VAR

	URL_DECODE := IN;
	pos := FIND(URL_DECODE,'%');
	WHILE pos > 0 DO
		HEX_TO_DWORD(Hex:=MID(URL_DECODE,2,pos + 1));
		new := BYTE_TO_STRING(DWORD_TO_BYTE(HEX_TO_DWORD.HEX_TO_DWORD),'%c');
		URL_DECODE := REPLACE(URL_DECODE, new, 3, pos);
		pos := FIND(URL_DECODE,'%');
	END_WHILE;

