	VAR_IN_OUT
		PT :	oscat_NW_BUF_LONG;
	END_VAR

	VAR
		pos :	INT;
		size2 :	INT;
	END_VAR

	pos := 0;
	size2 := UINT_TO_INT(SIZE);

	WHILE pos < size2 DO
		PT[pos] := TO_UPPER(PT[pos]);
		pos := pos + 1;
	END_WHILE;

	_BUFFER_UPPERCASE := TRUE;

END_FUNCTION_BLOCK

