FUNCTION_BLOCK TREND_DW
	VAR_INPUT
		X :	DWORD;
	END_VAR
	VAR_OUTPUT
		Q :	BOOL;
		TU :	BOOL;
		TD :	BOOL;
		D :	DWORD;
	END_VAR

	VAR
		LAST_X :	DWORD;
	END_VAR

	IF X > last_X THEN
		TU := TRUE;
		TD := FALSE;
		D := UDINT_TO_DWORD(DWORD_TO_UDINT(X) - DWORD_TO_UDINT(last_X));
		Q := TRUE;
	ELSIF X < last_X THEN
		TD := TRUE;
		TU := FALSE;
		D := UDINT_TO_DWORD(DWORD_TO_UDINT(last_X) - DWORD_TO_UDINT(X));
		Q := FALSE;
	ELSE
		TU := FALSE;
		TD := FALSE;
		D := DWORD#0;
	END_IF;
	last_X := X;
END_FUNCTION_BLOCK

FUNCTION_BLOCK _RMP_NEXT
	VAR_INPUT
		E :	BOOL := TRUE;
		IN :	BYTE;
		TR :	TIME;
		TF :	TIME;
		TL :	TIME;
	END_VAR

	VAR_OUTPUT
		DIR :	BOOL;
		UP :	BOOL;
		DN :	BOOL;
	END_VAR

	VAR_IN_OUT
		OUT :	BYTE;
	END_VAR
	VAR
		rmx :	_RMP_B;
		dirx :	TREND_DW;
		t_lock :	TP;
		xen :	BOOL;
		xdir :	BOOL;
	END_VAR

	dirx(X := BYTE_TO_DWORD(in));

	t_lock(in := FALSE, pt := TL);

	IF dirx.TU AND (OUT < IN) THEN
		IF NOT xdir AND xen THEN t_lock(in := TRUE); END_IF;
		xen := TRUE;
		xdir := TRUE;
	ELSIF dirx.TD AND (OUT > IN) THEN
		IF xdir AND xen THEN t_lock(in := TRUE); END_IF;
		xen := TRUE;
		xdir := FALSE;
	ELSIF xen THEN
		IF (xdir AND (out >= in)) OR (NOT xdir AND (out <= in)) THEN
			xen := FALSE;
			IF tl > t#0s THEN t_lock(IN := TRUE); END_IF;
		END_IF;
	END_IF;

	IF NOT t_lock.Q AND xen THEN
		UP := XDIR;
		DIR := XDIR;
		DN := NOT XDIR;
	ELSE
		UP := FALSE;
		DN := FALSE;
	END_IF;

	rmx(rmp := OUT, E := E AND (UP OR DN) , dir := DIR, tr := SEL(dir, TF, TR));
	OUT := rmx.RMP;
END_FUNCTION_BLOCK

